window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-24"]={"block":"med:med-clinica-medica-med-clm-24","label":"MED · MED CLM 24","count":484,"questions":[{"id":"med-clinica-medica-med-clm-24-345439","number":"345439","sourceNumber":"345439","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre o uso de vasopressores durante o atendimento de uma parada\ncardiorrespiratória (PCR) em paciente adulto,\nassinale a afirmativa CORRETA, de acordo com as\nrecomendações da American Heart Association:","options":{"A":"É razoável que se administre epinefrina para todos os pacientes com PCR, na dose de 01mg,\ncom intervalo de 02 minutos entre cada dose.","B":"Durante uma PCR em Atividade Elétrica sem Pulso (AESP), é recomendado que se administre\nepinefrina assim que possível.","C":"Paciente com PCR em Fibrilação Ventricular (FV) deve receber adrenalina logo após a\nrealização da primeira tentativa de desfibrilação.","D":"O uso de vasopressina em substituição à primeira ou segunda dose de adrenalina deve ser feito\nsempre que disponível, já que apresenta melhores desfechos em comparação ao uso apenas de\nadrenalina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-343854","number":"343854","sourceNumber":"343854","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Qual diagnóstico eletrocardiográfico (D2) da arritmia na figura abaixo?","options":{"A":"Fibrilação atrial","B":"Taquicardia paroxística supraventricular","C":"Flutter atrial com bloqueio AV variável","D":"Taquicardia ventricular"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-283271","number":"283271","sourceNumber":"283271","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 25 anos chega à emergência referindo dor torácica de forte intensidade,\nassociada à taquicardia e palpitações. O\neletrocardiograma evidenciou taquicardia sinusal com\ncomplexo QRS estreito, encurtamento do intervalo PR e supra desnivelamento de seguimento ST,\nsendo que a investigação enzimática não mostrou elevação de marcadores de necrose miocárdica.\nEm relação aos diagnósticos possíveis, assinale a alternativa CORRETA.","options":{"A":"Síndrome de Brugada.","B":"Síndrome de Wolff-Parkinson-White.","C":"Fibrilação atrial aguda.","D":"Flutter atrial."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-281110","number":"281110","sourceNumber":"281110","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 59 anos, sexo masculino, chega ao ambulatório para consulta médica de\nrotina quando apresenta quadro súbito de inconsciência, associado a ausência de pulso e\nrespiração. Nesse momento, recomenda-se ao profissional de saúde, chamar ajuda e realizar:","options":{"A":"15 compressões, intercaladas com 05 ventilações.","B":"15 compressões, intercaladas com 02 ventilações.","C":"90 compressões por minuto, apenas.","D":"30 compressões, intercaladas com 05 ventilações.","E":"30 compressões, intercaladas com 02 ventilações."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-281119","number":"281119","sourceNumber":"281119","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O achado ocasional ao eletrocardiograma de amplitude e forma na onda \"p\", em\npaciente jovem, chama atenção para eventuais problemas:","options":{"A":"Ventrículares.","B":"No ventrículo direito.","C":"Na despolarização ventricular.","D":"Atriais.","E":"De bloqueio de ramos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-283367","number":"283367","sourceNumber":"283367","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente masculino, 65 anos, apresenta diagnóstico de hipertensão arterial há 8 anos,\nfazendo uso regular de enalapril e anlodipino. Há uma semana passou a apresentar queixa de\npalpitações e fadiga fácil, tendo sido solicitado um eletrocardiograma, que mostrou taquicardia\nsupraventricular, FC= 135 bpm, sem sinais de isquêmica miocárdica. O exame físico do paciente é\nnormal, exceto pela taquicardia, PA - 126X80 mmHg. Assinale dentre as alternativas abaixo, a\nmelhor conduta neste caso:","options":{"A":"Substituição da anlodipina pelo diltiazem.","B":"Acréscimo da furosemida.","C":"Aumento da dose do enalapril.","D":"Acréscimo da espironolactona."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-182678","number":"182678","sourceNumber":"182678","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente inconsciente, não responsivo, com ausência de pulso carotídeo e com o\nseguinte traçado no monitor cardíaco: Qual a próxima medida terapêutica no atendimento de\nurgência?","options":{"A":"Desfibrilação imediata com 200 joules.","B":"Verificar cargas, ganhos e derivações da monitorização.","C":"Pedir ajuda a outros membros da equipe de saúde e iniciar imediatamente o Suporte Básico de\nVida.","D":"Acesso venoso imediato e epinefrina endovenosa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-159034","number":"159034","sourceNumber":"159034","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente 67 anos, com 100 kg, hipertenso e diabético, adentra a emergência do\npronto-socorro com dor torácica irradiando\npara mandíbula há 1 hora. Após o atendimento inicial,\npaciente apresentou parada cardiorrespiratória em fibrilação ventricular identificada pelo monitor\ncardíaco. A conduta mais adequada será utilizar:","options":{"A":"O desfibrilador monofásico com carga de 200 J.","B":"100 mg de lidocaína endovenosa.","C":"O desfibrilador bifásico com carga de 200 J.","D":"Amiodarona 300 mg endovenosa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-135917","number":"135917","sourceNumber":"135917","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 5 anos de idade, procedente da zona rural, prostrado há 15 dias, lúcido e\norientado no tempo e espaço, em regular estado geral, pálido ++, enchimento capilar de 2\nsegundos, taquipneico, desconforto precordial inespecífico, frequência respiratória de 53 irpm.\n\nAusculta cardíaca com ritmo cardíaco regular em 2 tempos e sopro sistólico 3+/6+, audível na\nborda esternal baixa, na região de foco mitral\nirradiado à região axilar esquerda, principalmente na\nlaterização do paciente. Também houve relato de dificuldade para deambular, astenia, febre baixa,\nfraqueza e dor muscular generalizada. O eletrocardiograma demonstrou sobrecarga ventricular\nesquerda e discreto aumento do intervalo PR. O RX de tórax evidenciou aumento importante da\nárea cardíaca e sinais de hiperfluxo pulmonar. Qual a hipótese diagnóstica?","options":{"A":"Doença de Kawasaki;","B":"Cardite reumática;","C":"Comunicação interventricular;","D":"Persistência do canal arterial;"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-108691","number":"108691","sourceNumber":"108691","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação à Febre Reumática pode-se AFIRMAR:","options":{"A":"Complicação tardia de uma infecção estreptocócica, que se manifesta com sinais e sintomas\nclínicos e laboratoriais específicos como cardite, coreia, artrite aguda, dentre outros.","B":"Apresenta-se comumente com um quadro de artrite, em que se pode isolar o estreptococo no\nlíquido sinovial e cardite indolente.","C":"Não se configura um problema de saúde pública, pois não acarreta gastos para o sistema de\nsaúde.","D":"Seu tratamento baseia-se somente na erradicação dos estreptococos da orofaringe do paciente."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-84460","number":"84460","sourceNumber":"84460","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Criança do sexo masculino, nove anos, procedente de Mâncio Lima, município do Acre,\ncom história de cansaço aos grandes e médios esforços, iniciado há três meses. Ausculta cardíaca\nevidenciando sopro sistólico em foco mitral 3+/6+. Foi encaminhado ao cardiologista pediatra por\nsuspeita de cardiopatia reumática. Assinale a alternativa INCORRETA:","options":{"A":"A suspeita de febre reumática deve ser baseada em evidência de infecção estreptocócica\nanterior (elevação dos títulos da ASLO), além de\npelo menos dois critérios maiores ou um critério\nmaior e dois menores.","B":"São considerados critérios maiores: cardite, artrite, coreia de Sydenham, eritema marginado e\nnódulos subcutâneos.","C":"São considerados critérios menores: febre, artralgia, elevação dos reagentes de fase aguda\n(VHS e PCR) e aumento do intervalo PR no\neletrocardiograma.","D":"A evidência de infecção pelo estreptococo do grupo A pode ser feita por meio de cultura de\norofaringe, teste rápido para EBGA, elevação dos títulos de anticorpos (ASLO).","E":"O uso da penicilina benzatina só deve ser realizado na presença de cardite reumática."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-66946","number":"66946","sourceNumber":"66946","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale qual o MELHOR ESQUEMA TERAPÊUTICO para a profilaxia secundária da\nFebre Reumática segundo as Diretrizes Brasileiras de Febre Reumática (2009).","options":{"A":"Penicilina Procaína 400.000 UI de 21/21 dias;","B":"Penicilina Benzatina 1.200.000 UI independente do peso corporal, de 21/21 dias;","C":"Penicilina Benzatina 1.200.000 UI para peso corporal \"maior ou igual a\" 20 Kg e 600.000 UI para\npeso corporal < 20 Kg;","D":"Penicilina Benzatina 1.200.00 independente do peso corporal de 28/28 dias."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-66949","number":"66949","sourceNumber":"66949","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale a MELHOR ALTERNATIVA para fazer o diagnóstico da Febre Reumática:","options":{"A":"Critérios de Jones;","B":"Critérios de Duke;","C":"Critérios do Colégio Americano de Reumatologia;","D":"Ecocardiograma com Collor doppler;"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-66942","number":"66942","sourceNumber":"66942","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente com edema de tecido mole de três ou mais articulações das mãos, com\nrigidez matinal \"maior ou igual a\" 1 hora,\nnódulos subcutâneos e erosões e/ou osteopenia\nperiarticular nas articulações de mãos e punhos. Qual teste laboratorial é encontrado em 70% dos\npacientes, tem alta especificidade e está frequentemente presente antes que a doença clínica seja\ndiagnosticada?","options":{"A":"FAN;","B":"Fator Reumatoide;","C":"Anti-CCP (Ac Antipeptídeo Citrulinado Cíclico);","D":"VHS;"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-37066","number":"37066","sourceNumber":"37066","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente feminina, 42 anos, branca, com artralgias de mãos, ombros e tornozelos há 3\nmeses, de intensidade crescente, apesar do uso de diclofenaco 50 mg 3x/dia. Refere limitações\ndo movimento por dor ao acordar durante aproximadamente 1 hora diariamente. Ao exame: bom\nestado geral, corada, afebril, sem lesões cutâneas, com aumento das articulações interfalangeanas\nproximais e metacarpofalangeanas de 2º e 3º dedos das duas mãos, sem desvios e com artrite de\ncotovelo direito e tornozelos. Restante do exame físico normal. De acordo com a principal hipótese\ndiagnóstica, qual a droga de escolha a ser introduzida no momento?","options":{"A":"Prednisona 1 mg/kg/dia, em doses divididas","B":"Azatioprina 1 mg/kg/dia, dose única","C":"Metotrexate 7,5 mg/semana","D":"Colchicina 0,5 g de 1/1 hora até passar a dor","E":"Corticosteroide intra-articular via punção"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-29360","number":"29360","sourceNumber":"29360","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Manifesta-se sob a forma de oligoartrite assimétrica de membros inferiores, com cultura\nde líquido sinovial estéril e associada ao\nHLA-B27 em cerca de 60% dos pacientes?","options":{"A":"Síndrome de Reiter","B":"Artrite enteropática","C":"Artrite psoriásica","D":"Artrite reumatoide","E":"Artrite séptica"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-343157","number":"343157","sourceNumber":"343157","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A classificação de acordo com sua duração em segundos da taquicardia sustentada\n(TVS) ou não sustentada (TVNS), está de\nacordo com o seguinte item correto:","options":{"A":"Se o período da arritmia for ou não superior a 90 s e/ou sem sintomas de instabilidade\nhemodinâmica.","B":"Se o período da arritmia for ou não inferior a 30 s e/ou sem sintomas de instabilidade\nhemodinâmica.","C":"Se o período da arritmia for ou não superior a 30 s e/ou sem sintomas de instabilidade\nhemodinâmica.","D":"Se o período da arritmia for ou não superior a 30 s e/ou sem considerar sintomas de\ninstabilidade hemodinâmica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-343164","number":"343164","sourceNumber":"343164","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"HMN, masculino de 57 anos, grande tabagista e obeso, analisando se ECG foi\nencontrado Sobrecarga Atrial Esquerda (SAE) com onda\nP com componente negativo aumentado\n(final lento e profundo) na derivação V1. Podemos indicar como correto que:","options":{"A":"A área da fase negativa de pelo menos 0,09 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta melhor\nsensibilidade que o critério isolado de duração aumentada.","B":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 11 mm2, constitui o\nÍndice de Morris, que apresenta melhor sensibilidade que o critério isolado de duração aumentada.","C":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta pior sensibilidade que o critério isolado de duração aumentada.","D":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta melhor sensibilidade que o critério isolado de duração aumentada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-343169","number":"343169","sourceNumber":"343169","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobrecarga Atrial Direita (SAD), está de acordo com o seguinte item correto:","options":{"A":"A onda P apresenta-se não apiculada com amplitude acima de 0,25 mV ou 2,5 mm.","B":"A onda P apresenta-se apiculada com amplitude acima de 0,25 mV ou 2,5 mm.","C":"A onda P apresenta-se apiculada com amplitude abaixo de 0,25 mV ou 2,5 mm.","D":"A onda P apresenta-se apiculada com amplitude acima de 0,25 mV ou 3,5 mm."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-313441","number":"313441","sourceNumber":"313441","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre as Arritmias em oncopediatria, assinale a alternativa incorreta.","options":{"A":"Os pacientes que serão submetidos a quimioterapias potencialmente cardiotóxicas devem\nrealizar um ECG prévio para diagnóstico, e fazer seguimento cardiológico pós-quimioterapia.","B":"Os pacientes que apresentarem alterações no ECG devem realizar a monitoração\neletrocardiográfica de 24 horas (Holter) e a\nmonitoração hemodinâmica contínua durante a\nquimioterapia.","C":"Na rotina do paciente que apresenta alterações eletrocardiográficas, deve-se incluir o ECG antes\nde cada novo ciclo de quimioterapia,\nespecialmente nos casos de usuários de ATO (trióxido de\narsênio).","D":"Nas arritmias de QT prolongado e torsades de pointes, deve-se realizar sulfato de magnésio na\ndose de 50 a 85mg/Kg em 30 minutos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-279028","number":"279028","sourceNumber":"279028","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Nas manobras de Ressuscitação Cardiopulmonar de Pacientes com Diagnóstico ou\nSuspeita de COVID-19, está correto que.","options":{"A":"Recomenda-se que tentativas de retorno do paciente para posição supina sejam executadas\ncom o mínimo de segurança ao despronar,\nevitando a desconexão do ventilador e o risco de\naerossolização. Se houver disponibilidade de pás adesivas do desfibrilador, deve?se colá-las em\nposição ântero posterior.","B":"Recomenda-se que tentativas de retorno do paciente para posição supina sejam executadas\ncom o máximo de segurança ao despronar,\npromovendo sempre a desconexão do ventilador e o\nrisco de aerossolização. Se houver disponibilidade de pás adesivas do desfibrilador, deve-se\ncolá-las em posição ântero posterior.","C":"Recomenda-se que tentativas de retorno do paciente para posição supina sejam executadas\ncom o máximo de segurança ao despronar,\nevitando a desconexão do ventilador e o risco de\naerossolização. Se houver disponibilidade de pás adesivas do desfibrilador, deve-se colá-las em\nposição ântero posterior.","D":"Recomenda-se que tentativas de retorno do paciente para posição supina sejam executadas\ncom o máximo de segurança ao despronar,\nevitando a desconexão do ventilador e o risco de\naerossolização. Se houver disponibilidade de pás adesivas do desfibrilador, nunca colá-las em\nposição ântero posterior."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-279031","number":"279031","sourceNumber":"279031","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A Parada Cardiorrespiratória (PCR) pode ser causada por quatro ritmos: FV, TVSP,\nAESP e Assistolia. A sobrevida depende da\nintegração do SBV, do Suporte Avançado de Vida em\nCardiologia (SAVC) e dos cuidados pós-ressuscitação. Sendo correto que:","options":{"A":"O atraso no início da administração de vasopressores para além dos primeiros 15 minutos de\nPCR, bem como a demora em instalar via aérea avançada, pode estar associado a pior\nprognóstico.","B":"O atraso no início da administração de vasopressores para além dos primeiros 5 minutos de\nPCR, bem como a demora em instalar via aérea avançada, pode estar associado a pior\nprognóstico.","C":"O atraso no início da administração de vasopressores para além dos primeiros 5 minutos de\nPCR, mas não a demora em instalar via aérea\navançada, pode estar associado à pior prognóstico.","D":"O atraso no início da administração de vasopressores para além dos primeiros 5 minutos de\nPCR, bem como a demora em instalar via aérea avançada, não pode estar associado à pior\nprognóstico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-278612","number":"278612","sourceNumber":"278612","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Há uma diminuição de 6% na taxa de metabolismo cerebral de oxigênio na redução da\ntemperatura corpórea a cada 1 °C. Indique o item com erro:","options":{"A":"O uso de hipotermia atua como estimulador das vias facilitadoras da morte cerebral e da\napoptose celular.","B":"Existe evidência de uma diminuição dos radicais livres durante o controle da temperatura.","C":"Há um bloqueio à ação intracelular da exposição às excitotoxina (acionadas pelo aumento do\ncálcio e do glutamato).","D":"Redução da resposta inflamatória na síndrome pós-PCR."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-279032","number":"279032","sourceNumber":"279032","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quando a monitorização com desfibrilador manual revela ritmo de FV/TVSP, assinale a\nalternativa correta.","options":{"A":"A prioridade deve ser a desfibrilação precoce, uma vez que não aumenta o sucesso do\nprognóstico.","B":"A prioridade deve ser a cardioversão precoce, uma vez que aumenta o sucesso do prognóstico.","C":"A prioridade deve ser a desfibrilação precoce, uma vez que reduz o sucesso do prognóstico.","D":"A prioridade deve ser a desfibrilação precoce, uma vez que aumenta o sucesso do prognóstico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-279033","number":"279033","sourceNumber":"279033","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quando da abordagem de Assistolia e Atividade Elétrica sem Pulso, podemos indicar\ncomo correto a alternativa:","options":{"A":"São ritmos em que a desfibrilação está indicada. Deve-se, então, promover RCP de alta\nqualidade, além de aplicar as drogas indicadas\ne procurar identificar e tratar as causas reversíveis.","B":"São ritmos em que a desfibrilação não está indicada. Deve-se, então, promover RCP de alta\nqualidade, além de aplicar as drogas indicadas e procurar identificar e tratar as causas\nreversíveis.","C":"São ritmos em que a desfibrilação não está indicada. Deve-se, então, promover RCP de alta\nqualidade, sem aplicar as drogas indicadas e procurar identificar e tratar as causas reversíveis.","D":"São ritmos em que a desfibrilação não está indicada. Deve-se, então, promover RCP de alta\nqualidade, além de aplicar as drogas indicadas e procurar identificar e não tratar as causas\nreversíveis."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-278084","number":"278084","sourceNumber":"278084","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O uso de escores de gravidade e sistemas de rastreamento e o disparo de códigos\namarelos:","options":{"A":"Permitem a detecção tardia de pacientes graves e podem otimizar o atendimento de eventuais\nPCRs.","B":"Permitem a detecção precoce de pacientes graves e podem otimizar o atendimento de eventuais\nPCRs.","C":"Permitem a detecção precoce de pacientes graves e não podem otimizar o atendimento de\neventuais PCRs.","D":"Não permitem a detecção precoce de pacientes graves e podem otimizar o atendimento de\neventuais PCRs."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-279034","number":"279034","sourceNumber":"279034","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O racional para o uso de vasopressores durante a RCP. Assinale a alternativa que se\nfundamenta sendo o item correto.","options":{"A":"Reduzir a pressão de perfusão coronariana, definida como a diferença entre a pressão aórtica e\na pressão no átrio direito, durante a fase de\nrelaxamento (descompressão) torácico.","B":"Aumentar a pressão de perfusão coronariana, definida como a diferença entre a pressão aórtica\ne a pressão no átrio esquerdo, durante a\nfase de relaxamento (descompressão) torácico.","C":"Aumentar a pressão de perfusão coronariana, definida como a diferença entre a pressão aórtica\ne a pressão no átrio direito, durante a fase\nde relaxamento (descompressão) torácico.","D":"Aumentar a pressão de perfusão coronariana, definida como a diferença entre a pressão aórtica\ne a pressão no átrio direito, durante a fase\nde contração (descompressão) torácico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249382","number":"249382","sourceNumber":"249382","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Para que ocorra uma melhoria nas estruturas e nos sistemas de saúde, que é um dos\npontos essenciais no sucesso do atendimento da Parada Cardiorrespiratória (PCR), sendo\ninadequado apenas:","options":{"A":"Criação de um sistema integrado com treinamento de pessoas.","B":"Auxílio de materiais de emergência.","C":"Transportes para um atendimento unificado.","D":"Disponibilidade de DEA em locais públicos com baixa movimentação de pessoas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249385","number":"249385","sourceNumber":"249385","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Atualização da Diretriz de Ressuscitação Cardiopulmonar e Cuidados Cardiovasculares\nde Emergência da Sociedade Brasileira de\nCardiologia ? 2019. Listamos abaixo itens referentes à\ncadeia de elos de sobrevivência diferenciadas no contexto de uma parada cardiorrespiratória (PCR)\nintra-hospitalar, determine o item que não pode ser considerado como parte da mesma:","options":{"A":"RCP imediata de alta qualidade.","B":"Rápida desfibrilação.","C":"Suporte básico de Vida.","D":"Cuidados pós-PCR."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249389","number":"249389","sourceNumber":"249389","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A Ressuscitação Cardiopulmonar e Cuidados Cardiovasculares inseridos nos Cuidados\npós-PCR, apresenta como importante ponto o item:","options":{"A":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom maior tolerância na variação de\ntemperatura e prevenção de febre.","B":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom menor variação de temperatura e prevenção\nde febre.","C":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom menor variação de temperatura e sem\nprevenção de febre.","D":"Ênfase na avaliação neurológica, sem o cumprimento das metas hemodinâmicas e controle\ntérmico, com menor variação de temperatura e prevenção de febre."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249393","number":"249393","sourceNumber":"249393","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A adequada abordagem de Ressuscitação Cardiopulmonar e Cuidados\nCardiovasculares com ênfase nos cuidados após o\nretorno à circulação espontânea trouxe\nmelhorias nos resultados, contribuído ao prognóstico dos pacientes. Podemos assim determinar\ncomo adequado que:","options":{"A":"O reconhecimento precoce das causas desencadeantes, orientando a intervenção para cada\ncenário clínico.","B":"O reconhecimento tardio das causas desencadeantes, orientando a intervenção para cada\ncenário clínico.","C":"O reconhecimento precoce das causas desencadeantes, desorientando a intervenção para cada\ncenário clínico.","D":"O reconhecimento precoce das causas desencadeantes, não orientando a intervenção para\ncada cenário clínico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249228","number":"249228","sourceNumber":"249228","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente feminina, 35 anos, sem comorbidades, admitida em leito de terapia intensiva\napós laparotomia exploradora por cisto de ovário\nroto. Após 12 horas de observação clínica,\napresenta dor torácica de forte intensidade, palpitações, associada à dispneia súbita. Nega\nvômitos. Permanece estável hemodinamicamente, sem alterações neurológicas. Realizado\neletrocardiograma abaixo. A conduta mais adequada neste caso é:","options":{"A":"Amiodarona 300 mg em bolus.","B":"Cardioversão elétrica.","C":"Amiodarona 150 mg em bolus.","D":"Metoprolol 25 mg via oral."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-216246","number":"216246","sourceNumber":"216246","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente que desenvolve Insuficiência Cardíaca - IC devido à Fibrilação atrial - FA, com\nresposta ventricular rápida (usualmente > 150 bpm), está ADEQUADO apenas que:","options":{"A":"Entidade denominada ?taquicardiomiopatia?, de prognóstico mais favorável com a correção da\nFA.","B":"Entidade denominada ?taquicardiomiopatia?, de prognóstico menos favorável com a correção da\nFA.","C":"Entidade não denominada ?taquicardiomiopatia?, de prognóstico mais favorável com a correção\nda FA.","D":"Entidade denominada ?cardiomiopatia?, de prognóstico mais favorável com a correção da FA."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-216263","number":"216263","sourceNumber":"216263","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Vários estudos documentaram a efetividade do Cardiversor desfibrilador implantável -\nCDI em reduzir o risco de morte súbita em pacientes de alto risco (prevenção secundária) quando\ncomparados às drogas antiarrítmicas. Sendo ADEQUADO que:","options":{"A":"Os estudos de prevenção secundária contemplaram, em sua maioria, pacientes portadores de\nmiocardiopatia de etiologia isquêmica, que foram recuperados de morte súbita ou que\napresentassem TVS e pacientes com arritmias ventriculares complexas, induzidas por estimulação\nventricular no estudo eletrofisiológico.","B":"Os estudos de prevenção primária contemplaram, em sua maioria, pacientes portadores de\nmiocardiopatia de etiologia isquêmica, que foram recuperados de morte súbita ou que\napresentassem TVS e pacientes com arritmias ventriculares complexas, induzidas por estimulação\nventricular no estudo eletrofisiológico.","C":"Os estudos de prevenção secundária contemplaram, em sua maioria, pacientes portadores de\nmiocardiopatia de etiologia isquêmica, que não foram recuperados de morte súbita ou que\napresentassem TVS e pacientes com arritmias ventriculares complexas, induzidas por estimulação\nventricular no estudo eletrofisiológico.","D":"Os estudos de prevenção secundária contemplaram, em sua maioria, pacientes portadores de\nmiocardiopatia de etiologia isquêmica, que foram recuperados de morte súbita ou que\napresentassem TVS e pacientes com arritmias supraventriculares complexas, induzidas por\nestimulação ventricular no estudo eletrofisiológico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-216318","number":"216318","sourceNumber":"216318","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em pacientes com Insuficiência Cardíaca - IC e Fibrilação atrial - FA a opção por\ncardioversão elétrica de urgência só é indicada se houver deterioração hemodinâmica. Quanto à\nabordagem química das outras situações, podemos apenas considerar inteiramente CORRETO o\nitem:","options":{"A":"A amiodarona é eficaz para reverter quimicamente a FA para ritmo sinusal, reduzir os\nparoxismos de FA e ajudar na manutenção do ritmo sinusal, após a reversão espontânea ou\nelétrica.","B":"A amiodarona não é eficaz para reverter quimicamente a FA para ritmo sinusal, reduzir os\nparoxismos de FA e ajudar na manutenção do ritmo sinusal, após a reversão espontânea ou\nelétrica.","C":"A amiodarona é eficaz para reverter quimicamente a FA para ritmo sinusal, mas não para reduzir\nos paroxismos de FA e ajudar na manutenção do\nritmo sinusal, após a reversão espontânea ou\nelétrica.","D":"A amiodarona é eficaz para reverter quimicamente a FA para ritmo sinusal, reduzir os\nparoxismos de FA e ajudar na manutenção do\nritmo sinusal, após a reversão espontânea, nunca\npara a elétrica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-216233","number":"216233","sourceNumber":"216233","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Nos pacientes com taquicardia juncional, qual é a medida terapêutica a se adotar?","options":{"A":"Resfriamento.","B":"Cardioversão.","C":"Atropina.","D":"Amiodarona."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-215530","number":"215530","sourceNumber":"215530","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Escolha, entre as alternativas a seguir, aquela que apresenta uma droga que NÃO deve\nser administrada pela cânula orotraqueal.","options":{"A":"Lidocaína.","B":"Atropina.","C":"Bicarbonato de sódio.","D":"Adrenalina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-201758","number":"201758","sourceNumber":"201758","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 54 anos queixando-se de palpitações há 72 horas, após ingestão de bebida\nalcoólica, procura atendimento de urgência. Sem antecedentes de doença cardíaca. PA = 140 x 80\nmmHg; FC = 168 bpm, e SatO2 = 98%. Orientado, sem outras queixas. ECG mostra fibrilação\natrial. Qual a melhor conduta?","options":{"A":"Amiodarona + enoxaparina + ecocardiograma transtorácico.","B":"Metoprolol + enoxaparina + ecocardiograma\ntransesofágico.","C":"Propafenona + enoxaparina + ecocardiograma\ntransesofágico.","D":"Cardioversão elétrica + alta na reversão.","E":"Cardioversão elétrica + enoxaparina + alta na reversão."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183596","number":"183596","sourceNumber":"183596","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Os pacientes que se encontram na fase aguda de miocardite podem desenvolver tanto\ntaquiarritmias como bradiarritmias. Estando INADEQUADO que:","options":{"A":"Essas arritmias frequentemente desaparecem após a fase aguda da miocardite, sendo a terapia,\nhabitualmente, de suporte.","B":"As taquicardias supraventriculares (TSV), principalmente fibrilação e flutter atrial, podem\ninduzir\nou agravar a IC.","C":"A abordagem inicial recomendada para a TSV sustentada sintomática é a restauração do ritmo\nsinusal através de cardioversão elétrica ou química.","D":"Geralmente se recomenda terapia antiarrítmica para extrassístoles atriais e ventriculares\nassintomáticas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183611","number":"183611","sourceNumber":"183611","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Os pacientes que se encontram na fase aguda de miocardite podem desenvolver\nanormalidades de condução que muitas vezes\nsão transitórias, mas podem também desenvolver\ntaquiarritmias. Quanto a isso, assinale a alternativa INCORRETA:","options":{"A":"Taquicardias ventriculares sustentadas assintomáticas não devem receber terapia específica.","B":"As arritmias ventriculares sustentadas devem ser tratadas com drogas antiarrítmicas após a\nreversão elétrica aguda.","C":"A opção é limitada a amiodarona.","D":"Devido aos efeitos pró-arrítmicos, drogas de classe I e III (exceto a amiodarona) são geralmente\nevitadas nesses pacientes."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-182822","number":"182822","sourceNumber":"182822","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"ECG compatível com Fenômeno de Ashman (ou de Gouaux-Ashman) seria\nADEQUADAMENTE descrito assim:","options":{"A":"condução aberrante, que ocorre em batimento que segue imediatamente um ciclo curto após um\nciclo longo, em razão da diminuição do período refratário no sistema de condução, principalmente\nno ramo direito do His, sendo mais frequente na FA.","B":"condução aberrante, que ocorre em batimento que segue imediatamente um ciclo curto após um\nciclo longo, em razão do aumento do período refratário no sistema de condução, principalmente no\nramo esquerdo do His, sendo mais frequente na FA.","C":"condução aberrante, que ocorre em batimento que segue imediatamente um ciclo curto após um\nciclo longo, em razão do aumento do período refratário no sistema de condução, principalmente no\nramo direito do His, sendo mais frequente na FA.","D":"Condução aberrante, que ocorre em batimento que segue imediatamente um ciclo curto após\num ciclo longo, em razão do aumento do\nperíodo refratário no sistema de condução, principalmente\nno ramo direito do His, sendo muito raro na FA."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-182729","number":"182729","sourceNumber":"182729","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Os tremores musculares podem afetar o ECG da seguinte forma:","options":{"A":"Tremores musculares não podem interferir na linha de base, mimetizando alterações\neletrocardiográficas como FLA e FV no paciente parkinsoniano.","B":"Tremores musculares podem interferir na linha de base, mas não mimetizando alterações\neletrocardiográficas como FLA e FV no paciente parkinsoniano.","C":"Tremores musculares podem interferir na linha de base, mimetizando alterações\neletrocardiográficas como FLA e FV no paciente com paralisia.","D":"Tremores musculares podem interferir na linha de base, mimetizando alterações\neletrocardiográficas como FLA e FV no paciente parkinsoniano."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-182732","number":"182732","sourceNumber":"182732","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O comprometimento agudo do sistema nervoso central, pode levar aos seguintes\nachados no ECG:","options":{"A":"ondas T negativas gigantes, simulando isquemia subepicárdica (onda T cerebral); aumento do\nintervalo QTc; irreversibilidade das alterações.","B":"ondas T negativas gigantes, simulando isquemia subepicárdica (onda T cerebral); aumento do\nintervalo QTc; reversibilidade das alterações.","C":"ondas T positivas gigantes, simulando isquemia subepicárdica (onda T cerebral); aumento do\nintervalo QTc; reversibilidade das alterações.","D":"ondas T negativas gigantes, mas não simulando isquemia subepicárdica (onda T cerebral);\naumento do intervalo QTc; reversibilidade das alterações."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183588","number":"183588","sourceNumber":"183588","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"As alternativas abaixo apresentam causas cardíacas de síncope, EXCETO","options":{"A":"lesão obstrutiva como estenose pulmonar.","B":"arritmias cardíacas.","C":"hipercianose.","D":"DPOC."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183598","number":"183598","sourceNumber":"183598","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Os sintomas prodrômicos de síncope neurogênica incluem, EXCETO","options":{"A":"sonolência.","B":"sudorese.","C":"palidez.","D":"náuseas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183115","number":"183115","sourceNumber":"183115","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale a alternativa CORRETA.","options":{"A":"O tônus vagal excessivo é a forma mais comum de síncope autonômica.","B":"A síncope reflexa resulta de aumento do tônus simpático associado a determinados eventos.","C":"O tônus vagal excessivo ocorre, exclusivamente, na mudança brusca de decúbito supino para\nortostático.","D":"Na síncope autonômica a perda de consciência é repentina e não ultrapassa dois minutos de\nduração."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161170","number":"161170","sourceNumber":"161170","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente foi trazido por resgate com mal-estar geral, prostração e dispneia de inícios\nsúbitos nesta manhã. Seu Eletrocardiograma\ndemonstrava uma taquiarritmia que você\ninadequadamente indicou terapia elétrica, causando grave complicação instantânea. Felizmente\napós diversas manobras, foi conseguida a reversão do quadro. A complicação provocada pode ser\nexplicada por uma das opções a seguir. Aponte-a.","options":{"A":"A desfibrilação e cardioversão elétrica consistem na aplicação de corrente elétrica de alta\nenergia para reversão de arritmias cardíacas geradas pelo mecanismo de reentrada.","B":"Na desfibrilação, esta corrente elétrica é aplicada em qualquer momento do ciclo cardíaco.","C":"Na cardioversão elétrica, esta corrente é sempre sincronizada com os complexos QRS do\neletrocardiograma.","D":"Na cardioversão elétrica, esta corrente é sempre sincronizada para que não seja administrada\ndurante o período vulnerável da\nrepolarização ventricular (onda T)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161176","number":"161176","sourceNumber":"161176","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente foi trazido ao Hospital por familiares com quadro de palpitação e mal-estar\nsúbitos nesta tarde, previamente hipertenso e\netilista. Seu Eletrocardiograma demonstrava uma\narritmia cardíaca, que foi adequadamente tratada com choque elétrico com bons resultados. Frente\na esse quadro, indique a alternativa CORRETA.","options":{"A":"Nos desfibriladores externos, o choque elétrico é aplicado por intermédio das pás manuais, as\nquais o operador posiciona sobre o tórax, exercendo pressão de aproximadamente 3 kg.","B":"No caso de flutter atrial, considera-se iniciar o procedimento com 150 J.","C":"Caso o ritmo for fibrilação atrial, considera-se o uso de energia inicial de 300 J.","D":"No caso de taquicardia supraventricular, considera-se iniciar o procedimento com 50 J."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161330","number":"161330","sourceNumber":"161330","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente previamente cardiopata evoluiu com súbito mal-estar seguido de perda de\nconsciência. Foi levado ao hospital, sendo desde sua chegada iniciado processo de reanimação.\nQuanto ao uso e indicações de desfibrilador, podemos afirmar que existem cuidados a serem\nrealizados durante sua utilização. Assinale a alternativa CORRETA em relação a esses cuidados.","options":{"A":"Não existe necessidade de depilação quando do excesso de pelos torácicos.","B":"Na presença de marcapasso definitivo, não existe maiores cuidados no uso do desfibrilados.","C":"Tórax molhado: não necessita de secar por completo o tórax da vítima.","D":"Vítima sobre uma poça d?água não há problema, porém se essa poça d?água também envolver\no socorrista, remova a vítima para outro local, o\nmais rápido possível."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161185","number":"161185","sourceNumber":"161185","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Senhora de 63 anos de idade apresentou súbito mal-estar nesta manhã, sendo\nimediatamente trazida por familiares ao\nHospital. Apresentava intensa dispneia e palpitações, sua\nausculta cardíaca demonstrava ritmo irregular. Seu ECG demonstrava taquiarritmia, sendo então\ndecidido uso de cardioversão elétrica. Dentre as etapas a seguir referentes a esse procedimento,\nindique a opção INCORRETA.","options":{"A":"Durante a cardioversão, deve-se acionar o botão de sincronização antes da administração de\ncada choque, nesta situação, geralmente,\naparece um sinal gráfico no monitor confirmando a\nsincronização. Selecione o nível adequado de energia de acordo com a arritmia, conforme\nmencionado.","B":"Aplique gel nas pás e posicioná-las sobre a superfície do tórax do paciente na posição\nadequada. Aplique uma pressão sobre as pás. Carregue o desfibrilador/cardioversor.","C":"Verifique se o operador e os demais socorristas não estão mantendo contato com o paciente ou\ncom a maca ou cama, pois existe o risco de\ncondução da corrente elétrica para estes indivíduos,\npodendo causar graves complicações. Também, verifique a ausência de administração de oxigênio\nem alto fluxo próximo ao desfibrilador devido ao risco de formação de faíscas.","D":"Aplique o choque elétrico, mantendo as pás sobre o tórax do paciente por alguns minutos,\nprincipalmente, durante a cardioversão, pois pode haver um pequeno atraso na administração do\nchoque devido à necessidade de adequada sincronização."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161290","number":"161290","sourceNumber":"161290","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quando após criteriosa avaliação clínica de uma bradicardia sinusal é constatada a\nausência de causas reversíveis, o implante de marca-passo definitivo é tratamento efetivo para a\ndisfunção sinusal sintomática. Sobre isso, assinale a alternativa INCORRETA.","options":{"A":"Apesar de não modificar a taxa de sobrevida, o marca-passo permite a melhora tanto dos\nsintomas como da qualidade de vida dessa população.","B":"Portadores de doença do nó sinusal na ausência de estimulação cardíaca (ou seja, sem\n\nmarca-passo) raramente evoluem com eventos sintomáticos que podem exigir tratamento imediato,\ntais como síncope, insuficiência cardíaca\ndescompensada e fibrilação atrial permanente, além de\ntaquiarritmias paroxísticas com resposta ventricular elevada.","C":"O implante de marca-passo melhora significativamente a qualidade de vida dos portadores de\ndoença do nó sinusal a partir do terceiro\nmês do procedimento, sem modificar a mortalidade por\nqualquer causa.","D":"Em pelo menos metade dos pacientes com doença do nó sinusal, observam-se bradiarritmias\nalternando-se com taquiarritmias atriais."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161337","number":"161337","sourceNumber":"161337","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Idoso é trazido por neto ao hospital, após sentir fortes dores torácicas nesta manhã. Foi\nadmitido na sala de emergência devido ao seu histórico de hipertenso e cardiopata. Foi\nmonitorizado e, durante o período em que aguardava novos exames laboratoriais, perdeu os\nsentidos, sendo que não existia, neste momento, complexos QRS organizados no monitor. Iniciado\nprotocolo de reanimação, que entre outros inclui terapêutica elétrica, podemos admitir que:","options":{"A":"na desfibrilação deve-se utilizar a máxima energia do aparelho. Se esta orientação é\ndesconhecida deve ser administrado choque de 200 J no caso do monofásico.","B":"na desfibrilação deve-se utilizar a máxima energia do aparelho; sendo aplicada 360 J no\ndesfibrilador monofásico e de 120 a 200 J no desfibrilador bifásico, conforme orientação do\nfabricante.","C":"pode ser utilizado cardioversão com efetividade, caso esteja utilizando 360 J.","D":"não deve ser tomada como prioritária em sua sequência de reanimação."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161221","number":"161221","sourceNumber":"161221","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A frequência cardíaca normalmente varia de 60 bpm a 100 bpm. Ritmos com\nFrequência Cardíaca < 60 bpm são definidos como\nbradicardia, podendo ser assintomática ou\nsintomática. As bradicardias sintomáticas têm características clínicas comuns, marcadas,\nsobretudo, pela síndrome do baixo fluxo, comumente ocasionadas por doença do nó sinusal. Na\ndoença do nó sinusal, o implante de marca-passo é indicado nos casos a seguir, com EXCEÇÃO\nde","options":{"A":"incompetência cronotrópica sintomática.","B":"bradicardia sinusal sintomática, secundária ao uso de fármacos indispensáveis.","C":"síncope de origem indeterminada, com evidências eletrocardiográficas de disfunção do nó\nsinusal documentada ou provocada no estudo eletrofisiológico.","D":"disfunção do nó sinusal com frequência cardíaca < 60 bpm em vigília, sem correlação clara entre\nos sintomas e a bradicardia documentada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161231","number":"161231","sourceNumber":"161231","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A doença do nó sinusal, condição em que existe disfunção do nó sinusal sintomática, é\ncaracterizada por anormalidades da geração e da condução do estímulo sinusal, levando a ritmos\ncom frequência cardíaca < 60 bpm, que são definidos como bradicardia. Assim, aponte a alternativa\nINCORRETA.","options":{"A":"As bradicardias sintomáticas têm características clínicas comuns, marcadas, sobretudo, pela\nsíndrome do baixo fluxo cerebral e/ou sistêmico, cujos sintomas mais comuns são tontura,\n\npré-síncope, síncope, fadiga, dispneia de esforço e bradipsiquismo,\n\nsendo comumente ocasionadas por doença do nó sinusal e bloqueio atrioventricular.","B":"As sintomáticas, geralmente, são de causas fisiológicas, representadas por bradicardia sinusal e\nritmos de escape da junção atrioventricular.","C":"Fatores extrínsecos também podem causar bradicardia, como uso de fármacos que deprimem o\nsistema de condução ou distúrbios metabólicos ou endócrinos, como hipotireoidismo,\nhiperpotassemia e hipotermia.","D":"Considerando que não há fármacos adequados para o tratamento das bradicardias sintomáticas\nirreversíveis, o implante de marca-passo definitivo é o tratamento mais indicado para essas\nafecções."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161201","number":"161201","sourceNumber":"161201","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em seu último plantão de emergência, você precisou utilizar um marca-passo em uma\nbradicardia, mas ele não estava funcionando adequadamente e você reclamou ao diretor. O diretor\nsolicitou, então, a sua ajuda para fundamentar a necessidade de adquirir outro aparelho mais\nmoderno para o Hospital. Assim, você o ajudou. Desse modo, aponte a alternativa CORRETA.","options":{"A":"O Marca-passo Transcutâneo (MPTC) faz a estimulação cardíaca temporária, é um\nprocedimento eletivo e tem a vantagem de ser uma técnica não invasiva e de instalação\npraticamente imediata.","B":"O Marca-passo Transcutâneo (MPTC) é um dispositivo que pode estimular o ritmo cardíaco pelo\nfornecimento de corrente elétrica por eletrodos colados na pele. Há repolarização elétrica que\nlevará à contração cardíaca.","C":"A principal indicação de seu uso é em pacientes com bradicardia sintomática. Pode também ser\nutilizado na superestimulação para supressão de taquicardias refratárias com o intuito de eliminar\nTaquicardia Supraventricular (TSV) e Taquicardias Ventriculares (TV) malignas.","D":"Recomendado para pacientes em PCR por assistolia, visto que trials randomizados indicaram\nmelhora nos índices de sobrevida na admissão hospitalar, e na alta hospitalar, em pacientes\nsubmetidos à colocação do MPTC em PCR por assistolia tanto pré como intra-hospitalar."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161355","number":"161355","sourceNumber":"161355","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A terapia elétrica apresenta diversas utilidades no tratamento de patologia crônica e\naguda, tanto ambulatorial como em emergências. Sobre isso, aponte a alternativa que NÃO se\nmostra adequada.","options":{"A":"No caso de flutter atrial ou taquicardia supraventricular, considera-se iniciar o procedimento\ncom\n50 J; e se o ritmo for fibrilação atrial,\nconsidera-se o uso de energia inicial de 200 J.","B":"Instabilidade de Fibrilação Atrial indica somente terapêutica elétrica.","C":"Somente situações de parada cardíaca indicam terapêutica com choque.","D":"Em arritmias ventriculares os aparelhos não são capazes de analisar o melhor momento dentro\ndo ciclo cardíaco para descarregar a corrente\nelétrica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161205","number":"161205","sourceNumber":"161205","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante procedimento eletivo com anestesia local na sala de pequenas cirurgias,\nocorreu a emergência de um paciente eletivo\nda clínica cirúrgica. Você então foi chamado a ajudar\nno socorro do paciente apenas com a informação de que ele já era cardiopata em uso de digoxina\ne amiodarona. Na sua avaliação inicial, detectou bradicardia com grande repercussão clínica, assim\nindicou o uso de marca-passo transcutâneo. Referente aos passos desse procedimento, marque a\nopção INCORRETA:","options":{"A":"Observe qual é o ponto de corte para que haja captura de algumas das espículas do MP. A partir\ndesse ponto, deixe o valor da corrente elétrica com margem de segurança de 30% acima desse\nlimiar.","B":"Fixe as pás autoadesivas no tórax despido da vítima. Coloque o eletrodo anterior à esquerda do\nesterno, centralizado e o mais próximo possível do ponto de máximo do impulso cardíaco. Coloque\no eletrodo posterior nas costas, diretamente atrás do\n\neletrodo anterior e à esquerda da coluna torácica. A alternativa a essa posição dos eletrodos é a\ncolocação semelhante à do DEA: uma das pás deve ser posicionada na região sobre o ápice do\ncoração e a outra sobre a região paraesternal direita.","C":"Selecione inicialmente a frequência cardíaca desejada (geralmente em torno de 80 bpm, em\ncasos de bradicardias). Em seguida, ajuste a\ncorrente elétrica a ser administrada, aumentando\ngradualmente o valor de corrente elétrica a partir do valor mínimo, até que se obtenha captura\nelétrica. Geralmente, a captura se caracteriza pelo alargamento do complexo QRS com uma onda T\nlarga e oposta à polaridade do QRS.","D":"Avalie a resposta hemodinâmica do MP pelo pulso e pela pressão arterial. Forneça analgesia e\nsedação, conforme necessário."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161250","number":"161250","sourceNumber":"161250","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A indicação mais comum para o implante de marca-passo definitivo é a doença do nó\nsinusal, condição em que existe disfunção do nó sinusal sintomática, caracterizada por\nanormalidades da geração e da condução do estímulo sinusal. A respeito das afirmações a seguir,\nindique aquela que é considerada INADEQUADA.","options":{"A":"Existe a facilitação na passagem do estímulo do nó sinusal para o tecido atrial.","B":"Ocorrem anormalidades da transmissão do impulso dentro dos átrios e para o sistema de\ncondução cardíaco.","C":"Disfunção na atividade de marca-passos subsidiários, e taquiarritmias crônicas e paroxísticas,\nprincipalmente a fibrilação atrial.","D":"A etiologia da doença do nó sinusal pode ser intrínseca, que inclui processos inflamatórios,\ninfecciosos e imunológicos, fibrose\ndegenerativa, disfunção de canais iônicos e remodelamento do\nnó sinusal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161258","number":"161258","sourceNumber":"161258","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dados epidemiológicos a respeito da doença do nó sinusal demonstram que as\nseguintes afirmativas estão adequadas, com EXCEÇÃO de uma. Assinale-a.","options":{"A":"A doença do nó sinusal afeta 1 a cada 600 pessoas com idade > 65 anos (média de 74 anos),\nsomente ocorrendo em idosos.","B":"Os distúrbios eletrolíticos mais comumente envolvidos são a hiperpotassemia, a hipopotassemia\ne a hipocalcemia.","C":"Os sintomas mais comuns dos portadores de doença do nó sinusal são tonturas, vertigens,\npré-síncope, síncope, palpitações, intolerância ao exercício e fadiga, geralmente intermitentes.","D":"As principais manifestações eletrocardiográficas da doença do nó sinusal são bradicardia\nsinusal, pausas ou paradas sinusais, bloqueio\nsinoatrial, taquicardia atrial, fibrilação atrial e\nincompetência cronotrópica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161368","number":"161368","sourceNumber":"161368","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente feminina, 70 anos de idade, deu entrada desacordada no hospital trazida por\ncorpo de bombeiros, tendo ocorrido perda de consciência após episódio de intensa dispneia, nesta\ntarde. Histórico de ser cardiopata com tratamento irregular. Exame físico demonstra estertores\npulmonares, ritmo cardíaco irregular e taquicardíaco. Monitor cardíaco com frequência acima de\n140 bpm, QRS fino, mas com distâncias variáveis. Podemos assim propor que o tratamento\nINDICADO deve considerar que:","options":{"A":"na cardioversão elétrica, pode-se realizar o choque sequencial com um nível decrescente de\nenergia se o primeiro choque não reverteu à arritmia, lembrando sempre de sincronizar o\ncardioversor antes de cada procedimento.","B":"se o ritmo for fibrilação atrial, considera-se o uso de energia inicial de 200 J.","C":"a corrente é sempre sincronizada com os complexos QRS do eletrocardiograma para que não\nseja administrada durante o período vulnerável da onda P.","D":"está indicado desfibrilação."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161175","number":"161175","sourceNumber":"161175","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Bradiarritmias são graves emergências médicas potencialmente fatais. Ocorrendo a\nindicação do procedimento de marca-passo, assinale a alternativa ADEQUADA frente à\ndesvantagem desta técnica.","options":{"A":"O Marca-Passo Transcutâneo (MPTC) é um dispositivo que, em geral, causa desconforto e dor\nao paciente, visto que correntes elétricas de\n50 a 100 miliampères (mA) são necessárias.\nConsidere analgesia e sedação do paciente.","B":"A desvantagem do Marca-Passo Transcutâneo (MPTC) é a necessidade de alta energia em\nrazão da necessidade de fazer a energia\naplicada vencer a impedância transtorácica e chegar ao\nmiocárdio. A impedância transtorácica consiste na resistência\n\nda parede torácica ao fluxo da corrente elétrica e pode também ser influenciada pelo tamanho dos\neletrodos.","C":"Por ser eficaz, rápido, seguro e não invasivo é bastante útil em serviços de emergência. Porém,\no Marca-Passo Transcutâneo (MPTC) é um procedimento\ntemporário e deve ser utilizado como\nponte até a colocação de um marca-passo transvenoso ou permanente, se indicados.","D":"Verifique se há a opção de MPTC em seu monitor/desfibrilador/cardioversor. Lembrete: nem\ntodos os aparelhos dispõem dessa função."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161374","number":"161374","sourceNumber":"161374","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Idoso, 80 anos, referia intenso mal-estar de início nesta manhã com palpitação,\nsudorese de dispneia. Foi trazido ao pronto\natendimento onde ocorreu diagnóstico\neletrocardiográfico de fibrilação atrial aguda. Foi proposto tratamento elétrico com desfibrilação\nde\nvez que era emergência, porém logo após o choque inicial o paciente evoluiu em parada cardíaca.\nTeoricamente, podemos AFIRMAR que:","options":{"A":"Isso pode ter ocorrido devido ao fato de que, na desfibrilação, a corrente elétrica é aplicada em\nqualquer momento do ciclo cardíaco.","B":"Nessa situação a corrente foi sincronizada com os complexos QRS do eletrocardiograma para\nque não seja administrada durante o período\nvulnerável da despolarização ventricular.","C":"Cardioversão pode potencialmente desencadear uma fibrilação ventricular caso associada à\nonda P.","D":"Nessa situação a corrente foi sincronizada com os complexos QRS do eletrocardiograma para\nque não seja administrada durante o período\nrefratário da despolarização ventricular."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161326","number":"161326","sourceNumber":"161326","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Adulto de 34 anos apresentou súbita dor torácica seguida de síncope nesta manhã. Foi\nsocorrido e iniciado manobras de reanimação com sucesso, no sentido de retorno à circulação\nespontânea. Frente a essa situação, podemos AFIRMAR que:","options":{"A":"somente após 24 horas podemos concluir clinicamente desfecho ruim neurológico.","B":"a Pressão Arterial Sistólica inferior a 90 mmHg no pós PCR está associada a pior desfecho.","C":"o período para avaliação neurológica não deve ser maior nos casos de suspeita de efeito\nresidual de sedação.","D":"existe uma meta geral para perfusão orgânica de todos os vitimados de parada cardíaca."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161190","number":"161190","sourceNumber":"161190","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Podemos considerar dentro da abordagem do paciente infartado uma grande\nimportância da FV como mecanismo de óbito\nprecoce. Estima-se que a desfibrilação salve cerca de\nseis vezes mais vidas que o tratamento trombolítico, mas depende de sua rápida aplicação ao\npaciente. Referente ao impacto potencial, em termos de benefício, ao se intervir na fase\n\npré-hospitalar no IAM, assinale a alternativa INCORRETA.","options":{"A":"Identificar o perfil dos casos de IAM que não chegam aos hospitais, qualificando o estado atual\nde atendimento e quantificando o impacto de uma\nnova estratégia de grande difusão na população.","B":"Fornecer maior informação somente a profissionais de saúde quanto aos sintomas de IAM e à\nimportância de uma busca rápida por auxílio médico, evitando erros de conduta.","C":"Realizar treinamento difuso da população para atendimento de urgência nos moldes do BLS.","D":"Disponibilizar desfibriladores externos automáticos em locais públicos de grande circulação."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161341","number":"161341","sourceNumber":"161341","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"De acordo com a maioria das diretrizes nacionais e internacionais atuais, ocorre a\nnecessidade de grande conhecimento médico a respeito das terapias elétricas utilizadas em\nsituações de emergência. Sobre isso, podemos considerar ADEQUADA a seguinte afirmativa ou\nnegativa. Aponte-a.","options":{"A":"Na cardioversão elétrica, pode-se realizar o choque sequencial com um nível crescente de\nenergia se o primeiro choque não reverteu a arritmia.","B":"Desfibrilação sempre utilizará uma corrente monofásica.","C":"A posição de qual pá está em seu local; será determinante do sucesso, mesmo estando ambas\nnos locais adequados no tórax.","D":"Desfibrilação é adequada em todos os ritmos sem pulso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161149","number":"161149","sourceNumber":"161149","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante o período noturno, ocorreu algo inusitado no seu plantão, isto é, você foi\nchamado a avaliar um paciente que estava na\nobservação e, ao ir até o seu leito, descobriu que ele\nestava em Parada Cardíaca. Você realizou os procedimentos que não foram bem sucedidos. Sobre\nesse caso, indique a opção INCORRETA.","options":{"A":"A Parada Cardiorrespiratória (PCR) é uma das situações clínicas de maior emergência na\nmedicina. A rapidez e a eficácia das intervenções adotadas são fundamentais e interferem\ndiretamente no prognóstico da vítima.","B":"Dos adultos vítimas de parada cardíaca em ambiente intra-hospitalar, grande parte apresenta\nritmo de atividade elétrica sem pulso e\nAssistolia como ritmo inicial de PCR.","C":"Os ritmos de fibrilação ventricular e taquicardia ventricular sem pulso (FV/TVSP) são\nresponsáveis por parte dos eventos de PCR em ambiente intra-hospitalar, apresentando as\nmenores taxas de sobrevida.","D":"Diversos fatores têm sido relacionados com maior sobrevida hospitalar, como o local onde\nacontece o evento, dias da semana quando\ncomparados com finais de semana, eventos que\nacontecem no período diurno quando comparados com o período noturno, eventos presenciados,\nidade menor de 65 anos, presença de função normal do ventrículo esquerdo antes do evento,\nduração do evento, entre outros."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161159","number":"161159","sourceNumber":"161159","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante esta manhã você recebeu, transferido de outro serviço de atendimento\nprimário, um paciente grave em insuficiência\nrespiratória por DPOC, no qual o colega\nadequadamente utilizou manejo de via aérea com máscara laríngea, o que levou você a elogiá-lo\nmuito, AFIRMANDO que:","options":{"A":"Embora a máscara laríngea ofereça proteção absoluta das vias aéreas contra aspiração, a\nfrequência desta complicação é maior do que quando a ventilação é realizada com dispositivo\nbolsa-válvula-máscara.","B":"Quando comparada com a intubação orotraqueal, a máscara laríngea oferece ventilação\nsuperior.","C":"Ventilação com sucesso, entre a minoria dos casos, tem sido reportada durante a realização das\nmanobras de RCP.","D":"Para profissionais da área da saúde treinados no seu uso, a máscara laríngea é uma alternativa\nao dispositivo bolsa-válvula-máscara ou à\nintubação orotraqueal."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161167","number":"161167","sourceNumber":"161167","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dentro dos conceitos atuais de abordagem da parada cardiorrespiratória, a\nmonitorização se apresenta como ferramenta\nclínica, sendo que o dióxido de carbono, exalado no\nfinal da expiração expressado em mmHg ? PETCO ?, detectado pela capnografia quantitativa em\npacientes intubados, relaciona-se CORRETAMENTE com uma das opções seguintes. Aponte-a.","options":{"A":"PETCO não tem sido correlacionado com a qualidade da RCP.","B":"Durante a PCR não tratada, a produção de CO é mantida, porém não existe liberação pelos\npulmões, sendo a presença de débito cardíaco a maior determinante da liberação do PETCO.","C":"Os valores do PETCO têm sido correlacionados com o Retorno Circulação Espontânea, mas\nnão com a pressão de perfusão coronária.","D":"Valores < 100 mmHg revelam pouca probabilidade de Retorno Circulação Espontânea,\nindicando a necessidade de melhora na qualidade da RCP."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161401","number":"161401","sourceNumber":"161401","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Idosa de 68 anos de idade procurou serviço hospitalar com queixa de mal-estar e\nfadigas progressivas nas últimas semanas. Dentre os\nexames solicitados inicialmente, foi realizado\num Eletrocardiograma demonstrando padrão de baixa voltagem, o que NÃO pode ser decorrente\nde:","options":{"A":"embolia pulmonar.","B":"pericardite.","C":"obesidade.","D":"mamas volumosas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161172","number":"161172","sourceNumber":"161172","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quanto à análise do dióxido de carbono exalado no final da expiração expressado em\nmmHg ? PETCO ?, detectado pela capnografia\nquantitativa em pacientes intubados, indique a\nalternativa considerada INADEQUADA.","options":{"A":"Evidências sugerem que, se o paciente mantiver valores baixos de PETCO por longos períodos,\na despeito de condições ideais de RCP,\nfacilmente o Retorno Circulação Espontânea (RCE) será\natingido.","B":"O valor baixo pode ser levado em consideração por ocasião da definição de cessação de\nesforços.","C":"No entanto, se durante as manobras de RCP existe aumento abrupto do PETCO, é razoável\nconsiderar que houve RCE.","D":"Para os pacientes que não estão intubados, ainda não existem evidências da utilidade da\ncapnografia quantitativa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161406","number":"161406","sourceNumber":"161406","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Diversas situações podem levar a graves arritmias cardíacas, podendo essas inclusive\nser geradores de Fibrilação Ventricular como\nconsequência. A doença descrita na síndrome de\nWolfParkinson White, contudo NÃO se relaciona com o seguinte dado. Assinale-o.","options":{"A":"Falha no Isolamento Elétrico Ventricular.","B":"Canais de Sódio defeituosos.","C":"Aumento do potencial arritmogênico.","D":"Feixe anômalo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161415","number":"161415","sourceNumber":"161415","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dentro da epidemiologia e algoritmos de avaliação do risco de fenômenos\ntromboembólicos da fibrilação atrial, podemos\nconsiderar INADEQUADA uma das alternativas.\nAponte-a.","options":{"A":"É a principal fonte emboligênica de origem cardíaca de que se tem conhecimento,\nrepresentando cerca de 45% dos casos quando\ncomparada com outras cardiopatias, como infarto\ndo miocárdio, aneurismas ventriculares e doenças valvares.","B":"As causas da formação de trombos são multifatoriais e estão relacionadas com a tríade de\nVirchow que inclui: (1) estase sanguínea atrial; (2) lesão endotelial; (3) aumento da\ntrombogenicidade sanguínea, própria dessa arritmia.","C":"No primeiro caso, a lenhificação do fluxo na região do Apêndice Atrial Esquerdo (AAE) favorece\na estase sanguínea e a formação de coágulos de\nfibrina, que se acumulam e geram o trombo.","D":"O cérebro, muito mais que membros e vísceras, é a região mais afetada, em cerca de 10% dos\ncasos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161416","number":"161416","sourceNumber":"161416","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dentro da afirmativa de que as três condições estabelecidas por Virchow estão\npresentes em paciente com Fibrilação Atrial, indique a opção considerada INCORRETA.","options":{"A":"Lesões do endocárdio atrial apresentavam microtrombos e que estes eram os precursores de\ntrombos maiores. Pacientes que não apresentavam tais lesões tinham muito menor propensão à\ntrombose atrial.","B":"O atrito do sangue com o endocárdio, lesões miocitárias causadas por agressões teciduais\nsecundárias a citocinas inflamatórias (fator\nde necrose tumoral, interleucina 6, proteína C-reativa e\noutras) prejudicam ainda mais os miócitos atriais e expõem o tecido colágeno na superfície, o que\ndiminui a aderência de plaquetas e a deposição de fibrina, gerando o trombo. Dessa forma, a FA\ncria um estado pró-trombótico, hipercoagulável próprio.","C":"O aumento da agregação plaquetária, mais intensa no Átrio Esquerdo (AE), e a elevação dos\nníveis plasmáticos do fator de Von Wilebrand.","D":"Os fragmentos de protrombina e do fibrinogênio plasmático, dentre outros, confirmam essa\nmaior trombogenicidade sanguínea, independentemente de qualquer outro fator."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161417","number":"161417","sourceNumber":"161417","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Devido à maior propensão de pacientes com fibrilação atrial apresentarem risco,\ninerente à própria arritmia, de formar\ncoágulos, independentemente de outros fatores, ocorre a\nnecessidade de se identificar exatamente aquele de menor risco e excluí-lo da necessidade de\nanticoagular, por meio da inclusão de outros critérios de risco que possam caracterizá-los, ficando\nfora da necessidade de terapia com anticoagulante oral os pacientes com real risco baixo. Por essa\nrazão, outras variáveis, que foram identificadas, passaram a ser valorizadas como fatores de risco,\nEXCETO:","options":{"A":"Sexo masculino.","B":"Doença vascular periférica.","C":"Idade entre 64 e 75 anos.","D":"Idade acima de 75 anos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161327","number":"161327","sourceNumber":"161327","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Pacientes com Fibrilação Atrial apresentam um risco maior de hemorragia quando\ntratados com Anticoagulante Oral, tornando-se\nnecessário não apenas avaliar o risco de\ntromboembolismo sistêmico, mas também de hemorragia quando o ACO for prescrito. Nas\nalternativas a seguir estão contidos os fatores associados a sangramento, com EXCEÇÃO de um.\nIndique-o.","options":{"A":"Hipertensão arterial não controlada (níveis pressóricos acima de 160 mmHg).","B":"Estabilidade da taxa de Razão Normalizada Internacional (RNI).","C":"Uso de fármacos anti-inflamatórios.","D":"Consumo de álcool."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161340","number":"161340","sourceNumber":"161340","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Para adequadamente indicar o uso de drogas Antiarrítmicas, o que representa um\npapel relevante em ambas as estratégias no\nmanejo clínico da Fibrilação Atrial, devemos entender\nque as drogas antiarrítmicas mais utilizadas variam de acordo com suas características clínicas,\necocardiográficas e evolução de tratamentos anteriores. Após a avaliação de um caso de FA, o\npaciente pode ser alocado na estratégia de controle do ritmo ou controle da frequência. A respeito\ndisso, aponte a alternativa INCORRETA.","options":{"A":"A avaliação inicial deve definir a presença de cardiopatia estrutural, assim como avaliar se a\ncausa é reversível.","B":"Episódios causados por ingestão excessiva de álcool ou crise tireotóxica, que reverteram ao\nritmo sinusal espontaneamente ou após\ncardioversão, necessitam de tratamento com antiarrítmico\npor longo prazo.","C":"Deve-se lembrar que as medidas não farmacológicas, como atividade física regular, dieta\nbalanceada, controle de peso, otimização da qualidade do sono, devem ser instituídas.","D":"Além disso, alguns medicamentos não antiarrítmicos apresentam importante papel na prevenção\nde FA como as estatinas, os\n\ninibidores da enzima conversora da angiotensina e bloqueadores dos receptores da angiotensina I,\nespecialmente nos pacientes que também apresentam hipertensão arterial ou IC."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161347","number":"161347","sourceNumber":"161347","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Acerca da abordagem da arritmia, o controle da frequência na Fibrilação Atrial é uma\nestratégia importante para a prevenção de diversas complicações cardiovasculares, com\nEXCEÇÃO de","options":{"A":"lesão endotelial.","B":"cansaço e redução da capacidade de exercício.","C":"redução da morbidade.","D":"taquicardiomiopatia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-161247","number":"161247","sourceNumber":"161247","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Leia as seguintes afirmativas sobre o atendimento intra-hospitalar do paciente vítima de\nafogamento. I. O controle da glicemia no paciente que sofreu afogamento deve focar na prevenção\nda hipoglicemia ou hiperglicemia e nas rápidas flutuações no estado glicêmico. II. Crianças que\nsofreram afogamento e que estão comatosas e apresentam tomografia computadorizada alterada\ngeralmente têm pior prognóstico. III. A pressão arterial deve ser continuamente monitorada. As\nafirmativas CORRETAS estão contidas em:","options":{"A":"I, II e III.","B":"I e II, apenas.","C":"II e III, apenas.","D":"I e III, apenas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-110563","number":"110563","sourceNumber":"110563","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Qual a sua orientação para um adolescente que chega ao seu consultório com febre\nreumática, fazendo uso de penicilina benzatina há três anos, cujo diagnóstico foi dado aos dez\nanos de idade, quando o menor apresentou febre, dores articulares sem sinais flogísticos, proteína\nC reativa +++ e ASLO de 500 U Todd?","options":{"A":"Prosseguir o tratamento com penicilina benzatina até o paciente completar 18 anos;","B":"Mudar o antibiótico injetável para um oral;","C":"Solicitar novos exames laboratoriais e fazer\nnova avaliação do caso;","D":"Substituir o antibiótico por anti-inflamatório\nnão hormonal;","E":"Suspender toda a medicação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-109976","number":"109976","sourceNumber":"109976","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"São características clínicas e radiológicas da osteoartrite, EXCETO que:","options":{"A":"Nas fases iniciais há alterações radiológicas, na maioria dos casos não acompanhadas de\nqueixas clínicas.","B":"A principal queixa clínica é a dor articular.","C":"A dor frequentemente é acompanhada de edema articular.","D":"A dor melhora com o exercício e piora após períodos prolongados de inatividade."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-86600","number":"86600","sourceNumber":"86600","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale a alternativa que apresenta manifestações clínicas e/ou alterações em exames\ncomplementares sugestivas de artrite psoriásica: I ? Envolvimento articular assimétrico; II ?\n\nArtropatia de Jaccoud; III ? Envolvimento de articulações interfalangianas distais na ausência de\nosteoartrose; IV - Ausência de fator reumatoide; V ? Síndrome nefrótica.","options":{"A":"I, II e III.","B":"I, IV e V.","C":"II, III e IV.","D":"III, IV e V.","E":"I, III e IV."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-86851","number":"86851","sourceNumber":"86851","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Pelos critérios de Jones (1992), o diagnóstico de doença reumática é muito provável\nquando existirem evidências laboratoriais de estreptococcia anterior e dois sinais maiores ou um\nmaior e dois sinais menores. Os sinais que caracterizam este diagnóstico são:","options":{"A":"Poliartrite, eritema marginatum e aumento da proteína C.","B":"Poliartrite, emagrecimento e intervalo PR aumentado.","C":"Febre, cardite e emagrecimento.","D":"Febre, artralgia e VHS elevado.","E":"Poliartralgia, febre e mucoproteina aumentada."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-286702","number":"286702","sourceNumber":"286702","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale a alternativa que NÃO faz parte da doença do nó sinusal:","options":{"A":"Síndrome bradicardia-taquicardia.","B":"Pausa sinusal.","C":"Taquicardia por reentrada nodal.","D":"Bradicardia sinusal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-286705","number":"286705","sourceNumber":"286705","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A indicação de marcapasso definitivo nos bloqueios atrioventriculares são todos abaixo,\nEXCETO:","options":{"A":"BAV do 2° grau do tipo 2 ou mobitz 2","B":"BAV do 2° grau do tipo 2:1","C":"BAV do 3° grau","D":"BAV do 2° grau do Tipo 1 ou mobitz 1"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-107961","number":"107961","sourceNumber":"107961","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente 60 anos, sexo feminino, vem evoluindo há 2 anos com dor em ambos os\njoelhos, que está ausente pela manhã e\naparece ao longo do dia quanto está fazendo suas\natividades. Não tem rigidez matinal, nega sintomas constitucionais ou outros sinais e sintomas. Ao\nexame físico, apresenta crepitação em ambos os joelhos, sem outras alterações. Com relação a\nesta paciente, analise as afirmativas abaixo: I. A paciente apresenta uma oligoartralgia simétrica\naditiva crônica de ritmo mecânico. II. o diagnóstico mais provável é osteoartrite. III. É\nnecessário a\nradiografia de joelhos AP e perfil para a Complementação diagnóstica. IV. Uma abordagem\nterapêutica adequada é: Parecetamol em caso de dor, fisioterapia visando fortalecimento muscular\ne a manutenção de amplitude e movimento, orientação quanto a manter o peso corporal em uma\nfaixa adequada. Com relação às afirmativas acima, assinale a alternativa correta:","options":{"A":"Somente as afirmativas I,II e III são corretas.","B":"Somente as afirmativas II,III e IV são corretas.","C":"Somente as afirmativas I,II; III e IV são corretas.","D":"Somente as afirmativas I,II e IV são corretas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-103825","number":"103825","sourceNumber":"103825","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente do sexo feminino, 45 anos de idade, evoluindo há 6 meses com poliartrite\nsimétrica, pequenas e grandes articulações (mãos, punhos, cotovelos, joelhos, tornozelos, e\narticulações dos pés). Relata perda de peso (5 kg), rigidez matinal de 3 horas. Tendo como\nhipótese diagnóstico Artrite Reumatoide, qual exame auxilia no diagnóstico?","options":{"A":"FAN","B":"ALSO","C":"Anti-CCP","D":"C3 e C4"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-103845","number":"103845","sourceNumber":"103845","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente do sexo masculino, 19 anos, evoluindo há 10 meses com artrite do tornozelo\ndireito, joelho esquerdo, cotovelo direito e\nlombalgia tipo inflamatória. A hipótese diagnóstica é de\nespondilite anquilosante. Qual o exame que auxilia no diagnóstico?","options":{"A":"HLA-B27.","B":"VHS.","C":"Anti-DNA de dupla hélice.","D":"Waaler-Rose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-87384","number":"87384","sourceNumber":"87384","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre o quadro clinicolaboratorial da artrite séptica, assinale alternativa INCORRETA.","options":{"A":"Geralmente tem início agudo e acometimento monoarticular.","B":"Cefepima e metronidazol estão entre os antibióticos de primeira escolha para o tratamento.","C":"Staphylococcus aureus é o principal agente etiológico.","D":"Joelhos, quadris, punhos e ombros são as articulações mais frequentemente envolvidas.","E":"Líquido sinovial com celularidade acima de 50.000 leucócitos com predomínio de\npolimorfonucleares são achados frequentes."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-81980","number":"81980","sourceNumber":"81980","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dos medicamentos abaixo, todos são utilizados no tratamento da artrite reumatoide,\nEXCETO:","options":{"A":"Metotrexato.","B":"Rituximabe.","C":"Hidroxicloroquina.","D":"Leflunomida.","E":"Belimumabe."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-81021","number":"81021","sourceNumber":"81021","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem, 52 anos, apresenta sinais de artrite aguda intensa na 1ª metatarsofalangeana\ndireita. Esta é a 3ª crise nos últimos 6 meses.\nTem diagnósticos de HAS, mas não faz tratamento,\nPA = 170/110 mmHg. Quais as medicações a serem prescritas nesse momento?","options":{"A":"Alopurinol, cochicina e losartana.","B":"Diclofenaco de sódio, predinisona e hidroclorotiazida.","C":"Butazolidina, prednisona e propanolol.","D":"Colchicina, alopurinol e propranolol.","E":"Anti-inflamatório não hormonal, colchicina e losartana."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-61551","number":"61551","sourceNumber":"61551","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"De acordo com a OMS (2004), para o diagnóstico do primeiro surto de febre reumática\nsão necessários usar os critérios de Jones (1992):\ndois critérios maiores ou um critério maior e dois\nmenores, associado à evidência de infecção estreptocócica anterior, são eles:","options":{"A":"Artrite, artralgia, febre.","B":"Artralgia, febre, aumento do intervalo PR.","C":"Artralgia, febre, aumento do intervalo PR.","D":"Eritema marginatum, febre, sopro sistólico mitral.","E":"Cardite, bloqueio atrioventricular do primeiro grau, artralgia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-60821","number":"60821","sourceNumber":"60821","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Na Artrite Reumatoide é correto afirmar, EXCETO:","options":{"A":"A PCR e VHS são exames frequentemente utilizados para avaliar a presença e intensidade do\nprocesso inflamatório da doença.","B":"Metotrexato, Hidroxicloroquina, sulfassalazina e leflunomida são fármacos antirreumáticos\nmodificadores do curso da doença.","C":"O envolvimento pulmonar é comum e geralmente se manifesta de maneira discreta.","D":"Anti-CCP e Fator Reumatoide são os principais marcadores imunológicos.","E":"Infliximabe é um agente biológico utilizado no tratamento e atua depletando linfócito B."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-46674","number":"46674","sourceNumber":"46674","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quanto à Artrite Reumatoide (AR) é INCORRETO afirmar:","options":{"A":"Na AR, a membrana sinovial caracteriza-se por uma neoformação vascular importante e uma\ninvasão marcante de células inflamatórias e imunes, formando um tecido chamado pannus.","B":"As articulações esternoclaviculares e manubrioesternal não são acometidas na AR por não\npossuírem sinóvia.","C":"Nódulos reumatoides, escleromalácia e doença pulmonar intersticial são manifestações\nextra-articulares da AR.","D":"A presença de Velocidade de Hemossedimentação (VHS) e Proteína C-Reativa (PCR) elevados,\ne Fator Reumatoide e Anti-CCP positivos ajudam\na caracterizar a natureza imunoinflamatória da\nAR.","E":"Metotrexato, Leflunomida e Hidroxicloroquina são fármacos antirreumáticos modificadores da\ndoença (DMARD)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-34168","number":"34168","sourceNumber":"34168","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher, 44 anos, lavadeira. Há 12 meses com dor difusa, sono não reparador,\n\n?dormências? (hipoestesia e parestesias) no 2º, 3º e 4º quirodáctilos direitos. Refere dor discreta\nno punho D e face anterior do antebraço D. Piora\nquando trabalha muito (lava para fora; não tem\nmáquina; esfrega a roupa, torce, pendura no varal e passa a ferro). Piora também na fase\n\npré-menstrual (tem 6 filhos e fez ligadura tubária). Exames complementares de laboratórios são\ntodos normais. O que falta para concluir o diagnóstico?","options":{"A":"A presença de 11 pontos dolorosos é sugestiva de fibromialgia.","B":"A presença de ácido úrico no sangue confirma o diagnóstico de Artrite gotosa.","C":"A presença de Anticorpo Antinuclear confirma o diagnóstico de LES.","D":"A presença de Fator Reumatoide confirma o diagnóstico de Artrite Reativa.","E":"Densitometria óssea, pois o diagnóstico mais provável é o de osteoporose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-26448","number":"26448","sourceNumber":"26448","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma mulher 72 anos é atendida com queixa de dor aguda, iniciada há dois dias, no\njoelho direito, que apresenta calor local pouco intenso. Exames laboratoriais revelam em\nhematócrito de 38%, 10.500 leucócitos com 70% de neutrófilos segmentados e 4% de bastonetes;\nácido úrico de 5,5 mg/dl. A radiografia de joelhos demonstra presença de condrocalcinose. O\ndiagnóstico mais provável é de:","options":{"A":"Artrite gotosa aguda.","B":"Pseudogota.","C":"Artrite reativa.","D":"Artrite reumatoide.","E":"Artrite infecciosa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-26594","number":"26594","sourceNumber":"26594","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A síndrome de Reiter pode ser complicada por, exceto:","options":{"A":"Ulcerações orais indolores.","B":"Pericardite.","C":"Anomalias de Condução Cardíaca.","D":"Psoríase ampla.","E":"Hiperuricemia."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-26686","number":"26686","sourceNumber":"26686","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"No tratamento da Febre Reumática, não está correta a seguinte afirmativa:","options":{"A":"Os corticoides devem ser usados sempre que se confirmar o diagnóstico clínico e laboratorial de\nfebre reumática","B":"O tratamento com agentes anti-inflamatórios é eficaz para suprir muitos dos sinais e sintomas de\nfebre reumática aguda","C":"Pacientes com coreia de sydenham requerem um ambiente tranquilo e sedativos como\nfenobarbital ou diazepam","D":"Indivíduos alérgicos à penicilina podem ser tratados com eritromicina 40 mg/Kg/dia (dose\nmáxima = 100 mg) divididos em 2-4 doses ou um\ncurso de 10 dias de uma cefalosporina de baixo\nespectro","E":"Os antibióticos não modificam a evolução de um episódio reumático nem influenciam o\ndesenvolvimento subsequente de cardite"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-9993","number":"9993","sourceNumber":"9993","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quais os critérios maiores de Jones na sua fase inicial da febre reumática?","options":{"A":"Cardite, coreia, febre.","B":"Febre, coreia, eritema marginado.","C":"Cardite, coreia, eritema marginado.","D":"Cardite, artralgia, coreia.","E":"Artralgia, nódulos subcutâneos, febre."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-10011","number":"10011","sourceNumber":"10011","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A síndrome de Reiter pode ser complicada por, EXCETO:","options":{"A":"Ulcerações orais indolores.","B":"Nefropatia por depósitos mesangiais de IgA.","C":"Iridociclite.","D":"Anomalias de condução cardíaca.","E":"Hiperuricemia."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-49366","number":"49366","sourceNumber":"49366","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, 13 anos de idade, sexo masculino, apresentou, há quatro semanas,\nmovimentos espontâneos incoordenados, que melhoram\nno repouso e se agravam no estímulo do\nexame. Recebe o diagnóstico de Coreia de Syndeham, CS. A respeito dessa patologia, é incorreto\nafirmar:","options":{"A":"A coreia de Syndeham ocorre predominantemente em lactentes menores de dois meses de\nidade.","B":"Embora possa ocorrer como manifestação isolada de FR, a CS se apresenta, com frequência,\nassociada à cardite clínica ou subclínica e, mais raramente, à artrite.","C":"Pode aparecer no início do surto, mas geralmente ocorre como manifestação tardia até sete\nmeses após a infecção estreptocócica.","D":"Nos casos em que a coreia é a única manifestação da FR ou é acompanhada somente por\nartrite, deve ser solicitado, se possível, o\nanticorpo antinúcleo para descartar a possibilidade de\nlúpus eritematoso sistêmico, pois anticorpos anticardiolipina têm sido descritos em pacientes com\nCS.","E":"O surto de coreia dura, em média, de dois a três meses, mas pode prolongar-se por mais de um\nano, em alguns casos também foram descritas manifestações neuropsiquiátricas, como tiques e\ntranstorno obsessivo compulsivo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-49379","number":"49379","sourceNumber":"49379","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, 13 anos de idade, sexo masculino, apresentou, há quatro semanas,\nmovimentos espontâneos incoordenados, que melhoram\nno repouso e se agravam no estímulo do\nexame. Recebe o diagnóstico de coreia de Syndeham, CS. Em relação ao tratamento dessa\npatologia, é incorreto afirmar:","options":{"A":"Os fármacos mais utilizados no controle dos sintomas da coreia são haloperidol, ácido valproico\ne carbamazepina.","B":"Existem evidências suficientes para a indicação de outras terapias, nas formas graves, em\nespecial a gamaglobulina endovenosa.","C":"Na coreia leve e moderada, estão indicados repouso e a permanência do paciente em ambiente\ncalmo, evitando-se estímulos externos, os benzodiazepínicos e o fenobarbital também podem ser\nutilizados.","D":"O tratamento para a erradicação do estreptococo da orofaringe deve ser feito na vigência da\nsuspeita clínica da FR independentemente do resultado da cultura de orofaringe.","E":"O objetivo de tratamento para a erradicação do estreptococo visa reduzir a exposição antigênica\ndo paciente e impedir a propagação de cepas\nreumatogênicas na comunidade."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-49308","number":"49308","sourceNumber":"49308","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, cinco anos de idade, sexo masculino, pardo, internado com história de febre e\ndor articular há seis meses. A dor iniciou nos braços, evoluindo para pernas, tornozelos e pescoço,\ncom edema e calor nas articulações dos cotovelos, punhos, mãos, joelhos e tornozelos, com\nrestrição de movimentos. Tem história de exantema maculopapular em tronco, que durou duas\nsemanas. REG, descorado ++/IV, febril, emagrecido, limitação na extensão da coluna cervical,\nfígado palpável a 2 cm de RCD. Exames: Hb = 6,8; Ht = 23; leuc. = 10.700 (Bt. = 0%, seg. = 46%,\neos. = 3%, linf. = 43%, mon. = 8%); reticulócitos = 1,1%; plaq. = 959.000/mm³; VHS = 37;\ncoagulograma normal; função renal e função hepática normais; fator reumatoide negativo;\nultrassonografia do joelho esquerdo: derrame articular. O diagnóstico mais provável é:","options":{"A":"FR.","B":"AIJ.","C":"Osteomielite aguda.","D":"Osteopenia própria da infância.","E":"Dor do crescimento."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-34971","number":"34971","sourceNumber":"34971","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, 5 anos de idade, vem há quatro meses com dor articular e febre em picos\ndiários. Ao exame, FC: 128 bpm, FR: 26 ipm,\nfebril, edema e calor em joelho e tornozelo\nesquerdos, ausculta cardíaca com bulhas abafadas, sem sopros. Hemograma com Hb de 12, série\nbranca e plaquetas normais, VHS elevado. Reticulócitos normais. O quadro apresentado sugere:","options":{"A":"doença de Kawasaki.","B":"febre reumática.","C":"AIJ.","D":"citomegalovirose aguda.","E":"esferocitose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-27477","number":"27477","sourceNumber":"27477","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, 8 anos de idade, sexo masculino, apresentou, há 4 semanas, febre elevada,\nartralgia com presença de sinais\nflogísticos, que afetavam articulações dos joelhos, posteriormente\ntornozelos e cotovelos, impedindo os movimentos. A ausculta cardiopulmonar com presença de SS\nem foco mitral, taquicardia e 3ª bulha. O ecocardiograma revela discreto derrame pericárdico com\ninsuficiência mitral. Em relação à patologia descrita, é incorreto afirmar:","options":{"A":"Os critérios diagnósticos são apenas um instrumento auxiliar, uma vez que não há testes\nlaboratoriais, sinais ou sintomas clínicos que, isoladamente, sejam patognomônicos da doença.","B":"Na coreia de apresentação tardia e cardite insidiosa, os outros achados clínicos podem estar\nausentes e os laboratoriais normais.","C":"A cultura de orofaringe continua sendo o padrão-ouro para o diagnóstico, embora só seja\npositivo na fase aguda em cerca de 25% dos casos.","D":"Os testes rápidos para identificação do agente, a partir de material colhido na orofaringe, com\nresultados imediatos, têm a vantagem de ser altamente específicos, mas nem sempre muito\nsensíveis.","E":"Devido às baixas condições socioeconômicas da população brasileira, é frequente se\nencontrarem níveis de antiestreptolisina O\n(ASLO) baixos em relação ao que se considera normal."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-11193","number":"11193","sourceNumber":"11193","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, 10 anos de idade, apresenta edema, cansaço fácil e mal-estar há mais de 2\nsemanas, diurese diminuída. Passado de amigdalites. Ao exame físico, mostra regular estado geral,\ntemperatura de 37,5ºC, edema bipalpebral e de MMII. Ausculta cardiopulmonar com F.C. > 160\nbat/min, F.R > 30 inc/min. Murmúrio rude e roncos com presença de terceira bulha, sopro sistólico\naudível em ponta. Abdome com fígado aumentado a 5 cm do RCD, doloroso à palpação. A causa\nmais provável desse quadro é:","options":{"A":"CIV","B":"coarctação da aorta","C":"infecção pulmonar","D":"doença de Kawasaki","E":"febre reumática"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-11194","number":"11194","sourceNumber":"11194","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, 10 anos de idade, apresenta edema, cansaço fácil e mal-estar há mais de 2\nsemanas, diurese diminuída. Passado de amigdalites. Ao exame físico, mostra regular estado geral,\ntemperatura de 37,5ºC, edema bipalpebral e de MMII. Ausculta cardiopulmonar com F.C. > 160\nbat/min, F.R > 30 inc/min. Murmúrio rude e roncos com presença de terceira bulha, sopro sistólico\naudível em ponta. Abdome com fígado aumentado a 5 cm do RCD, doloroso à palpação. A\nprofilaxia recomendada para esse paciente, segundo recomendação da American Heart\nAssociation, é usar penicilina:","options":{"A":"até 21 anos","B":"por, pelo menos, 10 anos depois desse período","C":"por toda a vida","D":"por 20 anos","E":"por 15 anos"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-343338","number":"343338","sourceNumber":"343338","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"HMN, masculino de 57 anos, grande tabagista e obeso, analisando se ECG foi\nencontrado Sobrecarga Atrial Esquerda (SAE) com onda\nP com componente negativo aumentado\n(final lento e profundo) na derivação V1. Podemos indicar como correto que:","options":{"A":"A área da fase negativa de pelo menos 0,09 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta melhor\nsensibilidade que o critério isolado de duração aumentada.","B":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 11 mm2, constitui o\nÍndice de Morris, que apresenta melhor sensibilidade que o critério isolado de duração aumentada.","C":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta pior sensibilidade que o critério isolado de duração aumentada.","D":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta melhor sensibilidade que o critério isolado de duração aumentada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-343343","number":"343343","sourceNumber":"343343","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobrecarga Atrial Direita (SAD), está de acordo com o seguinte item correto:","options":{"A":"A onda P apresenta-se não apiculada com amplitude acima de 0,25 mV ou 2,5 mm.","B":"A onda P apresenta-se apiculada com amplitude acima de 0,25 mV ou 2,5 mm.","C":"A onda P apresenta-se apiculada com amplitude abaixo de 0,25 mV ou 2,5 mm.","D":"A onda P apresenta-se apiculada com amplitude acima de 0,25 mV ou 3,5 mm."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249970","number":"249970","sourceNumber":"249970","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Infelizmente os dados na literatura quanto à incidência de PCR no Brasil são escassos.\nPodemos entretendo indicar que ocorre erro no\nitem:","options":{"A":"O principal ritmo de PCR em ambiente extra-hospitalar não é a Fibrilação Ventricular (FV) e sim\na Taquicardia Ventricular (TV).","B":"A Fibrilação Ventricular (FV) e a Taquicardia Ventricular (TV), juntas chegando a quase 80% dos\neventos.","C":"A Fibrilação Ventricular (FV) e a Taquicardia Ventricular (TV) apresentam um bom índice de\nsucesso na reversão, se prontamente tratados.","D":"Quando a desfibrilação é realizada precocemente, em até 3 a 5 minutos do início da PCR, a taxa\nde sobrevida é em torno de 50% a 70%."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-215593","number":"215593","sourceNumber":"215593","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"As crianças que recebem assistência ventilatória domiciliar devem ter sempre\ndisponíveis os seguintes materiais, EXCETO:","options":{"A":"Oxigênio suplementar.","B":"Monitor de eletrocardiograma.","C":"Bolsa autoinflável e máscara.","D":"Oxímetro de pulso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-215568","number":"215568","sourceNumber":"215568","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao suporte ventilatório em portadores de\ninsuficiência respiratória crônica.","options":{"A":"As necessidades do indivíduo, além da estrutura domiciliar e do seguimento pela equipe de\nsaúde, devem ser levadas em conta no momento\nda decisão sobre a modalidade ventilatória a ser\nutilizada.","B":"As falhas repetidas de extubação traqueal ou da retirada de suporte não invasivo precedem à\ndecisão pela desospitalização ainda em uso desse suporte.","C":"O processo de suporte ventilatório domiciliar tem início no momento da alta do paciente.","D":"Antes da hospitalização é realizada a transição para o ventilador de uso domiciliar, com\ndeterminação das demandas específicas de cada indivíduo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157723","number":"157723","sourceNumber":"157723","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente procurou serviço médico com quadro de tonturas que foram piorando nos\núltimos dias. Como em sua ausculta cardíaca\nfoi constatado ritmo cardíaco irregular, foi feito o ECG\nque demonstrou bradiarritmia. Acerca desse caso, marque a opção CORRETA:","options":{"A":"Bloqueio atrioventricular de segundo grau tipo I eletrocardiograficamente caracteriza-se pelo\naumento progressivo do intervalo PR, acarretando em uma onda P ?bloqueada?, ou isolada,\ngerando uma pausa no traçado do ECG e se relaciona com situações em que há aumento\nimportante do tônus vagal.","B":"Bloqueio atrioventricular de segundo grau tipo II é considerado de menor gravidade que o do tipo\n\nI. Pode localizar-se dentro do feixe de His, sendo o QRS estreito nestes casos. Quando está\nlocalizado abaixo do feixe de His, o QRS é largo.","C":"A presença do BAV de segundo grau tipo II indica doença do sistema His-Purkinje, sendo o\npaciente assintomático. Não indica intervenção.","D":"Quando o BAV é acompanhado por bloqueio de ramo, como bloqueio de ramo direito ou\nesquerdo, a possibilidade de ser uma lesão no sistema His-Purkinje é menor."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-350882","number":"350882","sourceNumber":"350882","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Especialistas recomendam que várias ?camadas de proteção? sejam usadas para\nprevenção de afogamentos, pois raramente são causados por um único fator. Das ações de\nprevenção elencadas abaixo qual tem o potencial isoladamente de prevenir mais de 50% dos\nafogamentos em crianças?","options":{"A":"Dispositivos de flutuação pessoal tipo boias de braços.","B":"Cercas de proteção com pelo menos de 1,5 m de altura.","C":"Aulas de natação para crianças menores de 4 anos.","D":"Supervisão, principalmente, aos maiores de 5 anos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-321298","number":"321298","sourceNumber":"321298","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem, 67 anos, tabagista, hipertenso e dislipidêmico, procurou pronto-atendimento\npor mal-estar, palpitações e dispneia. Refere\nepisódios prévios autolimitados, com duração de 5\nminutos. Paciente acordado, porém letárgico. PA 90x50 mmhg, SpO? 95%. Realizou o seguinte\nECG, na triagem: Assinale a conduta adequada no momento.","options":{"A":"Manobra vagal e diltiazem endovenoso; evitar betabloqueadores pelo risco de DPOC.","B":"Desfibrilação elétrica sem necessidade de anticoagulação devido risco iminente de morte.","C":"Cardioversão elétrica imediata e anticoagulação para prevenção de fenômenos\ntromboembólicos.","D":"Solução cristaloide endovenosa para estabilização hemodinâmica e investigação de\nhipertireoidismo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-321313","number":"321313","sourceNumber":"321313","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 26 anos, sexo masculino, acompanhado por esquizofrenia é atendido na\nemergência por importante agitação. Foi realizada contenção física e administrado 10mg de\nhaloperidol. Após 30 minutos, paciente está torporoso, pouco responsivo, com pressão arterial de\n60x30mmHg, taquicárdico com pulso filiforme, saturação periférica de O2 de 95%. Ainda não há\nexames laboratoriais disponíveis. Eletrocardiograma realizado foi o seguinte: Qual a melhor\nconduta a ser adotada?","options":{"A":"Infusão de sulfato de magnésio.","B":"Infusão de cloreto de potássio.","C":"Imediata cardioversão elétrica.","D":"Imediata desfibrilação."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-292822","number":"292822","sourceNumber":"292822","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem, 70 anos, procura atendimento médico em Unidade Básica de Saúde devido a\nepisódio de fraqueza em hemicorpo à direita e dificuldade na fala, durante 1 hora, que aconteceram\nhá duas semanas. Paciente procurou, naquela ocasião, emergência médica onde fez tomografia de\ncrânio e doppler de carótidas e vertebrais com laudos normais, exames de sangue que não\nmostraram alterações, e eletrocardiograma que mostrou fibrilação atrial. Paciente optou por não\npermanecer internado, saiu do hospital sem nenhuma prescrição médica e veio à consulta hoje,\ndevido ao \"medo de sentir novamente os sintomas\" e querendo saber qual o melhor tratamento que\ndeve fazer para evitar essa recorrência. Tem antecedente de febre reumática com necessidade de\ntroca valvar (válvula metálica) há 5 anos, mas vinha em uso irregular de suas medicações. No\nmomento está sem utilizar nenhuma. Pulso: 80bpm, PA:120x80mmHg. Exame neurológico sem\nalterações. Qual medicação está indicada para a profilaxia secundária, nesse paciente?","options":{"A":"Ácido acetil salicílico.","B":"Clopidogrel.","C":"Apixabana.","D":"Varfarina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-292823","number":"292823","sourceNumber":"292823","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher, 56 anos, hipertensa e diabética chegou na emergência referindo palpitação e\ntaquicardia há 3 dias. Refere episódios semelhantes, esporadicamente, que costumam melhorar\nespontaneamente, porém o episódio atual não melhorou, procurando então a emergência. Chegou\ncom pressão arterial = 120 x 80 mmHg, frequência cardíaca = 140 batimentos por minuto e o\neletrocardiograma está apresentado abaixo. Qual é a melhor conduta para essa paciente?","options":{"A":"Cloridrato de amiodarona endovenoso e ablação posterior.","B":"Cloridrato de amiodarona endovenoso e anticoagulação.","C":"Tartarato de metoprolol endovenoso e anticoagulação.","D":"Cardioversão elétrica com 100 J e anticoagulação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-234032","number":"234032","sourceNumber":"234032","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, 52 anos, sexo masculino, previamente hígido, assintomático, comparece à\nconsulta de rotina no ambulatório. Ao exame físico, chamam atenção sopro em ruflar diastólico\n3+/6+ no foco mitral e ritmo cardíaco irregular com frequência cardíaca em torno de 84 batimentos\npor minuto. Realizado eletrocardiograma (figura abaixo) e ecocardiograma transtorácico que\nevidenciou estenose mitral moderada. Qual conduta deve ser tomada nesse momento?","options":{"A":"Iniciar uso de rivaroxaban sem necessidade de monitoração do INR.","B":"Iniciar warfarin e realizar a monitorização do INR ambulatorialmente.","C":"Internar o paciente para administrar enoxaparina e iniciar uso de warfarin.","D":"Manter conduta expectante, pois o paciente apresenta baixo risco de complicações."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-199664","number":"199664","sourceNumber":"199664","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Criança de 5 anos foi encontrada inconsciente na piscina por vigilante de um\ncondomínio e foi removida rapidamente para a unidade de pronto atendimento. Não se sabe o\ntempo de duração do afogamento. Qual é a causa mais comum de morbimortalidade em\nhospitalizados afogados?","options":{"A":"Distúrbio hidroeletrolítico por aspiração de água.","B":"Insuficiência cardíaca com edema agudo de pulmão.","C":"Laringoespasmo seguido de relaxamento da laringe com aspiração de água.","D":"Desenvolvimento de encefalopatia por hipóxia, com ou sem edema cerebral."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-150870","number":"150870","sourceNumber":"150870","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente masculino, 63 anos, é trazido à Unidade Básica de Saúde pela filha que\ninforma que o pai é \"um paciente\ncomplicado\" e que raramente procura o serviço de saúde.\nMorador de zona rural, de difícil acesso e transporte, é hipertenso, dislipidêmico, obeso,\nsedentário,\ntabagista de 2 maços/dia, e apresenta-se com queixa de palpitações associadas à \"falta de ar\" há 4\nmeses. Refere que esses eventos ocorrem 2 a 3 vezes por semana, sendo mais frequentes nas\nsegundas-feiras. Durante um desses episódios, foi levado ao serviço de emergência do município e\nrealizou um ECG (VER IMAGEM). No momento, não tem queixas de palpitações. Faz uso de\nenalapril, hidroclorotiazida e atorvastatina. Ingere cerca 8 a 10 unidades de álcool nos finais de\nsemana. Ao exame físico, encontra-se com PA sentado 126 x 94 mmHg. Peso 80 kg. Altura 165\ncm. Apresenta ausculta cardíaca com ritmo cardíaco regular e frequência de 82 bpm. Sopro\nsistólico 3+/6+ em foco aórtico com irradiação para pescoço. Os pulsos são palpáveis, têm\nascensão lenta e são regulares, congruentes com ausculta. Índice Tornozelo Braquial foi 0,8 e 0,94\npara membro inferior direito e esquerdo, respectivamente. Os exames laboratoriais trazidos não\nevidenciam alterações nas provas de coagulação ou função hepática. Creatinina 1,6 mg/dL. Qual\ndeve ser a prescrição farmacológica com ênfase na prevenção de eventos\nvasculares/tromboembólicos?","options":{"A":"Aspirina 325 mg/dia.","B":"Cilostazol 200 mg/dia.","C":"Aspirina 100 mg/dia e Clopidogrel 75 mg/dia.","D":"Varfarina 5 mg/dia (manter INR entre 2,0 e 3,0)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-102095","number":"102095","sourceNumber":"102095","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher, 50 anos, tem artrite reumatoide em tratamento com prednisona há 10 anos,\napresenta edema, dor e rubor de joelho\ndireito com piora progressiva há três dias. Ao exame físico,\ntem dificuldade em flexionar o joelho acometido. A punção do líquido sinovial revela 110.000\nleuc/mm³, níveis elevados de proteínas e diminuídos de glicose. Qual a hipótese diagnóstica mais\nprovável e conduta mais indicada?","options":{"A":"Atividade da artrite reumatoide e iniciar infliximabe.","B":"Atividade da artrite reumatoide e iniciar metotrexato.","C":"Artrite séptica, drenagem cirúrgica e antibioticoterapia.","D":"Pseudogota, iniciar colchicina e anti-inflamatório não hormonal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-81297","number":"81297","sourceNumber":"81297","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Garota de 10 anos de idade é levada ao ambulatório com história de dor em membros\nhá dois meses e dificuldade para se\nmovimentar, principalmente pela manhã e após repouso.\n\nRefere ainda febre diária associada a exantema em tronco e membros. O exame físico revelou\nartrite em joelho e tornozelo direito.\nHemograma com anemia normocrômica e normocítica,\nleucocitose discreta sem desvio à esquerda e trombocitose. A dosagem de antiestreptolisina O está\nnormal, VHS e PCR aumentados. A radiografia do joelho apresenta erosão e diminuição da\ndensidade óssea em torno da articulação e diminuição do espaço articular. Considerando o quadro\nacima descrito, qual a hipótese diagnóstica mais provável?","options":{"A":"Artrite séptica.","B":"Febre reumática.","C":"Artrite idiopática juvenil.","D":"Lúpus eritematoso sistêmico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-65720","number":"65720","sourceNumber":"65720","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem de 65 anos apresenta artrite aguda do joelho esquerdo. A artrocentese\nevidenciou líquido sinovial amarelo turvo, com\n35000 céls/mm³, sendo 70% de polimorfonucleares.\nA microscopia de luz polarizada mostrou cristais com forma de bastões romboides e com\nbirrefringência fracamente positiva. O diagnóstico mais provável é:","options":{"A":"osteoartrite.","B":"artrite gotosa.","C":"pseudogota.","D":"artrite reativa.","E":"artrite infecciosa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-51263","number":"51263","sourceNumber":"51263","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 50 anos, em programa de hemodiálise há 5 anos, é avaliado por queixa de\ndor lombar com características inflamatórias.\nO exame físico mostra alterações nos testes de\nSchober e Patrick. Radiografia das articulações acometidas revelou-se normal. Qual dos exames\nde imagem abaixo deve ser solicitado para prosseguir avaliação das articulações acometidas desse\npaciente?","options":{"A":"Artrografia.","B":"Ultrassonografia.","C":"Tomografia Computadorizada.","D":"Ressonância Nuclear Magnética."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-45381","number":"45381","sourceNumber":"45381","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 56 anos é atendido por dor em joelho direito. Refere que o quadro surgiu\nhá dois dias, porém a dor vem piorando\nprogressivamente e constatou febre (38ºC) na noite\nanterior. Relata ser portador de gota, porém faz uso diário de alopurinol 300 mg há 3 anos, com\núltima crise há mais de um ano. O exame físico é inalterado, exceto por artrite de joelho direito. A\nanálise do líquido sinovial foi a seguinte: 130.000 células com predominância de\npolimorfonucleares, presença de cristais em agulha sem birrefrigência à luz polarizada e presença\nde cocos Gram-positivos em pesquisa direta. Qual a principal conduta a ser tomada?","options":{"A":"Iniciar antibiótico endovenoso.","B":"Iniciar anti-inflamatório não esteroidal.","C":"Iniciar corticoide oral.","D":"Iniciar colchicina.","E":"Solicitar avaliação ortopédica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-30862","number":"30862","sourceNumber":"30862","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Como é executado o teste de Tinel na investigação clínica da síndrome do túnel do\ncarpo?","options":{"A":"Digitopercussão sobre o nervo mediano ao nível do punho.","B":"Flexão do punho em 90 graus durante 1 minuto.","C":"Preensão firme dos dedos sobre polegar e flexão da mão.","D":"Levantamento de peso com punho reto por 3 minutos.","E":"Flexão-extensão repetitiva do punho por 1 minuto."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-36986","number":"36986","sourceNumber":"36986","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 56 anos comparece com relato de dor intensa, eritema e edema na primeira\narticulação metatarsofalangeana esquerda. Tem índice de massa corporal de 38 kg/m². Seus\nexames revelam ácido úrico de 9,0 mg/dl. Qual das drogas abaixo é a melhor escolha terapêutica\nnesse momento da doença?","options":{"A":"Colchicina.","B":"Alopurinol.","C":"Metilprednisolona.","D":"Anti-inflamatório não esteroide."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-37431","number":"37431","sourceNumber":"37431","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre quadro clinicolaboratorial da artrite séptica, assinale alternativa INCORRETA:","options":{"A":"Geralmente tem início agudo e acometimento\nmonoarticular.","B":"Staphilococcus aureus é o principal agente etiológico.","C":"Joelhos, quadris, punhos e ombros são as articulações mais frequentemente envolvidas.","D":"Cefepime e metronidazol estão entre os antibióticos de primeira escolha para o tratamento.","E":"Líquido sinovial com celularidade acima de 50.000 leucócitos com predomínio de\npolimorfonucleares são achados frequentes."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-36964","number":"36964","sourceNumber":"36964","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Menina de 8 anos, há 7 semanas vem evoluindo com dor, edema, calor e diminuição da\nfunção acometendo 4 articulações (punhos e interfalangeanas). Na avaliação oftalmológica foi\nevidenciada uveíte. Que exame laboratorial tem maior chance de ser positivo?","options":{"A":"Fator reumatoide.","B":"Anticorpo anticardiolipina.","C":"Fator antinuclear.","D":"Anticorpo antifosfolípide."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-30888","number":"30888","sourceNumber":"30888","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 28 anos comparece com poliartrite acometendo metacarpofalangeanas,\ninterfalangeanas proximais, punhos e cotovelos,\nhá três meses. Refere ainda rigidez matinal\ndurando cerca de 50 min. Tem um hemograma normal, anticorpo Anti-CCP positivo e VHS de 70\nmm/h. Com base nos dados acima, qual o melhor tratamento inicial?","options":{"A":"Prednisona + infliximab.","B":"Celecoxibe + leflunomide.","C":"Prednisona + metotrexate.","D":"Celecoxibe + infliximab.","E":"Leflunomide + metotrexate."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-37404","number":"37404","sourceNumber":"37404","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Criança de 04 anos, apresentando febre há mais de duas semanas. Ao exame físico,\nobservam-se erupções morbiliformes no tronco, poliartrite, hepatoesplenomegalia e polisserosite. O\ndiagnóstico mais provável é:","options":{"A":"Sepse.","B":"Febre reumática.","C":"Artrite reumatoide juvenil.","D":"Artrite pós-viral.","E":"Nenhuma das alternativas anteriores."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-30940","number":"30940","sourceNumber":"30940","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher, 32 anos, comparece com dor nas mãos e pés há seis dias, que limita suas\natividades, e lesões de pele. O exame\nfísico mostra edema, dor e eritema no dorso das mãos e pés\ncom pequenas pústulas necróticas nas palmas das mãos. Sua última menstruação terminou há três\ndias. Qual o melhor diagnóstico?","options":{"A":"Artrite psoriática.","B":"Artrite gonocócica.","C":"Gota.","D":"Artrite relacionada ao HIV.","E":"Doença de Still."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-29468","number":"29468","sourceNumber":"29468","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Droga de escolha para o tratamento da faringite estreptocócica:","options":{"A":"Penicilina;","B":"Eritromicina;","C":"Azitromicina;","D":"Cefalexina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-29469","number":"29469","sourceNumber":"29469","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A febre reumática é uma doença inflamatória desencadeada a partir de infecções\ncausadas pelo estreptococo beta-hemolítico do\ngrupo A em indivíduos geneticamente predispostos.\nOs critérios de Jones (manifestações maiores e menores) foram criados para aumentar a\nespecificidade do diagnóstico desta patologia, que é eminentemente clínico. Assinale a alternativa\nque contenha somente as manifestações maiores:","options":{"A":"Cardite, coreia, nódulos subcutâneos, eritema marginado e febre;","B":"Cardite, coreia, nódulos subcutâneos, artralgias e febre;","C":"Poliartrite, cardite, coreia, nódulos subcutâneos e eritema marginado;","D":"Poliartrite, VHS elevado, leucocitose, coreia e nódulos subcutâneos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-27696","number":"27696","sourceNumber":"27696","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 35 anos, sexo masculino, comparece ao ambulatório com queixa de dor\nlombar persistente há seis meses. Refere que a mesma é pior ao acordar e melhora ao longo do\ndia com movimentação ou exercícios. Procurou pronto-socorro há alguns meses, tendo recebido\nreceita de anti-inflamatório, do qual faz uso eventual com melhora parcial do quadro. Exame físico\nmostrou dor à palpação das articulações sacroilíacas e restrição da flexão da coluna (teste de\nSchober positivo). Exames laboratoriais recentes estão normais. Radiografia de tórax e de\nsacroilíacas estão normais. Considerando a principal hipótese diagnóstica para este paciente, qual\na conduta terapêutica mais adequada no momento?","options":{"A":"Iniciar corticoide oral.","B":"Iniciar sulfassalazina.","C":"Iniciar metotrexato.","D":"Iniciar antagonista de TNF.","E":"Iniciar anti-inflamatório em horários fixos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-29458","number":"29458","sourceNumber":"29458","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"São critérios menores de Jones para a classificação diagnóstica de Febre Reumática,\nEXCETO:","options":{"A":"Febre;","B":"Artralgia;","C":"Alongamento do espaço P-R no ECG;","D":"Cardite."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-25332","number":"25332","sourceNumber":"25332","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Menina 6 anos foi atendida com quadro de febre, dispneia, e sopro cardíaco. A\nradiografia de tórax apresentava cardiomegalia e sinais de edema agudo de pulmão. Há 18\ndias teve escarlatina. O quadro atual pode corresponder à:","options":{"A":"Cardiopatia congênita descompensada","B":"Pneumonia estafilocócia com insuficiência respiratória","C":"Síndrome da imunodeficiência adquirida","D":"Cardite Reumática","E":"Doença de Kawasaki com complicação cardiovascular"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-8838","number":"8838","sourceNumber":"8838","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher de 45 anos, previamente saudável, procura atendimento por dor em cotovelo e\nfebre. Refere inchaço, dor e vermelhidão no cotovelo direito há cerca de 24h, acompanhada de\nfebre de até 40 °C com calafrios. Exame físico evidencia sinais flogísticos em cotovelo direito com\ndemais articulações normais. Não há outros achados no exame físico. Exames laboratoriais\nevidenciam somente leucocitose de 16.000 células com desvio à esquerda (10% de bastões). Qual\na melhor conduta a ser adotada?","options":{"A":"Solicitar FAN, fator reumatoide e iniciar corticoide.","B":"Realizar artrocentese de cotovelo e iniciar antibiótico empírico.","C":"Realizar artrocentese de cotovelo e aguardar culturas.","D":"Solicitar FAN, fator reumatoide e iniciar anti-inflamatório não esteroide.","E":"Iniciar anti-inflamatório não esteroide e solicitar hemoculturas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-6953","number":"6953","sourceNumber":"6953","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher, 23 anos, tabagista 30 maços/ano, índice de massa corpórea = 30 kg/m²,\ncomparece ao seu consultório em uso de\nWarfarin por trombose venosa profunda no membro\ninferior esquerdo há 2 meses. Apresenta dosagem de anticardiolipina IgG de 60 unidades GPL.\nQuanto aos aspectos diagnósticos da síndrome do anticorpo antifosfolípide (SAAF) marque o\ncorreto:","options":{"A":"Sendo obesa, o anti-B2 glicoproteína é o melhor marcador e deve ser dosado duas semanas\napós o anticardiolipina.","B":"Só podemos definir SAAF com uso de dois marcadores clínicos distintos e devemos solicitar\nanticoagulante lúpico.","C":"Para o diagnóstico definitivo de SAAF necessitamos de nova dosagem de anticardiolipina com,\nno mínimo, 12 semanas após a primeira.","D":"Devemos suspender o Warfarin e repetir imediatamente o anticardiolipina que só terá valor se\nem título superior ao inicial.","E":"No caso em questão, o diagnóstico de SAAF já é definitivo, não necessitando de novas\navaliações."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-349742","number":"349742","sourceNumber":"349742","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma mulher de 58 anos apresentou-se à sala de emergência com palpitações intensas,\ndor torácica e dispneia. Ela relatou que as\npalpitações começaram repentinamente enquanto\nestava em repouso em casa. Não havia histórico prévio de arritmias. A seguir está o\neletrocardiograma realizado: Sinais vitais: frequência cardíaca estimada em cerca de 150 bpm;\npressão arterial: 80/50 mmHg. Assinale a alternativa que apresenta o diagnóstico e a conduta\nadequada para esse caso.","options":{"A":"Taquicardia supraventricular / Sedação leve e cardioversão química.","B":"Fibrilação atrial / Sedação leve e cardioversão elétrica.","C":"Flutter atrial / Desfibrilação.","D":"Taquicardia sinusal / Conduta expectante.","E":"Fibrilação atrial / Sedação leve e cardioversão química."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-349739","number":"349739","sourceNumber":"349739","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Diante de um atendimento a um paciente em parada cardiorrespiratória, o líder precisa\nconduzir a equipe que está realizando a Reanimação Cardiopulmonar (RCP). Qual é a maneira de\ncomunicação mais apropriada entre o líder e a equipe nessa situação?","options":{"A":"Apenas o líder da equipe possui a competência necessária para verbalizar informações,\ndevendo o restante da equipe permanecer em\nsilêncio durante todo o atendimento.","B":"O líder deve transmitir mensagens simultâneas a cada membro da equipe para que sejam\nevitados atos de procrastinação e a situação possa ser revertida o mais rápido possível.","C":"O líder deve transmitir uma mensagem, ordem ou atribuição a um membro da equipe; solicitar\numa resposta clara e contato visual do membro da\nequipe para garantir que tenha entendido a\nmensagem; confirmar que o membro da equipe concluiu a tarefa, antes de lhe atribuir outra tarefa.","D":"O líder deve elevar o tom de voz ao perceber que um dos membros da equipe não compreendeu\na ordem dada, a fim de que tal atitude não se\nrepita.","E":"É necessário que o líder reconheça sua equipe com elogios, como forma de incentivá-la quando\no atendimento é bem sucedido, bem como repreender\nem alto tom de voz ao perceber quaisquer\nfalhas durante o atendimento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-365613","number":"365613","sourceNumber":"365613","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante a assistência a um paciente em parada cardiorrespiratória no ambiente\nhospitalar, foi realizada a checagem de\nritmo, com o traçado apresentado. O ritmo representado no\ntraçado é.","options":{"A":"chocável e passível de pulso.","B":"não chocável e passível de pulso.","C":"não chocável e não passível de pulso.","D":"chocável e não passível de pulso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-365612","number":"365612","sourceNumber":"365612","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante a assistência a um paciente em parada cardiorrespiratória no ambiente\nhospitalar, foi realizada a checagem de ritmo,\ncom o traçado apresentado. No decorrer do manejo\nda parada cardiorrespiratória nesse ritmo, são indicados o uso de","options":{"A":"adrenalina e noradrenalina.","B":"adrenalina e amiodarona.","C":"atropina.","D":"adrenalina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-365635","number":"365635","sourceNumber":"365635","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma paciente de 43 anos de idade, com história de cardiopatia estrutural, procurou o\npronto-socorro queixando-se de desconforto torácico inespecífico e três pré-síncopes nas últimas\n12 horas. Na admissão, foi realizado eletrocardiograma (ECG) com o traçado apresentado.\n\nConsiderando esse caso e com base nesse traçado, é correto afirmar que se trata de","options":{"A":"ritmo sinusal normal.","B":"bloqueio atrioventricular de primeiro grau.","C":"bloqueio atrioventricular de segundo grau.","D":"bloqueio atrioventricular total."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-322152","number":"322152","sourceNumber":"322152","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem de 63 anos, recebendo medicação para dor epigástrica na sala de\nobservação do pronto atendimento, apresenta\num colapso ao levantar-se da poltrona. Qual é a\nconduta imediata mais adequada nesse caso?","options":{"A":"Realizar um eletrocardiograma de 12 derivações.","B":"Checar a responsividade.","C":"Aplicar 1 mg de epinefrina EV.","D":"Iniciar compressões torácicas.","E":"Solicitar avaliação da cardiologia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-337519","number":"337519","sourceNumber":"337519","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 80 anos foi encontrado em rua pública, e testemunhas disseram que ele\nestava caminhando quando subitamente caiu no chão, perdendo a consciência. No hospital, foi\nrealizado eletrocardiograma mostrado a seguir. Ao exame físico, sua pressão arterial era de\n80x40mmHg, havia estertores pulmonares em todos os segmentos pulmonares com turgência\njugular; sua glicemia estava normal. Durante seu atendimento, o paciente demonstrou ritmo\ncardíaco no monitor. Com base nos conhecimentos clínicos e nos eletrocardiogramas\napresentados, julgue o item a seguir: No eletrocardiograma número 2, o paciente apresenta\ntaquicardia ventricular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-337520","number":"337520","sourceNumber":"337520","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 80 anos foi encontrado em rua pública, e testemunhas disseram que ele\nestava caminhando quando subitamente caiu no chão, perdendo a consciência. No hospital, foi\nrealizado eletrocardiograma mostrado a seguir. Ao exame físico, sua pressão arterial era de\n80x40mmHg, havia estertores pulmonares em todos os segmentos pulmonares com turgência\njugular; sua glicemia estava normal. Durante seu atendimento, o paciente demonstrou ritmo\ncardíaco no monitor. Com base nos conhecimentos clínicos e nos eletrocardiogramas\napresentados, julgue o item a seguir: Na ausência de pulso no eletrocardiograma número 2,\ndeve-se realizar cardioversão elétrica sincronizada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-322164","number":"322164","sourceNumber":"322164","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem de 46 anos procura atendimento médico de urgência com queixa de\npalpitações e dor torácica do tipo aperto,\nde início há aproximadamente 1 hora. Seus sinais vitais\nsão aferidos: ? PA: 70x40mmHg (pressão arterial); ? FC: 190bpm (Frequência cardíaca); ? SatO2:\n86% (saturação de oxigênio). E o seu eletrocardiograma (ECG) é o seguinte: Nesse caso, conforme\nas informações apresentadas, é correto afirmar que","options":{"A":"se trata de uma taquicardia supraventricular, e o uso da manobra vagal modificada está\nindicado.","B":"a avaliação de um especialista deve ser prioritária.","C":"o uso de atropina 1mg endovenosa (EV) está indicado.","D":"a cardioversão elétrica sincronizada está indicada.","E":"um estudo eletrofisiológico deve ser realizado antes de qualquer intervenção terapêutica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-322174","number":"322174","sourceNumber":"322174","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Você está de férias, na praia, quando se depara com um afogamento. A vítima está\ndesacordada, parece ter 16 anos, aproximadamente, e está sendo retirada da água. Ela é colocada\nna areia, em decúbito dorsal, e você vai prestar o atendimento inicial. Uma ambulância já foi\nchamada e chegará em poucos minutos. Das alternativas a seguir, qual deve ser a sua próxima\natitude?","options":{"A":"Estabilização de cervical.","B":"Ventilação de resgate.","C":"Posicionar o paciente em decúbito lateral.","D":"Manobra de Helmlich.","E":"Compressões abdominais."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-305287","number":"305287","sourceNumber":"305287","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Qual das seguintes taquiarritmias apresenta complexo QRS estreito e regular?","options":{"A":"Fibrilação atrial.","B":"Torsades de pointes.","C":"Taquicardia atrial.","D":"Taquicardia de movimento circular antidrômica.","E":"Flutter atrial com bloqueio AV variado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-298858","number":"298858","sourceNumber":"298858","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente de 45 anos de idade vem apresentando sintomas de palpitação, mal-estar\ne sudorese profusa no decorrer da hemodiálise.\nEm cada sessão, são ultrafiltrados 4 litros em duas\nhoras e meia. Na última diálise, o paciente ficou com hipotensão = 85 mmHg x 40 mmHg, SatO2 =\n94% em ar ambiente e frequência cardíaca conforme o eletrocardiograma a seguir. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Provavelmente,\nno período do eletro de repouso, o intervalo PR seja normal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-298859","number":"298859","sourceNumber":"298859","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente de 45 anos de idade vem apresentando sintomas de palpitação, mal-estar\ne sudorese profusa no decorrer da hemodiálise.\nEm cada sessão, são ultrafiltrados 4 litros em duas\nhoras e meia. Na última diálise, o paciente ficou com hipotensão = 85 mmHg x 40 mmHg, SatO2 =\n94% em ar ambiente e frequência cardíaca conforme o eletrocardiograma a seguir. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Tratamento\ncom sotalol é o padrão-ouro, no caso desse paciente, para tratamento em longo prazo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-305291","number":"305291","sourceNumber":"305291","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem de 57 anos procura atendimento médico com queixa de palpitações e dor\ntorácica tipo aperto, de início há 30 minutos. Apresenta hipotensão (PA = 60 x 40 mmHg). Após\navaliar o ritmo mostrado a seguir, qual é a conduta mais adequada?","options":{"A":"Manobra vagal.","B":"Adenosina 6 mg EV em bólus.","C":"Amiodarona 150 mg EV em 30 minutos.","D":"Deslanosídeo 0,8 mg EV em blus.","E":"Cardioversão elétrica sincronizada."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-298860","number":"298860","sourceNumber":"298860","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente de 45 anos de idade vem apresentando sintomas de palpitação, mal-estar\ne sudorese profusa no decorrer da hemodiálise.\nEm cada sessão, são ultrafiltrados 4 litros em duas\nhoras e meia. Na última diálise, o paciente ficou com hipotensão = 85 mmHg x 40 mmHg, SatO2 =\n94% em ar ambiente e frequência cardíaca conforme o eletrocardiograma a seguir. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O risco de\nmorte súbita para esse paciente é elevado em relação à população normal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-298861","number":"298861","sourceNumber":"298861","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente de 45 anos de idade vem apresentando sintomas de palpitação, mal-estar\ne sudorese profusa no decorrer da hemodiálise.\nEm cada sessão, são ultrafiltrados 4 litros em duas\nhoras e meia. Na última diálise, o paciente ficou com hipotensão = 85 mmHg x 40 mmHg, SatO2 =\n94% em ar ambiente e frequência cardíaca conforme o eletrocardiograma a seguir. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Cardioversão é\no melhor tratamento para manejo agudo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-305305","number":"305305","sourceNumber":"305305","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem de aproximadamente 50 anos apresenta um colapso na recepção do\npronto-socorro e é levado diretamente para\na sala de emergência. Após verificar a responsividade,\nqual é a conduta mais adequada?","options":{"A":"Iniciar compressões torácicas.","B":"Aplicar duas ventilações de resgate.","C":"Acesso venoso calibroso e expansão volêmica.","D":"Eletrocardiograma de 12 derivações.","E":"Checar o pulso carotídeo e a respiração."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-274359","number":"274359","sourceNumber":"274359","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente masculino, 60 anos, foi admitido na urgência com quadro de taquiarritmia de\ninício recente, sintomática. Foi realizado o eletrocardiograma na admissão, que é apresentado em\nseguida. Analisando o eletrocardiograma e as alternativas a seguir, qual é o ritmo predominante\nmais provável que se apresenta?","options":{"A":"Taquicardia supraventricular de reentrada.","B":"Taquicardia ventricular.","C":"Flutter atrial.","D":"Fibrilação atrial.","E":"Ritmo juncional."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-255692","number":"255692","sourceNumber":"255692","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 35 anos de idade chega ao pronto-socorro com dor torácica em aperto,\nirradiada para membro superior esquerdo há duas horas. Foi realizado um eletrocardiograma de\nrepouso. Acerca desse caso clínico e tendo em vista os conhecimentos médicos correlatos,\nconsiderando o traçado eletrocardiográfico apresentado, julgue o item a seguir. No traçado\neletrocardiográfico, o paciente apresenta bloqueio atrioventricular de segundo grau.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-255712","number":"255712","sourceNumber":"255712","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 50 anos de idade com eritema marginatum, pancardite, nódulos\nsubcutâneos, febre e artralgia procurou o\nreumatologista para receber um diagnóstico. Além disso,\napresentava anúria e atrito pericárdico. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir. Artralgia é critério maior.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-255731","number":"255731","sourceNumber":"255731","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certo paciente de 10 anos de idade apresenta-se com febre e artrite. Além disso,\napresenta episódio prévio comprovado de\ninfecção estreptocócica. Seu eletrocardiograma\ndemonstrava um intervalo PR maior que 0,2 ms e o ecocardiograma estava normal. Apresenta\nhemograma de 9.5 g/dL, ferritina sérica de 12 microgramas/L e RDW era aumentado. No que se\nrefere a esse caso clínico e aos conhecimentos médicos correlatos, julgue o item a seguir. O\npaciente deverá fazer profilaxia até os 25 anos de idade por apresentar alteração cardíaca de alto\nrisco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-255732","number":"255732","sourceNumber":"255732","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certo paciente de 10 anos de idade apresenta-se com febre e artrite. Além disso,\napresenta episódio prévio comprovado de infecção\nestreptocócica. Seu eletrocardiograma\ndemonstrava um intervalo PR maior que 0,2 ms e o ecocardiograma estava normal. Apresenta\nhemograma de 9.5 g/dL, ferritina sérica de 12 microgramas/L e RDW era aumentado. No que se\nrefere a esse caso clínico e aos conhecimentos médicos correlatos, julgue o item a seguir.\n\nProvavelmente trata-se de talassemia, e o tratamento depende da severidade dos sintomas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-211957","number":"211957","sourceNumber":"211957","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Determinado paciente, atleta de alto rendimento não profissional, compareceu ao\nconsultório médico para fazer avaliação clínica, pois está sentindo tonteira e mal-estar e relata\nfadiga durante exercícios ergométricos. Realizou teste ergométrico com o seguinte resultado:\ntaquicardia ventricular polimórfica catecolaminérgica, conforme a figura apresentada. Nesse caso\nclínico, ao ser questionado acerca de quando o paciente poderá voltar a fazer atividade física em\ncompetição, o médico deve responder que o paciente:","options":{"A":"Poderá praticar todos os exercícios físicos competitivos.","B":"Poderá realizar esportes competitivos de baixa intensidade.","C":"Poderá fazer todos os esportes, com restrição somente aos praticados em ambientes perigosos.","D":"Não poderá praticar qualquer esporte competitivo.","E":"Deve fazer apenas esportes competitivos de baixa intensidade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-212003","number":"212003","sourceNumber":"212003","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante reanimação de um paciente previamente hígido, internado para avaliação\npressórica, o quadro evoluiu com parada cardiorrespiratória e ressuscitação por 17 minutos,\n\nbem-sucedida. O paciente evolui com estabilidade pressórica, pressão arterial invasiva (PAI) = 84\nmmHg, FC = 102 bpm e SatO? = 96% sob ventilação mecânica em via aérea definitiva. Intensivista\ndecidiu então fazer hipotermia, com temperatura entre 32°C e 34°C, pois o ritmo inicial era\nfibrilação ventricular. No que tange a esse caso clínico, assinale a alternativa que equivale a\npossíveis complicações dessa terapêutica.","options":{"A":"Nova parada cardíaca pelo resfriamento do sistema nervoso central.","B":"Crises hipertensivas e convulsivas.","C":"Coagulopatia e risco do aumento de infecção.","D":"Quadros álgicos intensos com fratura de ossos instáveis.","E":"Melhora clínica rápida com menos de oito horas de evolução e extubação acidental."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-214498","number":"214498","sourceNumber":"214498","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Determinada paciente de 22 anos de idade chega ao posto de saúde da família com\nhistórico de ocorrências de dores musculares e episódios intermitentes de dores em punhos e em\nmãos bilateralmente e simetricamente no último mês. Relata os episódios de dor como\nindependentes da realização de esforços. Refere ter percebido, no último mês, o surgimento de\nregiões de hiperemia e lesões de pele escamosas em cotovelos, mãos e no couro cabeludo. Ao\nexame, apresenta-se em bom estado geral, corada, hidratada, eupneica em ar ambiente, com PA =\n110 mmHg x 70 mmHg, FC = 74 bpm, FR = 21 irpm e SatO? = 98%.. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o item a seguir. A presença de\nhemossedimentação aumentada e de um fator reumatoide positivo não tem utilidade na\ndiferenciação entre artrite psoriática e artrite reumatoide, pois ambas são artrites soropositivas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-196706","number":"196706","sourceNumber":"196706","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certa paciente de 62 anos de idade, com histórico de hipertensão arterial sistêmica e\ndiabetes mellitus tipo 2, assintomática no momento, traz Eletrocardiograma (ECG) de 12\nderivações, solicitado por médico em consulta anterior. Com base nesse caso clínico, e\nconsiderando-se a reprodução do ECG apresentado, mediante a utilização da diretriz de\ninterpretação de eletrocardiograma de repouso, da Sociedade Brasileira de Cardiologia, julgue o\nitem a seguir. Considere: FC = 51 spm; intervalo PR = 195ms; intervalo QRS = 130ms; intervalo QT\n\n= 440ms. Observa-se um bloqueio divisional posteroinferior esquerdo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-196614","number":"196614","sourceNumber":"196614","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certa paciente de 62 anos de idade, com histórico de hipertensão arterial sistêmica e\ndiabetes mellitus tipo 2, assintomática no momento, traz Eletrocardiograma (ECG) de 12\nderivações, solicitado por médico em consulta anterior. Com base nesse caso clínico, e\nconsiderando-se a reprodução do ECG apresentado, mediante a utilização da Diretriz de\nInterpretação de Eletrocardiograma de Repouso, da Sociedade Brasileira de Cardiologia, julgue o\nitem a seguir. Considere: FC = 51 bpm; intervalo PR = 195ms; intervalo QRS = 130ms; intervalo QT\n\n= 440ms. Verifica-se um bloqueio atrioventricular de primeiro grau.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-196623","number":"196623","sourceNumber":"196623","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certa paciente de 62 anos de idade, com histórico de hipertensão arterial sistêmica e\ndiabetes mellitus tipo 2, assintomática no momento, traz Eletrocardiograma (ECG) de 12\nderivações, solicitado por médico em consulta anterior. Com base nesse caso clínico, e\nconsiderando-se a reprodução do ECG apresentado, mediante a utilização da diretriz de\ninterpretação de eletrocardiograma de repouso, da Sociedade Brasileira de Cardiologia, julgue o\nitem a seguir. Considere: FC = 51 spm; intervalo PR = 195ms; intervalo QRS = 130ms; intervalo QT\n\n= 440ms. As alterações de onda T em V5?V6 podem ser justificadas pela presença de bloqueio de\nramo esquerdo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-196629","number":"196629","sourceNumber":"196629","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certa paciente de 62 anos de idade, com histórico de hipertensão arterial sistêmica e\ndiabetes mellitus tipo 2, assintomática no momento, traz eletrocardiograma (ECG) de 12\nderivações, solicitado por médico em consulta anterior. Com base nesse caso clínico, e\nconsiderando-se a reprodução do ECG apresentado, mediante a utilização da Diretriz de\nInterpretação de Eletrocardiograma de Repouso, da Sociedade Brasileira de Cardiologia, julgue o\nitem a seguir. Considere: FC = 51 spm; intervalo PR = 195 ms; intervalo QRS = 130 ms; intervalo\nQT = 440 ms. Observa-se uma bradicardia sinusal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-196650","number":"196650","sourceNumber":"196650","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certo paciente de 33 anos de idade, que pratica corrida de rua há 15 anos,\n\napresenta-se para avaliação anual periódica em um posto de saúde. Leva eletrocardiograma com\npresença de bradicardia (45 bpm) e bloqueio atrioventricular de primeiro grau (intervalo PR de 240\nms). Não apresenta qualquer queixa espontânea. Tem histórico familiar de hipertensão arterial\nsistêmica, assim como de diabetes mellitus. Com base nesse caso clínico e considerando a\nliberação para a prática de exercício físico, utilizando como referência o International criteria\nfor\nelectrocardiographic interpretation in athletes (2017), julgue o item a seguir. A atividade física\ndeve\nser suspensa até maiores investigações das alterações eletrocardiográficas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-196656","number":"196656","sourceNumber":"196656","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certo paciente de 33 anos de idade, que pratica corrida de rua há 15 anos,\n\napresenta-se para avaliação anual periódica em um posto de saúde. Leva eletrocardiograma com\npresença de bradicardia (45 bpm) e bloqueio atrioventricular de primeiro grau (intervalo PR de 240\nms). Não apresenta qualquer queixa espontânea. Tem histórico familiar de hipertensão arterial\nsistêmica, assim como de diabetes mellitus. Com base nesse caso clínico e considerando a\nliberação para a prática de exercício físico, utilizando como referência o International criteria\nfor\nelectrocardiographic interpretation in athletes (2017), julgue o item a seguir. Para esse paciente,\ndeve-se solicitar ecocardiograma.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-196661","number":"196661","sourceNumber":"196661","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certo paciente de 33 anos de idade, que pratica corrida de rua há 15 anos,\n\napresenta-se para avaliação anual periódica em um posto de saúde. Leva eletrocardiograma com\npresença de bradicardia (45 bpm) e bloqueio atrioventricular de primeiro grau (intervalo PR de 240\nms). Não apresenta qualquer queixa espontânea. Tem histórico familiar de hipertensão arterial\nsistêmica, assim como de diabetes mellitus. Com base nesse caso clínico e considerando a\nliberação para a prática de exercício físico, utilizando como referência o International criteria\nfor\nelectrocardiographic interpretation in athletes (2017), julgue o item a seguir. Caso o paciente\napresente hipertensão arterial ao longo do seguimento, a prática do exercício físico aeróbico deve\nser estimulada, mas o exercício resistido (com pesos) deve ser contraindicado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-196672","number":"196672","sourceNumber":"196672","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Certo paciente de 33 anos de idade, que pratica corrida de rua há 15 anos,\n\napresenta-se para avaliação anual periódica em um posto de saúde. Leva eletrocardiograma com\npresença de bradicardia (45 bpm) e bloqueio atrioventricular de primeiro grau (intervalo PR de 240\nms). Não apresenta qualquer queixa espontânea. Tem histórico familiar de hipertensão arterial\nsistêmica, assim como de diabetes mellitus. Com base nesse caso clínico e considerando a\nliberação para a prática de exercício físico, utilizando como referência o International criteria\nfor\nelectrocardiographic interpretation in athletes (2017), julgue o item a seguir. A Diretriz\nBrasileira em\nCardiologia do Esporte e do Exercício indica a realização de eletrocardiograma de 12 derivações\nantes da liberação para a prática de atividade física em todos os indivíduos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-177607","number":"177607","sourceNumber":"177607","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"M.C.L., sexo feminino, de 76 anos de idade, é paciente com diagnóstico de insuficiência\ncardíaca com fração de ejeção reduzida\n(40%), atualmente com classe funcional NYHA II. Como\ncomorbidades, apresenta HAS, DM e fibrilação atrial fixa. Considerando o quadro dessa paciente e\nsua patologia, julgue o item a seguir. Há indicação de terapia anticoagulante para essa paciente?","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-135065","number":"135065","sourceNumber":"135065","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma paciente de quarenta anos de idade informou ao médico que, havia seis meses,\nvinha apresentando dor e edema nas articulações\ndas mãos e punhos. Passados dois meses do\ninício desses episódios, houve migração do processo para as articulações dos joelhos, o que tinha\nfeito a paciente sentir rigidez nas articulações todas as manhãs. O exame físico, por fim, mostrou\npresença de edema, calor, rubor e dor nas articulações citadas, de forma simétrica. Com relação a\nesse caso clínico, julgue o item subsequente. A ausência de manifestações extra-articulares na\npaciente é favorável a um bom prognóstico para a doença em questão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-135070","number":"135070","sourceNumber":"135070","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma paciente de quarenta anos de idade informou ao médico que, havia seis meses,\nvinha apresentando dor e edema nas articulações\ndas mãos e punhos. Passados dois meses do\ninício desses episódios, houve migração do processo para as articulações dos joelhos, o que tinha\nfeito a paciente sentir rigidez nas articulações todas as manhãs. O exame físico, por fim, mostrou\npresença de edema, calor, rubor e dor nas articulações citadas, de forma simétrica. Com relação a\nesse caso clínico, julgue o item subsequente. No caso em questão, exames radiológicos das\narticulações comprometidas são de pouca valia para o diagnóstico, sendo preferível a solicitação de\nRessonância Nuclear Magnética.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-134951","number":"134951","sourceNumber":"134951","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma paciente de quarenta anos de idade informou ao médico que, havia seis meses,\nvinha apresentando dor e edema nas articulações\ndas mãos e punhos. Passados dois meses do\ninício desses episódios, houve migração do processo para as articulações dos joelhos, o que tinha\nfeito a paciente sentir rigidez nas articulações todas as manhãs. O exame físico, por fim, mostrou\npresença de edema, calor, rubor e dor nas articulações citadas, de forma simétrica. Com relação a\nesse caso clínico, julgue o item subsequente. A rigidez matinal é, nessa situação, critério para o\ndiagnóstico de lúpus eritematoso sistêmico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-134962","number":"134962","sourceNumber":"134962","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma paciente de quarenta anos de idade informou ao médico que, havia seis meses,\nvinha apresentando dor e edema nas articulações\ndas mãos e punhos. Passados dois meses do\ninício desses episódios, houve migração do processo para as articulações dos joelhos, o que tinha\nfeito a paciente sentir rigidez nas articulações todas as manhãs. O exame físico, por fim, mostrou\npresença de edema, calor, rubor e dor nas articulações citadas, de forma simétrica. Com relação a\nesse caso clínico, julgue o item subsequente. A medida do fator reumatoide é um exame importante\npara a elucidação diagnóstica dessa paciente, embora esse fator possa estar presente em outras\ndoenças reumatológicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-134975","number":"134975","sourceNumber":"134975","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Acerca de febre reumática, julgue o item que se segue. A cardite reumática se\ncaracteriza clinicamente por dor torácica, hipofonese\nde bulhas e atrito pericárdico, apresentando\npoucas manifestações de pericardite.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-140708","number":"140708","sourceNumber":"140708","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Acerca da cardiopatia reumática crônica (CRC), julgue o item a seguir. Os nódulos de\nAschoff, patognomônicos da CRC, agem como células apresentadoras de antígeno para as células\nT, o que amplifica a resposta imune e promove a ativação de clones autorreativos de linfócitos T.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-108173","number":"108173","sourceNumber":"108173","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Julgue o item seguinte, relativo às doenças de acometimento comum na população. A\namigdalectomia está indicada como procedimento profilático da febre reumática.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-108181","number":"108181","sourceNumber":"108181","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente de trinta e cinco anos de idade compareceu a um ambulatório de clínica\nmédica apresentando quadro clínico constituído\npor episódios intermitentes de dor, rigidez, edema\ne calor nos joelhos e nos tornozelos. O paciente relatou, ainda, que esses sinais e sintomas\nocorriam pela manhã e duravam cerca de quatro horas. No exame físico, constatou-se que o\npaciente apresentava dor associada a sinais flogísticos na articulação do joelho direito. No\nprontuário do paciente, o resultado do hemograma indicava hemoglobina de 11 g/dl; hematócrito de\n34%; hemácias de 4.000.000/mm³; leucócitos com número absoluto e diferencial normal para o\nsexo e faixa etária do paciente; plaquetas de 250.000/mm³ e VHS de 90 mm/h. Com base nesse\ncaso clínico, julgue o item a seguir. Uma das orientações que devem ser dadas a esse paciente é\nde que ele mantenha absoluto repouso da articulação quando da exacerbação dos sinais\ninflamatórios articulares.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-108183","number":"108183","sourceNumber":"108183","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente de trinta e cinco anos de idade compareceu a um ambulatório de clínica\nmédica apresentando quadro clínico constituído\npor episódios intermitentes de dor, rigidez, edema\ne calor nos joelhos e nos tornozelos. O paciente relatou, ainda, que esses sinais e sintomas\nocorriam pela manhã e duravam cerca de quatro horas. No exame físico, constatou-se que o\npaciente apresentava dor associada a sinais flogísticos na articulação do joelho direito. No\nprontuário do paciente, o resultado do hemograma indicava hemoglobina de 11 g/dL, hematócrito\nde 34%, hemácias de 4.000.000 mm³, leucócitos com número absoluto e diferencial normal para o\nsexo e faixa etária do paciente, plaquetas de 250.000 mm³ e VHS de 90 mm/h. Com base nesse\ncaso clínico, julque o item que se segue. O comprometimento de grandes articulações apresentado\npelo paciente em questão é sugestivo de diagnóstico de gota.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-108192","number":"108192","sourceNumber":"108192","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente de trinta e cinco anos de idade compareceu a um ambulatório de clínica\nmédica apresentando quadro clínico constituído por episódios intermitentes de dor, rigidez, edema\ne calor nos joelhos e nos tornozelos. O paciente relatou, ainda, que esses sinais e sintomas\nocorriam pela manhã e duravam cerca de quatro horas. No exame físico, constatou-se que o\npaciente apresentava dor associada a sinais flogísticos na articulação do joelho direito. No\nprontuário do paciente, o resultado do hemograma indicava hemoglobina de 11 g/dL, hematócrito\nde 34%, hemácias de 4.000.000 mm³, leucócitos com número absoluto e diferencial normal para o\nsexo e faixa etária do paciente, plaquetas de 250.000 mm³ e VHS de 90 mm/h. Com base nesse\ncaso clínico, julque o item que se segue. A anemia normocística-normocrômica apresentada pelo\nreferido paciente é um achado frequente nessa forma de comprometimento articular.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-108175","number":"108175","sourceNumber":"108175","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"No item a seguir, é apresentado um caso clínico a respeito de doenças\ncardiovasculares na infância e na\nadolescência, seguido de uma assertiva a ser julgada. Escolar do\nsexo masculino com 30 kg apresentava quadro de febre e poliartralgia migratória havia uma\nsemana. Sua mãe relatou que três semanas antes do início do quadro ele havia tido amigdalite\nbacteriana, tratada com antibiótico. No exame clínico, além de artrite no joelho direito, foram\nidentificados sopro sistólico em foco mitral e sopro diastólico em foco aórtico, sem sinais de\ndescompensação cardíaca. O hemograma completo mostrou leucocitose com neutrofilia, sem\ndesvio para a esquerda e sem granulações tóxicas. A dosagem de ASLO foi de 1.000 UI e a da\nproteína C reativa, de 5 UI/L. A ecocardiografia do paciente revelou a presença de regurgitação\naórtica e mitral, com câmaras cardíacas de tamanhos normais. Nesse caso, a terapêutica\nmedicamentosa indicada para o paciente consiste na administração de penicilina benzatina por via\nintramuscular, na dose de 1.200.00 UI e prednisona por via oral na dose de 2mg/kg/dia por três\nsemanas, com redução progressiva semanal do corticoide de 20%.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-82077","number":"82077","sourceNumber":"82077","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma mulher de quarenta e cinco anos de idade foi atendida em ambulatório de clínica\nmédica com relato de que, havia oito anos, apresentava dor na região plantar dos calcanhares e\nque, após ter sido submetida à avaliação médica, recebeu o diagnóstico de reumatismo e que lhe\nhaviam sido prescritos medicamentos cujos nomes não se recorda. Nesse intervalo de tempo,\npassou a apresentar dor e alterações nos punhos, que a impossibilitam de fechar as mãos e\ntambém dor e vermelhidão nos joelhos e tornozelos. Ela relatou, ainda, rigidez matinal, com\nduração de três horas, por vários meses. Negou possuir outras doenças e informou que sua mãe\napresentava problema de reumatismo. Ao exame físico, observaram-se diminuição da flexão dos\npunhos (bilateralmente), dor nas articulações metacarpofalangianas (bilateralmente), presença de\ndiscreto derrame articular nos joelhos e dor à palpação das articulações metacarpofalangianas e\ndos calcanhares. Foram constatados três nódulos, com cerca de 2 cm de diâmetro cada um,\nindolores, firmes e móveis na região olecraniana direita. O restante do exame não apresentou\nalterações. Exames complementares realizados mostraram fator reumatoide (teste do látex)\npositivo, pesquisa de anticorpos contra peptídeos citrulinados cíclicos (CCP) positiva, níveis\nelevados de proteína C reativa e aceleração da velocidade de hemossedimentação. Radiografias\ndas mãos e dos pés mostraram estreitamento dos espaços articulares e lesões ósseas erosivas.\nCom base nessas informações clinicolaboratoriais, julgue o item que se segue. O principal\ndiagnóstico para a paciente é de lúpus eritematoso sistêmico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-79643","number":"79643","sourceNumber":"79643","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dos exames usados para avaliar processos inflamatórios, assinale a alternativa\nCORRETA:","options":{"A":"Ureia e creatinina.","B":"PCR e DHS.","C":"TGO e TGP.","D":"Troponina e PCR.","E":"Amilase e lipase."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-88648","number":"88648","sourceNumber":"88648","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"No que concerne à artrite reumatoide (AR), julgue o item subsequente. Para a remissão\nsustentada da AR, preconiza-se o uso dos inibidores seletivos de ciclo-oxigenase 2 devido à sua\nsuperioridade em relação aos anti-inflamatórios não hormonais não seletivos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-88655","number":"88655","sourceNumber":"88655","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"No que concerne à Artrite Reumatoide (AR), julgue o item subsequente. A AR pode\ngerar não só deformidade irreversível, mas\ntambém limitação funcional, além de menor sobrevida\nquando em estágio avançado.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-64244","number":"64244","sourceNumber":"64244","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Considere que, em consulta de rotina, uma criança de oito anos de idade relatou a\npresença de dor relevante no joelho\ndireito, havia um dia, que piorava com movimentação. No\nexame médico, verificou-se que a articulação apresentava discreto calor, rubor e edema de +/+4. A\nmãe informou que, havia três dias que a criança apresentara os mesmos sinais no tornozelo direito\ne, antes disso, a mesma situação instalara-se por dois dias no cotovelo esquerdo. Considerando\nesse caso clínico, julgue o item que segue. A manifestação clínica descrita corresponde a um\ncritério maior, de acordo com a classificação de Jones, para febre reumática.","options":{"A":"Certo","B":"Errado"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-64247","number":"64247","sourceNumber":"64247","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Considere que, em consulta de rotina, uma criança de oito anos de idade relatou a\npresença de dor relevante no joelho\ndireito, havia um dia, que piorava com movimentação. No\nexame médico, verificou-se que a articulação apresentava discreto calor, rubor e edema de +/+4. A\nmãe informou que, havia três dias que a criança apresentara os mesmos sinais no tornozelo direito\ne, antes disso, a mesma situação instalara-se por dois dias no cotovelo esquerdo. Considerando\nesse caso clínico, julgue o item que se segue. É necessária a evidência de faringite estreptocócica,\ncom incidência de oito a dez semanas anteriores ao caso clínico relatado, para que se considere o\ndiagnóstico de febre reumática.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-64254","number":"64254","sourceNumber":"64254","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Considere que, em consulta de rotina, uma criança de oito anos de idade relatou a\npresença de dor relevante no joelho\ndireito, havia um dia, que piorava com movimentação. No\nexame médico, verificou-se que a articulação apresentava discreto calor, rubor e edema de +/+4. A\nmãe informou que, havia três dias, a criança apresentara os mesmos sinais no tornozelo direito e,\nantes disso, a mesma situação instalara-se, por dois dias, no cotovelo esquerdo. Considerando\nesse caso clínico, julgue o item que se segue. É muito comum a coexistência temporal de artrite e\nde cardite nos casos de febre reumática.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-64259","number":"64259","sourceNumber":"64259","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Considere que, em consulta de rotina, uma criança de oito anos de idade relatou a\npresença de dor relevante no joelho\ndireito, havia um dia, que piorava com movimentação. No\nexame médico, verificou-se que a articulação apresentava discreto calor, rubor e edema de +/+4. A\nmãe informou que, havia três dias que a criança apresentara os mesmos sinais no tornozelo direito\ne, antes disso, a mesma situação instalara-se por dois dias no cotovelo esquerdo. Considerando\nesse caso clínico, julgue o item que se segue. A profilaxia primária da febre reumática consiste no\ntratamento adequado das faringoamigdalites bacterianas.","options":{"A":"Certo.","B":"Errado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-32163","number":"32163","sourceNumber":"32163","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um menino de seis anos de idade foi levado ao posto de saúde por apresentar febre,\nadinamia, dor abdominal, joelho direito e tornozelo esquerdo inchados. A mãe relatou ainda o\naparecimento de manchas pelo corpo que pioravam com o calor. Ao exame físico, apresentou\nqueda do estado geral, febre (38,5°C), edema e leve rubor no tornozelo esquerdo e no joelho\ndireito. FC = 111 bpm; SatO2 = 95%; FR = 25 irpm. À ausculta cardíaca, revelou sopro\nholossistólico apical com irradiação para axila. Foram, ainda, observadas máculas com bordos\neritematosos e centros evanescentes no tronco e na raiz das coxas. A respeito desse caso clínico,\nassinale a alternativa CORRETA:","options":{"A":"A principal faixa etária de acometimento da doença é de três a sete anos.","B":"Os critérios de Jones podem auxiliar no diagnóstico da fase aguda da doença, o qual somente\nserá confirmado com os exames laboratoriais\nespecíficos da doença.","C":"Os nódulos subcutâneos são raros na doença; mas, quando presentes, estão associados à\ncardite grave.","D":"A terapia antimicrobiana no início do tratamento deve ser prescrita somente na presença de\nquadro de faringite.","E":"A profilaxia secundária antimicrobiana em pacientes com lesão valvar residual grave deve ser\nfeita até a idade de 25 anos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-29722","number":"29722","sourceNumber":"29722","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A febre reumática é doença inflamatória multissistêmica que ocorre em indivíduos\ngeneticamente suscetíveis, após infecção\nfaríngea provocada pelo estreptococo beta-hemolítico do\ngrupo A. O diagnóstico baseia-se na utilização de sinais clínicos e laboratoriais que integram os\nchamados critérios de Jones modificados, incluindo cinco sinais maiores e cinco menores. Com\nbase nessas informações, julgue o item subsequente. Os cinco sinais maiores são a cardite, a\nartrite migratória, a coreia, o eritema marginado e os linfonodos subcutâneos cervicais.","options":{"A":"Certo","B":"Errado"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-8581","number":"8581","sourceNumber":"8581","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Nas diretrizes para o tratamento de Osteoartrite o emprego de órteses de\nposicionamento e equipamentos de auxílio de\nmarcha é utilizado, naquelas situações, em que há\nnecessidade de melhorar, auxiliar ou substituir uma função. Essa é uma recomendação com nível D\nde evidência, significando que se baseia em:","options":{"A":"estudo experimental de menor consistência.","B":"estudo experimental de maior consistência.","C":"série de relato de casos.","D":"opinião de especialistas.","E":"estudo caso-controle."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-343407","number":"343407","sourceNumber":"343407","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O nome da arritmia que é um ritmo que o impulso elétrico se origina logo acima do\nventrículo, com reentrada por uma via de\ncondução acessória, e o ECG não mostra a onda P, mas\nela pode estar presente e com morfologia anormal, nem sempre sendo possível determinar o\nintervalo PR e o intervalo RR é constante e o QRS estreito, com frequência cardíaca superior a 220\nbpm em lactentes e a 180 bpm em crianças maiores é:","options":{"A":"Bloqueio Atrioventricular.","B":"Bradicardia sinusal.","C":"Flutter Ventricular.","D":"Taquicardia Supraventricular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-273313","number":"273313","sourceNumber":"273313","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Criança de 2 anos de idade, inicia quadro súbito de taquipnéia, palidez e sudorese.\nApresenta-se afebril, com FR = 40 mrpm, FC =\n230 bpm, pulsos periféricos finos e rápidos,\nperfusão periférica preservada. A criança está consciente, contactando normalmente com os pais.\nFeito ECG: O diagnóstico e conduta mais adequados são:","options":{"A":"Taquicardia sinusal; expansão com solução cristalóide.","B":"Taquicardia ventricular; cardioversão sincronizada.","C":"Taquicardia supraventricular; adenosina IV.","D":"Taquicardia juncional; amiodarona IV."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-230558","number":"230558","sourceNumber":"230558","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A varfarina é altamente eficaz na prevenção de fenômenos tromboembólicos na FA,\ncom redução de 64% do risco nos pacientes\nadequadamente tratados. NÃO podemos aceitar que:","options":{"A":"Menos metade dos pacientes não são adequadamente tratados, por motivos que variam desde a\ndificuldade de controle frequente de RNI até alto risco de sangramento.","B":"Pacientes em uso de varfarina nem sempre se encontram na faixa terapêutica adequada (em\ngeral RNI entre 5 e 6).","C":"Ocorre interação medicamentosa, principalmente antibióticos e anti-inflamatórios.","D":"Ocorre interação com alimentos, uso irregular da medicação, intercorrências clínicas agudas,\nentre outros."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-230579","number":"230579","sourceNumber":"230579","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quais os parâmetros do ECG devem se conhecidos ao se avaliar uma criança com\nalteração do ritmo?","options":{"A":"Conhecimento da FC normal de acordo coma idade, o débito cardíaco e o ritmo de base.","B":"Conhecimento da FC normal de acordo com a idade, o débito cardíaco e a duração do complexo\nQRS.","C":"Conhecimento do débito cardíaco, ritmo de base e duração do complexo QRS.","D":"Conhecimento da FC normal de acordo com a idade, o ritmo de base e a duração do complexo\nQRS."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-203130","number":"203130","sourceNumber":"203130","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma paciente de 45 anos de idade sente tontura, pressão no peito e fadiga há três\nhoras. Durante o exame, verifica-se que ela\napresenta níveis pressóricos de 80 mmHg x 50 mmHg\ne FC = 140 bpm, associada a má perfusão periférica. Ao ECG, nota-se que ela tem fibrilação atrial,\nsendo que um ECG basal prévio mostrou ondas delta. A respeito desse caso clínico, assinale\nalternativa correta.","options":{"A":"Essa paciente não possui risco de taquicardia ventricular, pois a respectiva fibrilação atrial\npossui complexo QRS estreito, assim o risco maior seria evolução para taquicardia\nsupraventricular.","B":"A onda delta indica a presença de extrassístoles ventriculares (provável disfunção do nó\nsinusal); assim, o diagnóstico para esse caso é\nfibrilação atrial com complexo de QRS alargado.","C":"A terapia de escolha para essa paciente seria administração de betabloqueadores, com objetivo\nde redução da frequência cardíaca.","D":"A terapia com verapamil é uma opção aceitável para ser realizada nessa paciente em caráter de\nemergência, em razão da rápida absorção e objetivando a redução da frequência cardíaca e do\ninotropismo cardíaco.","E":"O diagnóstico clínico dessa paciente é fibrilação atrial em uma paciente portadora de síndrome\nde Wolff-Parkinson-White, indicado pelas ondas delta no\nECG anterior, que mostram uma via\nacessória ao nó atrioventricular para a comunicação elétrica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-206170","number":"206170","sourceNumber":"206170","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Responda qual a alternativa CORRETA sobre o ritmo apresentado:","options":{"A":"Trata-se de taquicardia supraventricular.","B":"Deve-se iniciar massagem cardíaca e oferecer adenosina rapidamente.","C":"Trata-se do tipo mais comum de PCR em crianças, é a assistolia.","D":"Devemos realizar desfibrilação."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-212110","number":"212110","sourceNumber":"212110","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Caso clínico - paciente sem doenças prévias; Idade: 19 anos: sexo: feminino; Sinais e\nsintomas: tremores nas extremidades, nervosismo e palpitações taquicárdicas (FC = 15 bpm, PA\n135 mmHg x 65 mmHg, pulsos radiais palpáveis e arrítmicos); Avaliação cardiovascular evidenciou\nictus cordis in situ, ritmo cardíaco irregular em 2 tempos, taquicárdico, bulhas normofonéticas, sem\nsopros ou ruídos adventícios. Na palpação, percebeu-se glândula tireoide indolor, levemente\naumentada e não nodular. Resultado de dosagem séricas: TSH (tirotrofina) = 0,05 mU/L (valores de\nreferência = 0,4 - 4,2 mU/L); T4 livre (tiroxina livre) = 4,0 nanogramas/dL (valores de referência =\n0,8 - 2,7 nanograma/dL); anticorpos antirreceptor de TSH (ou Trab) = 2 U/L (valor de referência <\n10 U/L); anticorpos antitireoglobulinas = positivo 1/6.400 (valores de referência não reagente <\n1/100); determinação de anticorpos antiperoxidase tireoidiana (anti-TPO) = 70 U/mL (valores de\nreferência < 35 U/mL). Ecodopplercardiograma = normal. Tira de ritmo eletrocardiográfico (ECG)\nmostrada na figura a seguir (derivação D2, velocidade do papel: 25 mm/s, calibração: 1 cm = 1\nmV). A respeito das informações do caso clínico descrito anteriormente, julgue o item subsequente.\nA arritmia cardíaca mostrada na tira de ECG é a fibrilação atrial.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-175085","number":"175085","sourceNumber":"175085","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dentro do estudo da genética, relacionada com o eletrocardiograma ocorre descrição\nde entidades clínicas potencialmente fatais, que\napresentam padrão eletrocardiográfico\ncaracterístico. Dentro desse grupo de doenças, destacam-se aquelas com coração estruturalmente\nnormal, como as canalopatias. Não sendo ADEQUADA a seguinte alternativa a seu respeito:","options":{"A":"As canalopatias cardíacas são o resultado de mutações genéticas ou de um mau funcionamento\nadquirido dos canais iônicos.","B":"Os canais iônicos são responsáveis por desencadear alterações na despolarização.","C":"Os canais iônicos são responsáveis por desencadear alterações na repolarização das fases do\npotencial de ação celular.","D":"Achados eletrocardiográficos específicos, com associação de síncopes espontâneas, mas não\nas desencadeadas pelo exercício."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-175106","number":"175106","sourceNumber":"175106","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A Síndrome do QT longo pode causar inúmeros sintomas. Sobre ela, podemos afirmar\nque:","options":{"A":"A claritromicina pode aumentar o intervalo QT.","B":"Calcula-se o QT corrigido apenas se a frequência cardíaca for maior que 80 bpm.","C":"Calcula-se o QT corrigido apenas se a frequência cardíaca for menor que 90 bpm.","D":"Apenas calcula-se QT corrigido para crianças maiores de 10 anos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-175110","number":"175110","sourceNumber":"175110","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre a morfologia da Onda P, é correto afirmar:","options":{"A":"A onda P sinusal é positiva em AVR, D1 e D2.","B":"No ritmo atrial ectópico a onda P é negativa em D2, sendo comum em adolescentes.","C":"Quando há situs atrial inversus, a onda P é negativa em D1 e em AVR.","D":"A amplitude normal da onda P é de 4mm."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-175111","number":"175111","sourceNumber":"175111","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Nas arritmias é CORRETO afirmar que:","options":{"A":"Quando há QT longo, há proteção contra a morte súbita.","B":"No torsades de pointes devemos oferecer cálcio ao paciente para tratá-lo e seu ECG apresenta\nQT curto.","C":"No torsades de pointes há espaço QT curto e tratamos com magnésio.","D":"No Wolff-Parkinson-White há espaço PR curto."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183963","number":"183963","sourceNumber":"183963","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Considerando o ritmo eletrocardiográfico apresentado na figura precedente - derivação:\nD2; velocidade do papel 25 mm/seg; calibração: 1cm\n= 1 mV - , julgue o seguinte item. A arritmia\napresentada decorre diretamente de um distúrbio na propriedade cronotrópica do nó sinusal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183965","number":"183965","sourceNumber":"183965","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Considerando o ritmo eletrocardiográfico apresentado na figura precedente - derivação:\nD2; velocidade do papel 25 mm/seg; calibração: 1cm\n= 1 mV - , julgue o seguinte item. A arritmia\nobservada nessa tira de ritmo é a extrassístole supraventricular com pausa compensatória.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-175163","number":"175163","sourceNumber":"175163","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A classificação mais utilizada na prática clínica refere-se à forma de apresentação da\nFA. Definem-se assim diversas classificações, sendo que somente uma das abaixo se mostra\ncompletamente correta, assinale-a:","options":{"A":"?Fibrilação atrial paroxística? aquela que é revertida espontaneamente ou com intervenção\nmédica em até 24 horas de seu início.","B":"Episódios com duração superior a 7 dias têm o nome de ?Fibrilação atrial persistente?.","C":"Alguns estudos utilizam a terminologia de ?Fibrilação atrial persistente de longa duração? para\ndesignar os casos com duração superior a mês.","D":"Finalmente, o termo ?Fibrilação atrial permanente? é utilizado nos casos em que as tentativas\nde reversão ao ritmo sinusal não foram feitas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-175174","number":"175174","sourceNumber":"175174","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dentro do estudo das complicações relacionadas à trombogênese e embolia na\nFibrilação Atrial, podemos considerar que as três condições estabelecidas por Virshow estão\npresentes em paciente com FA. Não sendo, contudo, completamente adequada a afirmativa:","options":{"A":"Lesões do endocárdio atrial apresentavam microtrombos, e estes eram os precursores de\ntrombos maiores.","B":"O atrito do sangue com o endocárdio, lesões miocitárias causadas por agressões teciduais\nsecundárias a citocinas inflamatórias (fator de\nnecrose tumoral, interleucina 6, proteína C-reativa e\noutras) prejudicam ainda mais os miócitos atriais e expõem tecido colágeno na superfície, o que\naumenta a aderência de plaquetas e a deposição de fibrina, gerando o trombo.","C":"Dessa forma, a FA cria um estado pró-trombótico e hipercoagulável próprio.","D":"O aumento da agregação plaquetária, menos intensa no Átrio Esquerdo (AE), e a redução dos\nníveis plasmáticos do fator de Von Wilebrand, os fragmentos de protrombina e do fibrinogênio\nplasmático, dentre outros, confirmam essa maior trombogenicidade sanguínea, independentemente\nde qualquer outro fator."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-168486","number":"168486","sourceNumber":"168486","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma lactante com 15 meses de idade é levada pela mãe ao Pronto-Socorro. A mãe\nrelata que o coração do bebê está muito\nacelerado. A mãe nega outras queixas e informa que\nrealiza acompanhamento na Unidade Básica de Saúde, não tendo ocorrido até então,\nintercorrências. Ao exame físico, a lactante apresenta-se em bom estado geral, corada, hidratada,\nafebril, consciente, com boa perfusão periférica, saturação de oxigênio de 98% em ar ambiente,\nBNF 2T sem sopro audivél, frequência cardíaca = 230 bpm, ausência de edema e pulsos de boa\namplitude. O eletrocardiograma apresenta onda P não visível; intervalo RR fixo QRS estreito\n(menor que 0,09 segundos). Diante desse quadro, além da manobra vagal, a conduta inicial\nadequada é","options":{"A":"administrar lidocaina","B":"administrar adenosina","C":"administrar amiodaroma","D":"realizar cardioversão elétrica sincronizada"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-159580","number":"159580","sourceNumber":"159580","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O item a seguir apresenta uma situação hipotética seguida de uma assertiva a ser\njulgada a propósito da fisiopatologia, do diagnóstico precoce e do tratamento de doenças em\ncrianças e adolescentes. Uma gestante com trinta e quatro semanas gestacionais foi a uma\nconsulta de rotina, e o médico obstetra observou que a frequência cardíaca fetal era de 70 bpm.\nNeste caso, um diagnóstico que pode ser excluído na gestante é lúpus eritematoso sistêmico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-168519","number":"168519","sourceNumber":"168519","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem com 60 anos de idade foi internado em um hospital municipal com quadro\nde confusão mental. O paciente reside em outro\nmunicípio, há 300 km do hospital. Na admissão, o\npaciente se disse assintomático, relatou que não costuma procurar atendimento médico e que\npreferia morar sozinho no sítio onde nasceu e cuida de uma pequena lavoura. Os familiares que o\nacompanhavam confirmaram que ele não apresenta comorbidades diagnosticadas, mas relataram\nque, há 5 dias, o paciente apresentou um episódio de confusão mental, tendo sido levado para\ninternação hospitalar. Acrescentaram que, na ocasião, foi diagnosticada e tratada uma infecção do\ntrato urinário e que, durante o exame físico, detectou-se uma arritmia cardíaca, confirmada por\neletrocardiograma, cujo resultado é reproduzido a seguir. (Conforme imagem no caderno de\nquestões) O resultado do eletrocardiograma realizado na internação atual apresenta o mesmo\npadrão. Agora, consciente e orientado, sem queixas, o paciente manifesta desejo de ter alta e de\nretornar ao seu sítio, afirmando que não pretende realizar outras consultas médicas. Nesse\ncontexto, qual é a conduta médica indicada?","options":{"A":"Dar alta hospitalar ao paciente após introdução de digoxina.","B":"Dar alta hospitalar ao paciente após a introdução e o ajuste da dose da varfarina.","C":"Dar alta hospitalar ao paciente após introdução e ajuste de dose do betabloqueador.","D":"Orientar os familiares para que busquem, por meios jurídicos, a guarda do idoso e o mantenham\nna sede do município para iniciar tratamento\ncom varfarina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-111355","number":"111355","sourceNumber":"111355","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre a farmacologia dos Glicocorticoides (GC), assinale a afirmativa CORRETA:","options":{"A":"A dexametasona e a triancinolona apresentam boa atividade mineralocorticoide.","B":"A betametasona e a hidrocortisona são\nconsiderados GC de ação de curta duração.","C":"Os GC fluorados não atravessam a barreira\nplacentária.","D":"Pacientes tratados com GC, mesmo em doses fisiológicas e em regime de dias alternados,\ndevem ser considerados com supressão do eixo\nHHA.","E":"Aplicação tópica de GC pode induzir a supressão do eixo Hipotálamo-Hipófise-Adrenal (HAA)."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-104750","number":"104750","sourceNumber":"104750","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale a alternativa que apresenta a manifestação clínica mais comum da febre\nreumática.","options":{"A":"Dor articular devido à poliartrite migratória de grandes articulações.","B":"Precordialgia devido à pericardite.","C":"Sopro cardíaco devido à endocardite com insuficiência da valva mitral.","D":"Movimentos involuntários devido à Coreia de Sydenham.","E":"Nódulos subcutâneos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-111299","number":"111299","sourceNumber":"111299","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação à Febre Reumática, assinale a alternativa CORRETA:","options":{"A":"A valva cardíaca mais acometida em casos de cardite é a valva aórtica.","B":"São critérios menores de Jones: ASLO elevado e artrite.","C":"Artralgia, presente na articulação com evidências de artrite, deve ser considerada como critério\nmenor de Jones.","D":"O tempo de profilaxia secundária é sempre igual, independente da manifestação da doença e de\noutras particularidades.","E":"A profilaxia primária é fundamental tanto para evitar o primeiro surto da doença nos\nindivíduos suscetíveis como para erradicar o estreptococo beta-hemolítico do grupo A de\nLancefield, naqueles em que o diagnóstico está sendo firmado."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-97794","number":"97794","sourceNumber":"97794","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem com 53 anos de idade, tabagista e com história prévia de cardiopatia, tem\nparada cardiorrespiratória na unidade básica de saúde, enquanto aguardava atendimento. A\nsequência CORRETA de medidas a serem adotadas nessa situação é:","options":{"A":"Verificar o nível de consciência; acionar o serviço de emergência; verificar o pulso; iniciar\ncompressões torácicas.","B":"Iniciar compressões torácicas; verificar o pulso; acionar o serviço de emergência; verificar o\nnível\nde consciência.","C":"Acionar o serviço de emergência; verificar o pulso; verificar o nível de consciência; iniciar\ncompressões torácicas.","D":"Acionar o serviço de emergência; avaliar o nível de consciência; iniciar compressões torácicas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-75557","number":"75557","sourceNumber":"75557","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher com 60 anos de idade, hipertensa, vai à consulta em Unidade Básica de Saúde\nporque apresentou quadro de parestesias e\nhemiparesia no membro superior esquerdo há uma\nsemana, com reversão espontânea completa em 12 horas. Pressão arterial = 180 x 110 mmHg,\nausculta cardíaca com ritmo irregular, em 2 tempos, exame neurológico sem alterações\nsignificativas. Traz tomografia computadorizada de crânio sem contraste, realizada no dia dos\nsintomas, que é normal. Realizou eletrocardiograma conforme mostrado abaixo - DII (traz exame\nsemelhante feito há 60 dias). (VER IMAGEM). Qual outro fármaco, além do tratamento\n\nanti-hipertensivo, é o mais indicado para essa paciente como medida de maior impacto na\nprevenção de novos episódios do quadro neurológico?","options":{"A":"Warfarina.","B":"Clopidogrel.","C":"Ticlopidina.","D":"Atorvastatina.","E":"Ácido acetilsalicílico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-137579","number":"137579","sourceNumber":"137579","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem de 55 anos de idade, portador de infecção pelo HIV, diabético do tipo II,\nhipertenso, em terapia antiretroviral, estável há 6 anos, com contagem de linfócitos CD4 de 980\ncélulas/mm (valor de referência < 1 000 células/mm ) e carga viral indetectável (< 25 cópias/mL),\napresentou quadro de perda súbita e transitória da consciência, com queda da própria altura e\nrecuperação espontânea. Na semana seguinte ao episódio, procurou o médico clínico que o\nacompanha; a\n\nhipertensão arterial e o diabetes mellitus mantinham-se controlados. O paciente relatou que, desde\no episódio mencionado, sente ?palpitações? e\n?pulso acelerado?. O médico observou no exame\ncardiovascular: frequência cardíaca = 105 bpm; pressão arterial = 140 x 90 mmHg, ritmo\n\ncardíaco irregular, achados que não haviam sido até então documentados em 10 anos de\nseguimento ambulatorial do paciente. O eletrocardiograma realizado naquela ocasião mostra\nausência de ondas P e intervalos RR muito irregulares. A conduta imediata mais adequada é","options":{"A":"monitorizar o paciente por 48 horas, para observar a\npossibilidade de reversão espontânea da arritmia.","B":"encaminhar o paciente para a emergência cardiológica, para ser submetido à cardioversão\nelétrica.","C":"solicitar ecocardiograma transesofágico, para avaliar a presença de trombos em átrio esquerdo.","D":"iniciar heparinização plena e warfarina, para minimizar o\nrisco existente de doença tromboembólica.","E":"administrar antiarrítmicos intravenosos, para induzir reversão farmacológica da arritmia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-138414","number":"138414","sourceNumber":"138414","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Adolescente, após tentativa de suicídio com ingestão de antidepressivo tricíclico,\nmanifestou parada cardiorrespiratória. Durante a\nreanimação cardiopulmonar, observou-se o\nseguinte ritmo no monitor cardíaco (VER IMAGEM). A análise do monitor cardíaco permite afirmar\nque o traçado eletrocardiográfico demonstra ritmo de","options":{"A":"taquicardia ventricular, que pode ser responsiva a\nchoque e a uso de atropina.","B":"fibrilação ventricular, que pode ser responsiva a\ncardioversão (choque no modo sincronizado).","C":"fibrilação ventricular, que pode ser responsiva a\ndesfibrilação (choque no modo sincronizado).","D":"taquicardia ventricular, que pode ser responsiva a\ncardioversão (choque no modo sincronizado).","E":"taquicardia ventricular, que pode ser responsiva a\ndesfibrilação (choque no modo não sincronizado)."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-138584","number":"138584","sourceNumber":"138584","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, com 57 anos de idade, sexo masculino, chega ao pronto atendimento\nqueixando-se de palpitações que se iniciaram\nhá três dias, associadas à tontura e à dispneia.\nRelata fazer uso de metimazol 10 mg/dia há um mês por diagnóstico de hipertireoidismo. Faz uso\nainda de enalapril 20 mg para hipertensão arterial desde os 45 anos de idade. Ao exame: Pressão\narterial = 110 x 70 mmHg; Frequência cardíaca = 160 BPM; Frequência respiratória = 26 irmp; rítmo\ncardíaco taquicárdico, irregular, em dois tempos, sem sopros; murmúrio vesicular fisiológico com\ncrepitações bibasais; abdome livre, indolor, ruídos hidroaéreos positivos; aparelho locomotor sem\nalterações. Saturação periférica de oxigênio de 87%. Solicitado ECG: (VER IMAGEM). Instalada a\nsuplementação de oxigênio e monitorização cardíaca. Assinale a alternativa que identifica a arritmia\ne a conduta a ser tomada ainda na sala de pronto atendimento.","options":{"A":"Flutter atrial e amiodarona.","B":"Taquicardia supra ventricular paroxistica e procainamida.","C":"Sindrome de Wolff-Parkinson-White e beta bloqueador.","D":"Taquicardia atrial multifocal e bloqueadores de canais de cálcio.","E":"Fibrilação atrial e digitálico."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-30947","number":"30947","sourceNumber":"30947","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com relação a cardiopatias na infância, julgue o item a seguir: A manifestação mais\nfrequente de comprometimento cardíaco em criança com febre reumática é a endocardite, e as\nvalvas mais acometidas, em ordem de frequência, são: mitral, aórtica e tricúspide.","options":{"A":"Certo.","B":"Errado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-22213","number":"22213","sourceNumber":"22213","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com relação aos critérios de algumas patologias, julgue o item. Os sinais e sintomas\nclínicos da febre reumática surgem em média\napós uma a três semanas da infecção estreptocócica\nda orofaringe. Fazem parte dos critérios menores de Jones (modificados em 1992) febre, artralgia,\nprovas reumáticas de fase aguda elevadas (VHS e PCR) e prolongamento do espaço P.R.","options":{"A":"certo","B":"errado"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-8658","number":"8658","sourceNumber":"8658","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com respeito à artrite gotosa, julgue o item. A identificação, em material proveniente de\naspirado articular ou de um tofo de cristais de urato de sódio, com localização extracelular ou no\ninterior de neutrófilos, semelhantes a agulhas, negativamente birrefringentes ao microscópio de luz\npolarizada, permite confirmar o diagnóstico em pacientes com suspeita de gota.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-8659","number":"8659","sourceNumber":"8659","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com respeito à artrite gotosa, julgue o item. Em pacientes com diagnóstico de artrite\ngotosa, que estão no período intercrítico,\no principal efeito adverso decorrente do uso de alopurinol\n(um inibidor de xantina oxidase) é a precipitação de um ataque agudo de gota.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-19235","number":"19235","sourceNumber":"19235","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação ao diagnóstico de AIDS, julgue o item abaixo. O período de janela\nimunológica é de 10 dias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-19236","number":"19236","sourceNumber":"19236","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação ao diagnóstico de AIDS, julgue o item abaixo. No período de janela\nimunológica, não há riscos de transmissão da doença, por qualquer via, pois esse período\ncorresponde ao intervalo entre a infecção por HIV e a produção de anticorpos anti-HIV.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-352188","number":"352188","sourceNumber":"352188","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre a fibrilação atrial, selecione a alternativa incorreta:","options":{"A":"Fibrilação atrial paroxística é aquela que é revertida espontaneamente ou com intervenção\nmédica em até 7 dias de seu início.","B":"Fibrilação atrial persistente é aquela com episódios com duração superior a 7 dias.","C":"O termo fibrilação atrial permanente é utilizado nos casos em que as tentativas de reversão ao\nritmo sinusal não serão mais instituídas.","D":"Considera-se fibrilação atrial aguda quando iniciada há menos de 7 dias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-345697","number":"345697","sourceNumber":"345697","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O eletrocardiograma nas mulheres difere:","options":{"A":"Em relação à magnitude dos sinais elétricos, com maior amplitude do QRS, do ponto J e da\nonda T e maior intervalo QT corrigido.","B":"Em relação à magnitude dos sinais elétricos, com menor amplitude do QRS, do ponto J e da\nonda T e menor intervalo QT corrigido.","C":"Em relação à magnitude dos sinais elétricos, com menor amplitude do QRS, do ponto J e não da\nonda T e maior intervalo QT corrigido.","D":"Em relação à magnitude dos sinais elétricos, com menor amplitude do QRS, do ponto J e da\nonda T e maior intervalo QT corrigido."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-346839","number":"346839","sourceNumber":"346839","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 68 anos se queixa de tontura ao se levantar. É portador de DM-2 e HAS, e\nfaz uso de metformina, clortalidona e enalapril. Ao exame físico, PA/FC: (deitado)\n190x96mmHg/62bpm; PA/FC: (em pé) 90x46mmHg/61bpm; PA/FC: (após 3 minutos de\nortostatismo) 82x40mmHg/64bpm. Hemoglobina glicada 8,9%. Assinale a alternativa que apresenta\numa conduta INCORRETA para esse paciente:","options":{"A":"Prescrever dapagliflozina.","B":"Orientar o aumento da ingestão de água e sal.","C":"Orientar dormir com a cabeceira elevada (30 a 45 graus).","D":"Substituir clortalidona e enalapril por captopril uma vez ao dia antes de dormir."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-345701","number":"345701","sourceNumber":"345701","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"MJD, feminina de 40 anos, procurou seu atendimento por ter realizado ECG com\nachados no exame periódico. A inversão da\nonda T anterior, isso é, além de V1, ocorre em cerca\nde 2,3% da população e é mais comum em mulheres, independentemente do status de atividade\nfísica. Sendo correto que:","options":{"A":"É um padrão maligno desde que ocorra em assintomáticas e de baixo risco, pois estudos\nsugerem que possa refletir um deslocamento lateral do ventrículo direito.","B":"É um padrão benigno desde que não ocorra em assintomáticas e de baixo risco, pois estudos\nsugerem que possa refletir um deslocamento lateral do ventrículo direito.","C":"É um padrão benigno desde que ocorra em assintomáticas e de baixo risco, pois estudos\nsugerem que possa refletir um deslocamento lateral do ventrículo direito.","D":"É um padrão benigno desde que ocorra em assintomáticas e de alto risco, pois estudos sugerem\nque possa refletir um deslocamento lateral\ndo ventrículo direito."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-345705","number":"345705","sourceNumber":"345705","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"VLD, feminina de 34 anos, apresentou dor torácica relacionada a cirurgia plástica,\nporém informou que seu ECG estava com achados, por\nisso solicitou sua avaliação. Sua posição\nfoi de que alterações eletrocardiográficas são observadas em 45% das portadoras de implantes\nmamários sendo correto que:","options":{"A":"Inversão de ondas T, depressão do segmento ST inferolateral, alta progressão de R de V1-V4,\nintervalo QT prolongado e hipertrofia ventricular esquerda, podendo assim levar a interpretações\nenganosas.","B":"Inversão de ondas T, depressão do segmento ST inferolateral, baixa progressão de R de V1-V4,\nintervalo QT prolongado e hipotrofia ventricular esquerda, podendo assim levar a interpretações\nenganosas.","C":"Inversão de ondas T, depressão do segmento ST inferolateral, baixa progressão de R de V1-V4,\nintervalo QT prolongado e hipertrofia ventricular esquerda, podendo assim levar a interpretações\nenganosas.","D":"Inversão de ondas T, depressão do segmento ST inferolateral, baixa progressão de R de V1-V4,\nintervalo QT prolongado e hipertrofia ventricular esquerda, nunca podendo assim levar a\ninterpretações enganosas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-337624","number":"337624","sourceNumber":"337624","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente 70 anos, sexo feminino, procura atendimento com quadro de piora do estado\ngeral há alguns meses, informa que tem\nobservado perda de peso, mesmo com aumento do\napetite. Relata que tem apresentado tremor de extremidades ocasionalmente. E o que tem mais lhe\nincomodado são as palpitações que tem se tornado mais frequentes, principalmente nas últimas 2\nsemanas atrapalhando suas atividades da vida diária. Informa ser apenas hipertensa em uso de\nhidroclorotiazida. Nega outras comorbidades. Você observa os exames solicitados em última\nconsulta em UBS que ainda não haviam sido avaliados e opta por realizar um ECG de 12\nderivações. Ao exame: PA: 145x90mmHg, Sat.99%, FR: 18irmp, FC:144bpm, Hb: 10,1g/dL, Ht:\n29%, GL: 4500, Plaq: 129.000mm³, TSH: 0,001 e T4L: 5,4. Considerando o caso descrito, assinale\na alternativa que apresenta a conduta MAIS adequada.","options":{"A":"Realizar cardioversão sincronizada seguido de anticoagulação, encaminhar para realização de\ntireoidectomia.","B":"Iniciar amiodarona ou propafenona para controle de ritmo seguido de anticoagulação com\nenoxaparina, solicitar TRAB e iniciar metimazol.","C":"Iniciar metoprolol para controle de frequência e rivaroxabana como anticoagulante, encaminhar\npara ultrassom de tireoide.","D":"Iniciar atenolol para controle de frequência, warfarina como anticoagulante e iniciar metimazol."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-345706","number":"345706","sourceNumber":"345706","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"As mulheres têm mais taquicardia:","options":{"A":"Sinusal e taquicardia por reentrada nodal, sendo que a gravidez reduz o risco de taquicardias\nsupraventriculares","B":"Sinusal e taquicardia por reentrada nodal, sendo que a gravidez aumenta o risco de taquicardias\nsupraventriculares.","C":"Sinusal e não de taquicardia por reentrada nodal, sendo que a gravidez aumenta o risco de\ntaquicardias supraventriculares.","D":"Sinusal e taquicardia por reentrada nodal, sendo que a gravidez não aumenta o risco de\ntaquicardias supraventriculares."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-346856","number":"346856","sourceNumber":"346856","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Isadora, 10 anos, sem história prévia de doenças, apresentou subitamente episódio de\ntaquicardia, dificuldade de respirar, acompanhada de palidez e sensação de desmaio. Relata a\n\n?sensação do coração estar saindo pela boca?. Nega desmaios ou síncopes. Ao chegar no\npronto-atendimento, a pediatra notou olhar ansioso, FC: 220bpm, PA: 120x70mmHg, enchimento\ncapilar adequado. Aparelho Respiratório - FR: 48irpm, sem ruídos adventícios. Abdômen: fígado e\n\nbaço não palpados. Foi inicialmente tratado com manobras vagais, sem resposta. Um ECG é obtido\ne mostrou taquicardia, QRS estreito e ausência\nde onda P. Considerando o caso apresentado, o\ndiagnóstico MAIS provável é de:","options":{"A":"Taquicardia sinusal.","B":"Bloqueio Mobitz tipo I.","C":"Taquicardia ventricular monomórfica.","D":"Taquicardia supraventricular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-335100","number":"335100","sourceNumber":"335100","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 58 anos de idade, hipertenso e diabético, sem histórico de eventos\nisquêmicos, tem FA persistente\nrecém-diagnosticada. Faz uso de enalapril, anlodipina, metformina\ne AAS. Nega uso de álcool ou drogas. Hemograma, função hepática e coagulograma normais. Não\nfaz uso de AINE e não tem histórico de úlcera nem de quedas. Seu ecocardiograma mostra\nmiocardiopatia dilatada com leve regurgitação mitral funcional. É proposta adequada para o\npaciente:","options":{"A":"Iniciar anticoagulação com varfarina, mantendo o AAS.","B":"Iniciar anticoagulação com varfarina, suspendendo o AAS.","C":"Manter apenas oAAS, sem iniciar anticoagulante.","D":"Manter o AAS e associar clopidogrel."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-336303","number":"336303","sourceNumber":"336303","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem, 74 anos, hipertenso e diabético internado na UTI em pós operatório de\ndebridamento cirúrgico de ?pé-diabético? infectado em membro inferior direito. Inicia quadro de\nsudorese, precordialgia e taquicardia seguida de perda do nível de consciência. Monitor\neletrocardiográfico apresenta o traçado abaixo. Qual a conduta imediata?","options":{"A":"Cardioversão elétrica","B":"Amiodarona","C":"Desfibrilação","D":"Adenosina"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-304993","number":"304993","sourceNumber":"304993","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale a alternativa que apresenta a causa que pode determinar a ocorrência de\nflutter atrial:","options":{"A":"Cardiopatia hipertensiva.","B":"Infarto agudo do miocárdio.","C":"Miocardiopatia dilatada.","D":"Cardiopatia chagásica aguda."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-304854","number":"304854","sourceNumber":"304854","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante o atendimento à parada cardiorrespiratória, o acesso venoso profundo está\ncontraindicado. A explicação que fundamenta tal recomendação é:","options":{"A":"Piora do prognóstico neurológico por interrupção das compressões torácicas.","B":"Maior risco de ocorrência de pneumotórax.","C":"Dificuldade técnica no acesso venoso central.","D":"Maior incidência de punção de vasos arteriais."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-283892","number":"283892","sourceNumber":"283892","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"No tratamento das taquiarritmias supraventriculares regulares, com estabilidade\nhemodinâmica, qual das alternativas abaixo NÃO é capaz de reverter a taquiarritmia?","options":{"A":"Manobra de Valsalva.","B":"Massagem do seio carotídeo.","C":"Contato facial com água gelada.","D":"Uso de adenosina intravenosa.","E":"Respirar dentro de um saco plástico."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-227077","number":"227077","sourceNumber":"227077","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 77 anos se queixa de palpitação em repouso. Sem outras queixas. Nega\ndoenças conhecidas ou uso de medicamentos. Ao\nexame físico, PA: 140 X 90mmHg, FC 116bpm,\nFR 15ipm, SpO? 98%. O ritmo cardíaco é irregular, a primeira bulha é hiperfonética e há sopro\nmesodiastólico em ruflar no apex do coração. Sem outras alterações ao exame físico.\n\nEcocardiograma: ventrículo esquerdo de dimensões levemente aumentadas, sem déficits\nsegmentares da contratilidade e fração de ejeção\nde 40%. Átrio esquerdo de volume muito\naumentado. Estenose mitral moderada e insuficiência mitral moderada de morfologia reumática.\nNão se visualizam trombos. Eletrocardiograma; Considerando o caso descrito, assinale a\nalternativa que apresenta a prescrição CORRETA para esse paciente.","options":{"A":"Bisoprolol e varfarina.","B":"Digoxina e enoxaparina.","C":"Diltiazem e rivaroxabana.","D":"Metoprolol e apixabana."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-234408","number":"234408","sourceNumber":"234408","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma mulher de 78 anos vai ao consultório de Clínica Médica para uma consulta de\nacompanhamento clínico. Está assintomática. É portadora de insuficiência cardíaca e faz uso de\nfurosemida, enalapril, metoprolol, espironolactona e digoxina. Ao exame físico, apresenta-se alerta\ne orientada. Os dados vitais são PA: 120 X 70mmHg, FC: 30bpm, FR: 17ipm, SpO? em ar ambiente\n97%. O exame cardiovascular revela bradicardia e variação da fonese da primeira bulha. Sem\noutras anormalidades ao exame físico. Solicitou-se um eletrocardiograma apresentado a seguir:\nConsiderando o caso descrito, assinale a conduta imediata MAIS ADEQUADA para essa paciente.","options":{"A":"Administrar atropina, dopamina ou dobutamina em infusão contínua pela via intravenosa.","B":"Posicionar um marcapasso transvenoso até a colocação do marca-passo definitivo.","C":"Suspender o metoprolol e realizar o estudo eletrofisiológico após 48h.","D":"Suspender o metoprolol e a digoxina e manter a monitoração clínica e eletrocardiográfica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-232140","number":"232140","sourceNumber":"232140","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 23 anos, com palpitações, apresenta o eletrocardiograma a seguir. Qual o\ndiagnóstico?","options":{"A":"Fibrilação atrial.","B":"Taquicardia sinusal.","C":"Taquicardia atrial unifocal.","D":"Taquicardia atrial multifocal.","E":"Taquicardia atrial incessante."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-232141","number":"232141","sourceNumber":"232141","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 84 anos, evoluindo com quadros de síndromes convulsivas tônico-clônicas\nde repetição, que se iniciam ao repouso, não\nacompanhadas de liberação esfincteriana. Procurou\nconsultório do cardiologista, onde chegou deambulando normalmente e, no meio da consulta,\napresentou uma síncope, seguida de crise convulsiva. Nesse momento, foi realizado\neletrocardiograma abaixo, que confirmou o diagnóstico:","options":{"A":"Bloqueio átrio-ventricular avançado alternante.","B":"Bloqueio átrio-ventricular do segundo grau.","C":"Bloqueio átrio-ventricular do tipo 2:1.","D":"Bloqueio átrio-ventricular do primeiro grau.","E":"Bloqueio átrio-ventricular total."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-227322","number":"227322","sourceNumber":"227322","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente feminina, 6 anos, será submetida à cirurgia eletiva e ao ser examinada\nnotou-se ritmo cardíaco irregular, sem outros\nsinais ou sintomas. Feito ECG que demonstrou:\nBaseado na história e ECG, o diagnóstico provável é:","options":{"A":"Arritmia sinusal.","B":"Bloqueio AV de segundo grau.","C":"Bloqueio AV de primeiro grau.","D":"Escape juncional por provável distúrbio eletrolítico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-199493","number":"199493","sourceNumber":"199493","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma mulher de 76 anos apresentou perda súbita da consciência e caiu da cadeira onde\nestava sentada conversando com o filho. Recobrou totalmente o sensório após 2 minutos. Negou\nquaisquer sintomas ou sinais antes e após esse episódio. É portadora de diabetes Mellitus, doença\nrenal crônica e angina do peito. Sofreu de infarto agudo do miocárdio há 10 anos. O exame clínico\nrevelou PA 90 x 50mmHg, FC 104bpm, FR 25ipm, SpO2 91%. Os exames respiratório,\ncardiovascular, abdominal e neurológico resultaram normais. Sobre o caso descrito, assinale a\nalternativa CORRETA:","options":{"A":"A ausência de pródromo afasta a possibilidade de causa cardíaca.","B":"A síncope dessa paciente é postural e pode ser devida à disautonomia da neuropatia periférica\ndo diabetes.","C":"A principal hipótese diagnóstica é hipoglicemia.","D":"O tromboembolismo pulmonar deve ser considerado no diagnóstico diferencial."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-220298","number":"220298","sourceNumber":"220298","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher de 45 anos apresentou perda da consciência após se levantar e sair do ônibus\nem frente a um Pronto-Socorro. Recuperou\ncompletamente a consciência em 2 minutos e estava\nassintomática. Relatou uma sensação de escurecimento visual e tontura logo antes da queda. Era\ndiabética e hipertensa há 20 anos, com tratamento irregular. Possuía doença renal crônica (estádio\n3) e gastroparesia diabética. Fazia uso de hidroclorotiazida, atenolol e metformina. Ao exame\nfísico,\nestava alerta, orientada, corada, hidratada. PA (deitada): 130 x 80mmHg, FC: 103bpm, FR: 17ipm,\nSpO2 98%, Glicemia Capilar: 168mg/dL. Os exames respiratório, cardiovascular e abdominal\nresultaram normais. O exame neurológico revelou hipoestesia em botas nos pés. Observe o\neletrocardiograma a seguir: Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"Trata-se de um caso de crise convulsiva atônica e a paciente deve ser tratada com fenitoína IV.","B":"Trata-se de um caso de síncope cardiogênica por arritmia e a paciente deve ser submetida à\navaliação cardiológica.","C":"Trata-se de um caso de síncope vasovagal e a paciente deve realizar um tilt test.","D":"Trata-se de um caso de síncope postural e deve ser considerado o uso de meias elásticas\ncompressivas e fludrocortisona."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-199633","number":"199633","sourceNumber":"199633","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Pré-escolar, masculino, 5 anos de idade, está internado para a correção cirúrgica de\nhérnia inguinal. Ao ser examinado, notou-se que a frequência cardíaca era irregular, sem outras\nanormalidades no exame físico. O Eletrocardiograma (ECG) demonstra o seguinte traçado. Após\nanálise do eletrocardiograma, o diagnóstico é:","options":{"A":"Arritmia sinusal.","B":"Bloqueio AV de 1º grau.","C":"Bloqueio AV de 2º grau.","D":"Bloqueio de ramo direito."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-196806","number":"196806","sourceNumber":"196806","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um dos muitos acrósticos usados em medicina é o CHADS 2, (evoluiu para CHA2\nDS2-VASC), usado para avaliar risco de\nacidente vascular cerebral em pessoas com fibrilação\natrial, medida importante para médicos que atuam em Atenção Primária à Saúde (APS). Entre as\nopções abaixo qual a condição clínica é pontuada nesta avaliação de risco? Marque a CORRETA:","options":{"A":"Crise hipertensiva.","B":"Hipertensão intracraniana.","C":"Alteração de ritmo cardíaco.","D":"Diabetes mellitus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-172784","number":"172784","sourceNumber":"172784","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 56 anos chega ao pronto-socorro com quadro súbito de palpitações e\ndispneia. Ao exame físico apresenta\nfrequência cardíaca de 145 bpm, pressão arterial de 112 x 75\nmmHg, e o seguinte traçado eletrocardiográfico. São fatores de risco para o quadro clínico citado:","options":{"A":"Consumo de bebida alcoólica, Doença Pulmonar Obstrutiva Crônica (DPOC).","B":"Apneia obstrutiva do sono, obesidade.","C":"Hipertensão arterial, tabagismo.","D":"Insuficiência cardíaca, hipotireoidismo."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-172544","number":"172544","sourceNumber":"172544","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Na reanimação cardiopulmonar:","options":{"A":"A vasopressina mostrou-se claramente superior à adrenalina, mas seu custo bastante superior\ninviabiliza seu emprego na maior parte dos hospitais públicos e ou filantrópicos do Brasil","B":"A amiodarona pode ser usada em determinado momento do protocolo de atendimento da\nfibrilação ventricular (FV), apesar de não haver\nnenhum estudo que mostre sua real capacidade de\nprevenção de morte súbita, por exemplo, em pacientes portadores de miocardiopatia isquêmica\ngrave.","C":"A amiodarona foi abolida na revisão mais recente do protocolo de FV feita pela American Heart\nAssociation, visto a falta de evidências claras que dêem suporte ao seu uso.","D":"A atropina deve ser usada imediatamente após a assistolia ter sido detectada na\nmonitorização cardíaca, uma vez que a demora tornará inútil o emprego nesses casos.","E":"A intubação orotraqueal não poderá ser realizada em hipótese alguma antes do segundo ciclo\nde reanimação, independentemente do diagnóstico inicial e causa da parada cardiorrespiratória."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-155343","number":"155343","sourceNumber":"155343","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A fibrilação atrial ocorre com certa frequência em pacientes com insuficiência cardíaca,\npodendo ser uma das causas de\ndescompensação clínica do paciente. Quando necessário, a\nreversão dessa arritmia deve ser feita com um antiarrítmico com pouco ou nenhum efeito inotrópico\nnegativo. Qual opção abaixo indica o fármaco preferido para restaurar e manter o ritmo sinusal\nnesses casos?","options":{"A":"Digoxina.","B":"Quinidina.","C":"Disopiramida.","D":"Amiodarona.","E":"Flecainida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-155370","number":"155370","sourceNumber":"155370","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em paciente com fibrilação atrial aguda e sem cardiopatia estrutural, caso o médico\nopte por reversão da arritmia com droga, qual das abaixo seria a de primeira escolha?","options":{"A":"Amiodarona.","B":"Propafenona.","C":"Adenosina.","D":"Quinidina.","E":"Sotalol."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-155419","number":"155419","sourceNumber":"155419","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"No idoso, a diminuição das respostas cronotrópicas e inotrópicas aos beta-agonistas\ndeve-se à(ao):","options":{"A":"Redução da responsividade dos receptores beta-adrenérgicos.","B":"Aumento do número de receptores adrenérgicos.","C":"Aumento da responsividade dos receptores beta-adrenérgicos.","D":"Redução do número de receptores alfa-adrenérgicos.","E":"Aumento da responsividade dos receptores alfa e beta-adrenérgicos > plasmática."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-131628","number":"131628","sourceNumber":"131628","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Na artrite reativa podem ocorrer manifestações extra-articulares. Todas as abaixo\npodem estar presentes, exceto:","options":{"A":"Erupções cutâneas palmo-plantares.","B":"Conjuntivite.","C":"Ulcerações orais.","D":"Nódulos subcutâneos.","E":"Disúria."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-131643","number":"131643","sourceNumber":"131643","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A manifestação ocular mais frequente em pacientes portadores de artrite reumatoide é:","options":{"A":"Paresia da musculatura ocular extrínseca.","B":"Descolamento de retina.","C":"Opacificação do cristalino.","D":"Ceratoconjuntivite sicca.","E":"Uveíte."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-106426","number":"106426","sourceNumber":"106426","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Na Artrite Reumatoide (AR) estabelecida, qual das articulações abaixo é a mais\ncomprometida?","options":{"A":"Interfalangiana distal.","B":"Quadril.","C":"Joelho.","D":"Coluna.","E":"Punho."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-100981","number":"100981","sourceNumber":"100981","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente do sexo masculino, 52 anos, previamente diabético e dislipidêmico, com\nhistória de dor, vermelhidão e calor de\njoelho direito há dois dias. Nega febre e nega episódios\nsemelhantes anteriores. Ao exame físico apresenta frequência cardíaca de 104 bpm, pressão\narterial de 120 x 80 mmHg, presença de edema, calor e hiperemia de joelho direito com sinal da\ntecla positivo. A adequada conduta em pronto-socorro foi coleta do líquido sinovial que se mostrou\nturvo e com viscosidade diminuída. Assinale a alternativa CORRETA:","options":{"A":"O diagnóstico é artrite séptica e deve-se iniciar antibioticoterapia depois do resultado da\ncultura.","B":"A contagem de células e a avaliação da citologia não diferenciam artrite gotosa de artrite\nséptica.","C":"O principal agente infeccioso em diabéticos nas artrites sépticas é anaeróbio.","D":"Ausência de febre descarta artrite infecciosa.","E":"Deve-se iniciar antibioticoterapia com penicilina cristalina imediatamente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-106441","number":"106441","sourceNumber":"106441","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Os critérios de Jones são utilizados para o diagnóstico da febre reumática. Essa\ndoença é diagnosticada numa criança quando ela\napresenta, além de evidencia de infecção\nrecente pelo Streptococcus beta hemolítico do grupo A:","options":{"A":"artralgia e intervalo P-R aumentado.","B":"cardite e febre.","C":"nódulos subcutâneos e proteína-C-reativa aumentada .","D":"eritema marginado e poliartrite migratória.","E":"coréia de Sydenham e aumento da velocidade de hemossedimentação"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-88921","number":"88921","sourceNumber":"88921","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Caracteriza a presença de artrite:","options":{"A":"Dor à palpação articular.","B":"Derrame articular.","C":"Dor à movimentação ativa de uma articulação.","D":"Hiperemia da pele sobrejacente a uma articulação.","E":"Dor à movimentação passiva de uma articulação."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-88886","number":"88886","sourceNumber":"88886","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 30 anos, admitido com mal-estar, dispneia e síncope. ECG mostra\nsupradesnivelamento de segmento ST em V1 e V2, e padrão de BRD em V1. Cateterismo\nrealizado, imediatamente, foi normal. Qual a hipótese diagnóstica mais provável?","options":{"A":"Síndrome de Dressler.","B":"Síndrome do QT longo.","C":"Síndrome de Brugada.","D":"Displasia arritmogênica do VD.","E":"Síndrome do QT curto."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-88883","number":"88883","sourceNumber":"88883","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A alteração radiográfica que, num caso suspeito de espondilite anquilosante,\nfortaleceria essa hipótese diagnóstica é:","options":{"A":"sacroilite","B":"osteomalácia","C":"espondilólise","D":"peritendinite","E":"osteoporose"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-88882","number":"88882","sourceNumber":"88882","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente com episódios recorrentes de ulcerações orais e genitais associados à\nuveíte, artrite e lesões múltiplas de pele é, provavelmente, portador de:","options":{"A":"Lúpus eritematoso sistêmico.","B":"Gaucher.","C":"Meleney.","D":"Takayasu.","E":"Behçet."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-59047","number":"59047","sourceNumber":"59047","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Qual classe de medicamentos a seguir é de primeira linha no tratamento da\nfibromialgia?","options":{"A":"Anti-inflamatórios não esteroidais.","B":"Opioides.","C":"Antidepressivos dual.","D":"Relaxantes musculares.","E":"Benzodiazepínicos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-59473","number":"59473","sourceNumber":"59473","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação à Febre Reumática (FR), marque a alternativa CORRETA:","options":{"A":"Seu aparecimento é coincidente e simultâneo a uma infecção por estreptococos do Grupo A.","B":"A infecção sintomática da garganta por estreptococos do grupo A precedendo a febre reumática\né necessária para caracterização diagnóstica do\nsurto reumático.","C":"A artrite da FR acomete pequenas e grandes articulações de maneira simétrica.","D":"O eritema marginado e os nódulos subcutâneos são critérios maiores para o diagnóstico e\nocorrem em mais 80% dos casos de FR.","E":"O uso de corticoides no tratamento da Insuficiência Cardíaca relacionada a um surto de febre\nreumática aguda, apesar de usado por muitos, permanece controverso à luz da medicina baseada\nem evidências."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-59431","number":"59431","sourceNumber":"59431","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"M.M.T., 7 anos, foi admitido na emergência com história de febre (39°C), inapetência,\ndor em joelho direito. Ao exame: regular estado\ngeral, edema com rubor, calor e dor à flexão\npassiva e ativa do joelho direito. Podemos afirmar, exceto:","options":{"A":"Deve ser considerada uma urgência médica por ocasionar, de forma rápida, destruição óssea e\narticular.","B":"Nas fases iniciais o RX simples mostra destruição epifisária, periostite metafisária ou\nosteólise.\n\nPorém, o tratamento adequado precocemente evita sequelas irreversíveis e graves prejuízos\nfuncionais.","C":"Traumatismo recente pode ser um fator predisponente à infecção, pois facilita o estabelecimento\ndas bactérias na articulação devido a um maior\naporte sanguíneo, à facilidade de multiplicação e\nfixação bacteriana.","D":"Nessa faixa etária predomina, como agente etiológico, o S. aureus e o padrão monoarticular é o\nmais frequente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-43941","number":"43941","sourceNumber":"43941","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente feminina, 43 anos, diagnóstico recente de hipotireoidismo ainda\ndescompensado, apresenta dor tipo neuropática em\nhálux e indicador e diminuição da força de\npinça. Ao exame físico, apresenta Manobra de Phalen positivo. Qual o diagnóstico?","options":{"A":"Contratura de Dupuytren.","B":"Síndrome do túnel do carpo.","C":"Tenossinovite De Quervain.","D":"Síndrome do impacto.","E":"Síndrome da compressão no nervo radial."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-43953","number":"43953","sourceNumber":"43953","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente masculino, 25 anos, com queixa de dor lombar que é pior ao acordar e\nmelhora ao longo do dia, acompanhada de\nrigidez matinal por mais do que 30 minutos e edema de\njoelho direito há 06 meses. Refere que 30 dias antes do início do quadro articular apresentou\ndiarreia aguda. Quanto ao caso acima, assinale a alternativa correta.","options":{"A":"Este paciente não apresenta nenhum sinal de alerta que justifique investigação radiológica da\ndor.","B":"O diagnóstico sindrômico do paciente é lombalgia mecânica crônica.","C":"É provável que o paciente não tenha sacroileíte, pois não apresenta dor alternante em nádega.","D":"Diante dos sintomas pode-se classificar esse quadro como uma espondiloartrite.","E":"Prováveis causadores desta diarreia são Salmonella typhimurium, Yersinia enterocolitica,\nShigella flexneri, Campylobacter jejuni, Chlamydia\ntracomatis."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-43312","number":"43312","sourceNumber":"43312","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Escolar há 2 meses queixa-se de cansaço após a escola, dor e edema nos joelhos e\ntornozelos no fim da tarde. Há 1 mês observou piora, com limitação e dor ao movimento,\nacompanhados de edema e calor permanente, porém sem hiperemia. Exames laboratoriais:\nAnemia, leucocitose, trombocitose, VHS e PCR elevados. Alterações radiológicas: edema de partes\nmoles, osteoporose e periostite. De acordo com o caso exposto, podemos afirmar:","options":{"A":"Trata-se da forma pauciarticular da doença, onde há predomínio de articulações das\nextremidades inferiores. O comprometimento do\nquadril não é comum, porém, quando faz parte do\nquadro, surge em uma fase mais tardia e geralmente é o primeiro sinal de um curso funcional\ndesfavorável.","B":"Trata-se da forma poliarticular da doença, onde há comprometimento de mais de duas\narticulações. A presença de nódulos reumatoides\nnas superfícies extensoras estão associadas a\num curso mais grave.","C":"Trata-se da forma sistêmica da doença, onde há comprometimento de grandes articulações,\ntanto extremidades superiores quanto inferiores.","D":"O período de dois meses de evolução não é possível classificar o tipo de início da doença,\nsendo necessário pelo menos seis meses de evolução\npara fazê-lo."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-44017","number":"44017","sourceNumber":"44017","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Criança do sexo feminino, quatro anos de idade, é atendida devido à febre alta diária,\nhá mais de 03 semanas, geralmente um pico à\nnoite. Refere dores nas pernas durante a febre, bem\ncomo um exantema discreto em tronco e membros superiores, mas fica bem nos períodos afebris.\nRefere ainda dor, edema e calor em joelho direito, que iniciou há uma semana. Ao exame está\nbem, afebril no momento, mas com aumento de volume no joelho direito, calor e dor à palpação.\n\nPresença de adenomegalia cervical, auxiliar e inguinal bilateral e hepatoesplenomegalia discreta.\nSem outras alterações ao exame físico. Qual\ndos diagnósticos abaixo é o mais provável?","options":{"A":"Febre reumática.","B":"Artrite idiopática juvenil sistêmica.","C":"Lúpus eritematoso sistêmico.","D":"Tuberculose óssea.","E":"Artrite reacional a quadro infeccioso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-32457","number":"32457","sourceNumber":"32457","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Marque a alternativa correta sobre a Artrite Reumatoide: I - A doença não diminui a\nsobrevida, mas afeta significativamente a qualidade de vida da maioria dos pacientes. II - O\nacometimento das mãos é caracteristicamente simétrico e predomina em metacarpofalangeanas e\ninterfalangeanas proximais. III - O tratamento da doença deve ser instituído o mais rapidamente\npossível com drogas modificadoras da doença como anti-inflamatórios. IV - Os nódulos\nreumatoides podem ocorrer nos pulmões, coração e olhos.","options":{"A":"Uma afirmativa é correta.","B":"Duas afirmativas são corretas.","C":"Três afirmativas são corretas.","D":"Quatro afirmativas são corretas.","E":"Nenhuma das alternativas é correta."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-27384","number":"27384","sourceNumber":"27384","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem branco de 60 anos relata história de artrite de joelho direito há 05 dias. Há\nquatro meses teve artrite em tornozelo D e 1º metatarso, sendo medicado em pronto-socorro com\nanti-inflamatório não hormonal, obtendo alívio completo dos sintomas. Diabético e hipertenso em\nuso de tiazídico. Sem queixas intestinais ou urinárias. Antecedente de urolitíase em uma ocasião.\nAo exame físico, apresentava temperatura axilar de 37,8ºC, artrite de joelho, rubor local em 1º\nmetatarso, ausência de edema nos tornozelos. Sobre o caso acima, assinale apenas a afirmativa\nCORRETA:","options":{"A":"Artrite reumatoide é a principal hipótese diagnóstica em um caso de monoartrite aguda\nrecorrente com acometimento de 1º metatarso em\npacientes acima de 40 anos, como no caso\ndescrito.","B":"No caso descrito, é fundamental a realização de RX de mãos e pés, dosagem do fator\nreumatoide, dosagem de anti-CCP e ácido úrico para\ndefinir a artrite reumatoide desse paciente.","C":"O quadro sugere uma artrite microcristalina ou por depósito de cristais, que classicamente\nocorre em episódios agudos e em indivíduos com\ncomorbidades metabólicas, podendo haver\nurolitíase prévia.","D":"O uso de tiazídicos pode ter precipitado a artrite deste paciente e o nível de ácido úrico\nsérico é\nfrequentemente elevado no momento da crise aguda de artrite.","E":"Leucocitose pode ser encontrada nos exames complementares deste paciente, e juntamente\ncom a febre e o rubor articular podem mimetizar\numa artrite séptica, sendo mandatória uma\nressonância magnética de joelho para excluir esse diagnóstico diferencial."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-9405","number":"9405","sourceNumber":"9405","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com relação ao fator AR (Artrite Reumatoide), assinale a INCORRETA:","options":{"A":"O fator reumatoide é encontrado em 70 a 80% dos casos de AR.","B":"Os métodos mais utilizados para identificação de fator reumatoide são o látex e o Waaler-Rose.","C":"O fator reumatoide tem sido identificado no soro, líquido sinovial, líquido pleural e nos\ntecidos.","D":"No tipo infanto-juvenil, ou nas formas clínicas benignas, estes testes geralmente são negativos.","E":"O fator reumatoide é diagnóstico de artrite reumatoide e sua ausência determina a exclusão\ndiagnóstica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-9449","number":"9449","sourceNumber":"9449","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A válvula MAIS acometida na febre reumática é:","options":{"A":"Aórtica.","B":"Subaórtica.","C":"Mitral.","D":"Tricúspide.","E":"Pulmonar."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-8133","number":"8133","sourceNumber":"8133","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente do sexo feminino, 92 anos, sem antecedentes de doença cardiovascular\napresenta dor crônica de joelho direito. Ao\nexame físico, observa-se aumento de calor e volume de\njoelho direito, atrofia significativa da coxa direita, limitação para extensão completa da\narticulação e\npresença de crepitação. Raio X de joelho D mostra diminuição do espaço articular, osteófitos e\nesclerose subcondral. Qual o diagnóstico mais provável?","options":{"A":"Osteoartrite.","B":"Síndrome paraneoplásica.","C":"Tuberculose articular.","D":"Artrite reumatoide.","E":"Condrocalcinose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-363960","number":"363960","sourceNumber":"363960","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Para qual destas situações há indicação CLASSE I de implante de marcapasso\ndefinitivo?","options":{"A":"Doença do nó sinusal em pacientes em uso de amiodarona.","B":"Bloqueio atrioventricular de segundo grau Mobitz I (Wenckebach) durante o sono.","C":"Sincope recorrente, > 40 anos de idade e documentação de pausa sintomática espontânea\nmaior que 6 segundos","D":"Pacientes com miocardiopatia hipertrófica forma obstrutiva, mesmo com gradiente de via de\nsaída de ventrículo esquerdo baixo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-331961","number":"331961","sourceNumber":"331961","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher, 73 anos, tem diagnóstico de fibrilação atrial paroxística. Antecedentes\npessoais: hipertensão controlada com medicação.\nNega diabetes, outras doenças ou internações\nprévias. Radiograma de tórax: área cardíaca normal, sem calcificações vasculares. Em relação à\nabordagem terapêutica da fibrilação atrial nesta paciente, é correto:","options":{"A":"O escore de CHADS-VASC é de 3, sem indicação de terapia antitrombótica, pela ausência de\nevidência de eventos prévios.","B":"O escore de CHADS-VASC é de 2, sendo que um ponto é pelo gênero, sem indicação de terapia\nantitrombótica.","C":"O escore de CHADS-VASC é de 3, com indicação de terapia antitrombótica.","D":"O escore de CHADS-VASC não se aplica nessa situação, por se tratar de arritmia paroxística"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-330063","number":"330063","sourceNumber":"330063","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O eletrocardiograma, também chamado de ECG, é o registro gráfico dos fenômenos\nelétricos do músculo cardíaco ou do coração. Com base no tema, é CORRETO afirmar:","options":{"A":"O complexo QRS representa a despolarização e a condução do impulso nos ventrículos.","B":"O ECG é registrado em papel gráfico, na velocidade (linha vertical) de 20 mm/s, ou 1mm a cada\n0,04 segundos.","C":"As derivações periféricas são obtidas no plano horizontal, pela colocação de eletrodos no tórax\ndo paciente.","D":"O posicionamento do eletrodo para derivação precordial V4 deve ser de 4° espaço intercostal à\ndireita, próximo ao esterno."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-342615","number":"342615","sourceNumber":"342615","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"As arritmias cardíacas são decorrentes, basicamente, de alterações na geração do\nimpulso (automatismo anormal e atividade deflagrada) e/ou na condução do impulso (reentrada).\nSobre os principais mecanismos de taquiarritmia mais prevalentes na população pediátrica, sua\nclassificação e tratamento, não podemos afirmar que:","options":{"A":"as células miocárdicas atriais e ventriculares normalmente não apresentam atividade de\nmarca-passo","B":"a reentrada é o mecanismo gerador de taquiarritmias supraventriculares e ventriculares mais\nfrequente e relevante, podendo ser anatômica ou funcional","C":"as arritmias cardíacas podem ser classificadas, quanto à repercussão clínica, em estável ou\ninstável","D":"cicatrizes (fibroses) miocárdicas secundárias à cardiopatia estrutural não favorecem o\ndesenvolvimento de reentrada"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-330088","number":"330088","sourceNumber":"330088","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com relação às arritmias cardíacas em Pediatria, é CORRETO afirmar:","options":{"A":"A taquicardia ventricular tem início geralmente abrupto, exceto em lactentes, que apresentam\nirritabilidade, inapetência e dispneia enquanto evoluem para insuficiência cardíaca congestiva.","B":"O paciente com bloqueio atrioventricular deve ser submetido diretamente à cardioversão elétrica\nsincronizada ou à cardioversão química com adenosina, o que for mais rápido na situação.","C":"A taquicardia sinusal é definida como frequência cardíaca maior do que 220 bpm no lactente e\nmaior do que 180 bpm nas crianças maiores, com complexo QRS estreito e ausência de onda P.","D":"Os sinais clínicos associados à bradiarritmia podem ser choque com hipotensão, perfusão\nineficiente de órgão- alvo, alteração do nível de consciência ou colapso súbito."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300803","number":"300803","sourceNumber":"300803","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O eletrocardiograma realiza a reprodução gráfica da atividade elétrica do coração\ndurante o seu funcionamento, registrada a\npartir da superfície do corpo. Quanto às principais\nalterações eletrocardiográficas, onda P com orientação normal e frequência cardíaca < 50 bpm\ndenotam:","options":{"A":"Parada sinusal.","B":"Bloqueio sinoatrial (BSA).","C":"Bradicardia sinusal.","D":"Bloqueio de ramo esquerdo (BRE)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300914","number":"300914","sourceNumber":"300914","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O uso de betabloqueadores via oral ou intravenosa após a PCR por FV/TVSP mostrou\nreduzir mortalidade 72 horas após e em 6 meses. Está CORRETO o item:","options":{"A":"Não podem levar à piora hemodinâmica, exacerbar sinais de Insuficiência Cardíaca (IC) e causar\narritmias.","B":"No entanto, podem levar à piora hemodinâmica, e nunca exacerbar sinais de Insuficiência\nCardíaca (IC) e causar arritmias.","C":"No entanto, podem levar à piora hemodinâmica, exacerbar sinais de Insuficiência Cardíaca (IC)\ne causar arritmias.","D":"No entanto, podem levar à piora hemodinâmica, exacerbar sinais de Insuficiência Cardíaca (IC)\ne não causar arritmias."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-313197","number":"313197","sourceNumber":"313197","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com relação à Fibrilação Atrial (FA), assinale a alternativa correta:","options":{"A":"a FA paroxística diminui sua incidência com o aumento da idade","B":"a FA apresenta baixa morbimortalidade em mulheres hipertensas acima de 80 anos","C":"a FA persistente é a forma mais comum de apresentação","D":"a FA paroxística que apresenta reversão espontânea apresenta baixa taxa de recorrência, e o\npaciente pode ser mantido sem anticoagulação, independentemente de outros fatores de risco"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-317939","number":"317939","sourceNumber":"317939","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A melhor conduta diante de uma idosa com doença de Chagas que apresenta\ntaquicardia ventricular sustentada, FC 155bpm e PA 85x55mmHg é:","options":{"A":"amiodarona endovenosa.","B":"lidocaína endovenosa.","C":"cardioversão elétrica.","D":"implante imediato de cardiodesfibrilador."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-295354","number":"295354","sourceNumber":"295354","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dentre as arritmias conhecidas, qual é a mais comum durante atendimentos de\nemergência?","options":{"A":"Extrassistolia ventricular.","B":"Taquicardia sinusal.","C":"Fibrilação atrial.","D":"Taquicardia ventricular."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300916","number":"300916","sourceNumber":"300916","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em adultos com FV/TVSP, observou-se que a administração de amiodarona 300 mg ou\n5 mg/kg melhorou a sobrevida à admissão\nhospitalar, quando comparada com placebo ou\nadministração de lidocaína. No entanto, não houve melhora do prognóstico neurológico. Podemos\nindicar como CORRETO que:","options":{"A":"A amiodarona não pode ser considerada para FV/TVSP que não responde à RCP, desfibrilação\ne terapêutica vasopressora.","B":"A amiodarona pode ser considerada para FV/TVSP que responde à RCP, desfibrilação e\nterapêutica vasopressora.","C":"A amiodarona pode ser considerada para FV/TVSP que não responde à RCP, desfibrilação e\nnão a terapêutica vasopressora.","D":"A amiodarona pode ser considerada para FV/TVSP que não responde à RCP, desfibrilação e\nterapêutica vasopressora."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-317940","number":"317940","sourceNumber":"317940","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A melhor conduta diante de um idoso com fibrilação atrial sem data certa de início, FC =\n110 BPM e PA 130x85 mmHg é:","options":{"A":"cardioversão química.","B":"cardioversão elétrica.","C":"controle de frequência cardíaca e anticoagulação.","D":"estudo eletrofisiológico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300917","number":"300917","sourceNumber":"300917","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Para pacientes com disfunção ventricular sistólica, a amiodarona e a digoxina são as\ndrogas mais utilizadas como Drogas Antiarrítmicas (DAA). Sendo ADEQUADO nesse contexto o\nitem:","options":{"A":"Bloqueadores de canal de cálcio e betabloqueadores intravenosos não devem ser evitados\nquando houver esta suspeita clínica (área cardíaca aumentada, edema de membros inferiores,\nhepatomegalia, turgência jugular a 45º e história clínica de IC).","B":"Bloqueadores de canal de cálcio e betabloqueadores intravenosos devem ser evitados quando\nhouver esta suspeita clínica (área cardíaca\naumentada, edema de membros inferiores,\nhepatomegalia, turgência jugular a 45º e história clínica de IC).","C":"Bloqueadores de canal de cálcio e betabloqueadores intravenosos devem ser evitados quando\nnão houver esta suspeita clínica (área\ncardíaca aumentada, edema de membros inferiores,\nhepatomegalia, turgência jugular a 45º e história clínica de IC).","D":"Bloqueadores de canal de cálcio e betabloqueadores intravenosos devem ser utilizados quando\nhouver esta suspeita clínica (área cardíaca\naumentada, edema de membros inferiores,\nhepatomegalia, turgência jugular a 45º e história clínica de IC)."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-317162","number":"317162","sourceNumber":"317162","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com base no traçado do Eletrocardiograma abaixo, assinale a correta:","options":{"A":"A frequência cardíaca é de 100 bpm.","B":"O ritmo não é sinusal","C":"Observa-se um desvio do eixo elétrico para esquerda","D":"Provável síndrome coronariana aguda"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300920","number":"300920","sourceNumber":"300920","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A atropina antagoniza a ação da acetilcolina, um neurotransmissor parassimpático, nos\nreceptores muscarínicos. Está CORRETO que:","options":{"A":"Dessa forma, ela não bloqueia o efeito do nervo vago tanto no nó sinoatrial como no nó\natrioventricular, aumentando a frequência de disparos do nó sinusal e facilitando a condução\natrioventricular.","B":"Dessa forma, ela bloqueia o efeito do nervo vago tanto no nó sinoatrial como no nó\natrioventricular, reduzindo a frequência de disparos do nó sinusal e facilitando a condução\natrioventricular.","C":"Dessa forma, ela bloqueia o efeito do nervo vago tanto no nó sinoatrial como no nó\natrioventricular, aumentando a frequência de\ndisparos do nó sinusal e dificultando a condução\natrioventricular.","D":"Dessa forma, ela bloqueia o efeito do nervo vago tanto no nó sinoatrial como no nó\natrioventricular, aumentando a frequência de disparos do nó sinusal e facilitando a condução\natrioventricular."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300922","number":"300922","sourceNumber":"300922","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Diversos sistemas manifestam sinais e sintomas como os listados a seguir relacionados\na ritmos com taquicardia, que são indicativos\ndeste comprometimento hemodinâmico, sendo\nCORRETO o item:","options":{"A":"Alteração no nível de consciência; hipotensão arterial sistêmica (Pressão Arterial Sistólica -\nPAS\n\n< 70 mmHg) ou choque circulatório com alteração da perfusão periférica; congestão pulmonar; e\ndor precordial anginosa.","B":"Alteração no nível de consciência; hipotensão arterial sistêmica (Pressão Arterial Sistólica -\nPAS\n\n< 90 mmHg) ou choque circulatório com alteração da perfusão periférica; congestão pulmonar; e\ndor precordial anginosa.","C":"Alteração no nível de consciência; hipotensão arterial sistêmica (Pressão Arterial Sistólica -\nPAS\n\n< 90 mmHg) ou choque circulatório sem alteração da perfusão periférica; congestão pulmonar; e\ndor precordial anginosa.","D":"Alteração no nível de consciência; hipotensão arterial sistêmica (Pressão Arterial Diastólica -\nPAD < 90 mmHg) ou choque circulatório com\nalteração da perfusão periférica; congestão pulmonar;\ne dor precordial anginosa."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300926","number":"300926","sourceNumber":"300926","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Adenosina é uma droga que diminui a condução pelo nó atrioventricular e promove\nvasodilatação coronária. Sendo CORRETO que:","options":{"A":"Possui meia-vida de menos de 5 a 10 minutos, tendo efeito fugaz, porém efetivo no término da\nmaioria das taquicardias de QRS estreito.","B":"Possui meia-vida de menos de 5 a 10 segundos, tendo efeito fugaz, porém efetivo no término da\nmaioria das taquicardias de QRS estreito.","C":"Possui meia-vida de menos de 5 a 10 segundos, tendo efeito fugaz, e inefetivo no término da\nmaioria das taquicardias de QRS estreito.","D":"Possui meia-vida de menos de 5 a 10 segundos, tendo efeito fugaz, porém efetivo no término da\nmaioria das taquicardias de QRS largo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300927","number":"300927","sourceNumber":"300927","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"As contraindicações absolutas à adenosina são listadas adequadamente na alternativa:","options":{"A":"Bloqueio atrioventricular de primeiro grau, disfunção do nó sinusal e FA pré-excitada.","B":"Bloqueio de ramo direito, disfunção do nó sinusal e FA pré-excitada.","C":"Bloqueio atrioventricular de segundo ou terceiro graus, disfunção do nó sinusal e FA\npré-excitada.","D":"Bloqueio atrioventricular de segundo ou terceiro graus, disfunção do nó átrio ventricular e FA\npré-excitada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-311919","number":"311919","sourceNumber":"311919","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher, 61 anos, solteira, procura um pronto atendimento de uma unidade hospitalar\napós perceber, de forma ocasional, uma redução\nda sua frequência cardíaca. Dá entrada na\nunidade com frequência cardíaca de 40bpm, PA de 120x80mmHg, tempo de enchimento capilar de\num segundo, consciente, negando dispneia ou dor torácica. Após avaliação do D2 longo no ECG,\nqual é a conduta imediata?","options":{"A":"Monitorizar e administrar atropina.","B":"Monitorizar e programar passagem de marcapasso definitivo.","C":"Monitorizar e passar marcapasso transvenoso.","D":"Monitorizar e iniciar dopamina em BIC."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300930","number":"300930","sourceNumber":"300930","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Verapamil e diltiazem mostraram-se efetivos em reversão para ritmo sinusal em\ndiversos ensaios clínicos e nesse contexto, assinale a alternativa correta:","options":{"A":"Permanecem como tratamento de segunda linha para o tratamento das taquicardias\nsupraventriculares.","B":"Permanecem como tratamento de primeira linha para o tratamento das taquicardias\nventriculares.","C":"Permanecem como tratamento de primeira linha para o tratamento das bradicardias\nsupraventriculares.","D":"Permanecem como tratamento de primeira linha para o tratamento das taquicardias\nsupraventriculares."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-311923","number":"311923","sourceNumber":"311923","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Utilizando como base o BLS/ACLS, como deve orientar sua equipe em vigência de uma\nparada cardiorrespiratória, visando a uma reanimação de qualidade?","options":{"A":"Velocidade de compressão até 100 vezes por minuto.","B":"Administrar adrenalina a cada 2 minutos.","C":"Se houver via área avançada, manter massagem cardíaca contínua com ventilações a cada 6\nsegundos.","D":"Profundidade de compressão entre 5-7 cm."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-300933","number":"300933","sourceNumber":"300933","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em pacientes estáveis com Fibrilação Atrial e Flutter Atrial, dados como Fração de\nEjeção de Ventrículo Esquerdo (FEVE), tempo de duração da arritmia (menor ou maior que 48\nhoras) e presença de pré-excitação ventricular (síndrome de Wolf-Parkinson-White) estão de\nacordo com o item:","options":{"A":"São dispensáveis para tomada de decisões acerca de indicação de anticoagulação, reversão do\nritmo ou controle da resposta ventricular e avaliação da segurança para reversão do ritmo.","B":"São imprescindíveis para tomada de decisões acerca de indicação de anticoagulação, reversão\ndo ritmo ou controle da resposta ventricular e\navaliação da segurança para reversão do ritmo.","C":"São imprescindíveis para tomada de decisões acerca de indicação de anticoagulação, reversão\ndo ritmo e não do controle da resposta\nventricular e avaliação da segurança para reversão do ritmo.","D":"São imprescindíveis para tomada de decisões acerca de indicação de anticoagulação, reversão\ndo ritmo ou controle da resposta ventricular e\nnunca da avaliação da segurança para reversão do\nritmo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-308286","number":"308286","sourceNumber":"308286","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente é encontrado não responsivo em leito de enfermaria pela equipe de\nenfermagem que, de imediato, aciona o código\nazul. Você se dirige para avaliação do caso e\npercebe que o paciente não responde e não apresenta pulso. O carrinho de parada já se encontra\nno cenário. Neste contexto, a melhor conduta imediata é:","options":{"A":"Desfibrilação com 200 J.","B":"RCP por 2 minutos seguida de avaliação de ritmo.","C":"Amiodarona EV 300mg em bolus.","D":"Cardioversão com 200 J."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-285058","number":"285058","sourceNumber":"285058","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma paciente de 26 anos procurou a emergência com queixas de pal pitações e\ndispneia aos esforços, iniciadas há três\ndias. Ao exame, apresenta-se eupneica, conscien te e\norientada, com turgência jugular, estertores fi nos em bases pulmonares, ritmo cardíaco irregu\nlarmente irregular com frequência de 120 bpm e sopro diastólico no ictus cordis. PA 120x70mmHg.\nQual a medida recomendada nesse momento?","options":{"A":"Diltiazem.","B":"Amiodarona.","C":"Ecocardiograma transesofágico.","D":"Cardioversão elétrica.","E":"Warfarin."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-258162","number":"258162","sourceNumber":"258162","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante uma partida de futebol em um clube da cidade, um jogador cai no gramado\nespontaneamente, ou seja, sem contato com outro jogador ou objeto. À avaliação inicial,\nencontrava-se irresponsivo, sem ventilação espontânea e sem pulso. Foram iniciadas manobras de\nreanimação. Em menos de três minutos houve a chegada da caixa de socorro com ambu e\nmáscara facial e dispositivo automático externo (DEA), que estavam bem próximos ao campo de\nfutebol. Nesse caso, qual deverá ser a próxima conduta?","options":{"A":"Manter massagem cardíaca externa e ventilação com máscara e ambu na frequência 30:2, sem\ninterrupções enquanto aguarda-se o socorro médico.","B":"Instalar o DEA, de acordo com as instruções, e aguardar até 15 segundos para leitura do ritmo.","C":"Instalar o DEA e após cinco segundos, se o ritmo não for identificado, reiniciar a massagem\ncardíaca externa.","D":"Realizar ajuste manual para desfibrilação com 200J, caso o ritmo não for identificado pelo DEA\napós cinco segundos e o paciente continuar\nsem pulso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-257720","number":"257720","sourceNumber":"257720","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 44 anos, obeso, fumante e dislipidêmico, apresenta um episódio de\nfibrilação atrial após ingesta excessiva de bebida alcoólica. De acordo com a classificação de\nCHA2DS2-VASc, qual o tratamento adequado para prevenção de fenômeno tromboembólico?","options":{"A":"Orientação e acompanhamento.","B":"Aspirina 100 mg, ao dia.","C":"Warfarina.","D":"Rivaroxabana 20 mg, ao dia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-258171","number":"258171","sourceNumber":"258171","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Os betabloqueadores pertencem a qual classe de antiarrítmicos?","options":{"A":"V.","B":"IV.","C":"III.","D":"II."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-265855","number":"265855","sourceNumber":"265855","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A terapia farmacológica também pode ser recomendada para se restaurar o ritmo\nsinusal de Fibrilação Atrial e Flutter Atrial de início < 48 horas, sendo ADEQUADO o item:","options":{"A":"É a primeira escolha (reservar para casos em que a CVE e seu preparo - sedação - impõem\nrisco alto para o paciente). Vários estudos\nforam realizados para definir a eficácia de medicações\nna cardioversão química da FA.","B":"Não é a primeira escolha (exceto para casos em que a CVE e seu preparo - sedação - impõem\nrisco alto para o paciente). Vários estudos foram realizados para definir a eficácia de medicações\nna cardioversão química da FA.","C":"Não é a primeira escolha (reservar para casos em que a CVE e seu preparo - sedação - impõem\nrisco alto para o paciente). Não existem estudos realizados para definir a eficácia de medicações na\ncardioversão química da FA.","D":"Não é a primeira escolha (reservar para casos em que a CVE e seu preparo - sedação - impõem\nrisco alto para o paciente). Vários estudos foram realizados para definir a eficácia de medicações\nna cardioversão química da FA."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-265856","number":"265856","sourceNumber":"265856","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Evidências recentes mostraram que a lidocaína apresentou mesma taxa de sobrevida\nquando comparada à amiodarona em PCR extra-hospitalar. Podemos indicar como CORRETO\nque:","options":{"A":"A dose inicial recomendada é de 1,0 a 1,5 mg/kg por via intravenosa. Se a FV/TVSP não\npersistir, uma segunda dose de 0,5 a 0,75 mg/kg pode ser administrada. Seu uso pode ser\nconsiderado após a PCR em FV/TVSP em infusão contínua.","B":"A dose inicial recomendada é de 1,0 a 1,5 mg/kg por via intravenosa. Se a FV/TVSP persistir,\numa segunda dose de 0,5 a 0,75 mg/kg pode ser\nadministrada. Seu uso não pode ser considerado\napós a PCR em FV/TVSP em infusão contínua.","C":"A dose inicial recomendada é de 1,0 a 1,5 mg/kg por via intravenosa. Se a FV/TVSP persistir,\numa segunda dose de 0,5 a 0,75 mg/kg pode ser\nadministrada. Seu uso pode ser considerado após\na PCR em FV/TVSP em infusão não contínua.","D":"A dose inicial recomendada é de 1,0 a 1,5 mg/kg por via intravenosa. Se a FV/TVSP persistir,\numa segunda dose de 0,5 a 0,75 mg/kg pode ser\nadministrada. Seu uso pode ser considerado após\na PCR em FV/TVSP em infusão contínua."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-274767","number":"274767","sourceNumber":"274767","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 76 anos, portador de hipertensão arterial e diabetes mellitus, descobre\nrecentemente ser portador de fibrilação atrial. Sobre a profilaxia de acidente vascular cerebral\nnesses pacientes:","options":{"A":"não está indicado o uso de anticoagulantes orais após a cardioversão e manutenção do ritmo\nsinusal.","B":"apesar da necessidade de monitorização da sua atividade, a varfarina apresenta menor risco de\nsangramento intracraniano nesses pacientes.","C":"antiagregantes plaquetários não são eficazes, e não devem ser utilizados para profilaxia de\nAVC.","D":"os anticoagulantes orais diretos (DOAC) são mais eficazes que a varfarina em previnir AVC,\nindependente da droga e a dose escolhida."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-265858","number":"265858","sourceNumber":"265858","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Estudos observacionais mostraram que a administração de sulfato de magnésio por via\nintravenosa pode finalizar TV polimórfica do tipo TdP, podemos indicar como CORRETO que:","options":{"A":"É efetiva para TV polimórfica em pacientes com intervalo QT normal.","B":"Não é efetiva para TV polimórfica do tipo TdP.","C":"Não é efetiva para TV polimórfica em pacientes com intervalo QT normal.","D":"Não é efetiva para TV polimórfica em pacientes com intervalo QT padrão."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-265859","number":"265859","sourceNumber":"265859","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação à orientação do uso de drogas e manobras no Suporte Avançado de Vida\nem adultos, indique o item ERRADO:","options":{"A":"Amiodarona ou lidocaína devem ser considerados como antiarrítmico de primeira escolha para\nFV/TVSP que não responde a RCP, desfibrilação e vasopressor.","B":"O uso de lidocaína pode ser considerado alternativa na PCR em FV/TVSP.","C":"O uso precoce de betabloqueadores pode ser considerado em pacientes pós-RCE por ritmos de\nFV/TVSP","D":"O soco precordial pode ser considerado na TV instável em pacientes monitorizados, quando um\ndesfibrilador está imediatamente pronto para uso."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-265861","number":"265861","sourceNumber":"265861","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O cálcio apresenta papel no mecanismo celular de contração miocárdica e da\nmusculatura lisa vascular. Indique o item com ERRO:","options":{"A":"Não há evidências científicas que deem suporte ao uso rotineiro do cálcio na RCP.","B":"Seu uso pode ser considerado, na dose de 0,5 a 1 g (gluconato de cálcio 10%, de 15 a 30 mL,\nou cloreto de cálcio 10%, de 5 a 10 mL).","C":"Seu uso pode ser considerado nas seguintes condições de PCR: hiperpotassemia, hipocalcemia\ne intoxicação por agentes bloqueadores dos canais\nde cálcio.","D":"Utilizar soluções de cálcio e bicarbonato de sódio simultaneamente na mesma via de\nadministração."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-281992","number":"281992","sourceNumber":"281992","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação à prevenção de fenômenos tromboembolicos na fibrilação atrial, é correto\nafirmar que:","options":{"A":"Os NOACs (novos anticoagulantes orais) reduzem as taxas de acidente vascular encefálico\nhemorrágico ao serem comparados aos antagonistas da vitamina K.","B":"A anticoagulação plena só é indicada nas formas persistente e permanente da fibrilação ou\nflutter.","C":"O escore CHADSVASC é usado para avaliar risco tromboembólico, sendo indicada\nanticoagulação com escores acima de 3 pontos.","D":"O anticoagulante de preferência em pacientes com prótese valvar mecânica aórtica é o\ndabigatrana."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-265865","number":"265865","sourceNumber":"265865","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Na Massagem do Seio Carotídeo (MSC), temos esse mesmo reflexo, sendo CORRETO\nque:","options":{"A":"Inibido pela pressão externa no bulbo carotídeo, estimulando seus barorreceptores.","B":"Deflagrado pela pressão externa no bulbo carotídeo, reprimindo seus barorreceptores.","C":"Deflagrado pela pressão interno no bulbo carotídeo, estimulando seus barorreceptores.","D":"Deflagrado pela pressão externa no bulbo carotídeo, estimulando seus barorreceptores."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-281996","number":"281996","sourceNumber":"281996","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O ano de 2020 foi um ano marcado por diversas atualizações publicadas pela AHA\n(American Heart Association) em que houve algumas modificações. Sobre isso, assinale a\nalternativa incorreta:","options":{"A":"Os elos da cadeia de sobrevivência bem como as medidas de cuidados pós-parada cardíaca\nforam ratificados em 2020, por recentes estudos e\nníveis de recomendações cada vez mais\nelevados.","B":"Nos ritmos em assistolia ou atividade elétrica sem pulso (AESP), a prioridade é a administração\nprecoce de adrenalina 1 mg. Além disso, o\nacesso intravenoso se tornou definitivamente a\npreferência, só devendo o intraósseo ser utilizado se não houve sucesso. A busca por causas\nreversíveis pelo 5H/5T não foram modificadas.","C":"No algoritmo das bradicardias instáveis foi dobrada a dose de atropina para 1mg a cada 3 a\n5min, assim como a dose mínima de dopamina de 2 para 5Mcg/kg/min.","D":"No caso da FV/TV, a prioridade é realizar desfibrilação elétrica na carga recomendada pelo\nfabricante (em geral 200J bifásico, mas na dúvida coloque a carga máxima do seu aparelho) e\nreiniciar a massagem cardíaca. A sequência de drogas, adrenalina e amiodarona, está mantida,\nbem como os ciclos de 30:2 compressão/ventilação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-274478","number":"274478","sourceNumber":"274478","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente sexo feminino, 55 anos, chega ao pronto atendimento com queixa de\npalpitação. Ao avaliar paciente você não\nidentifica nenhum sinal de instabilidade clínica. Saturação\nadequada na oximetria. Ao monitorá-la, percebe uma taquicardia monomórfica de complexo largo.\nPaciente se mantém comunicando normalmente. Dentro deste contexto a conduta inicial MAIS\nADEQUADA é:","options":{"A":"Amiodarona venosa 300 mg em bolus.","B":"Amiodarona venosa 150 mg em 10 minutos.","C":"Milrinone venoso 300 mg em 10 minutos.","D":"Milrinone venoso 150 mg em bolus."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-265869","number":"265869","sourceNumber":"265869","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"São antecedentes familiares importantes na avaliação de crianças e adolescentes que\napresentam síncope, EXCETO:","options":{"A":"Doença cardíaca congênita.","B":"Arritmias.","C":"Doenças metabólicas.","D":"História de pneumonia com derrame em pais ou irmãos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-265884","number":"265884","sourceNumber":"265884","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao exame físico de crianças com\nsíncope:","options":{"A":"Os sinais vitais devem ser registrados exclusivamente com o paciente em posição ortostática.","B":"Se a pressão sistólica de adolescentes, após a realização dos dois registros dos sinais vitais,\nfor\nmenor do que 80 mmHg ou houver variação de mais de 30mmHg, a etiologia provável é vagal\nmediada.","C":"A palpação do precórdio na avaliação cardiológica pode sugerir doenças cardíacas estruturais.","D":"Qualquer deficiência focal ou anormalidade no exame neurológico deve alertar o pediatra para\npossibilidade convulsão ou outra doença neurológica como causa da síncope."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-274834","number":"274834","sourceNumber":"274834","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Adolescente, sexo masculino, 12 anos, comparece a consulta solicitando atestado para\nprática de natação. Assintomático, sem história familiar de risco para doença cardiovascular.\n\nExame físico: dados vitais e exame segmentar normais. Traz eletrocardiograma realizado há um\nano para avaliação pré-operatória de cirurgia\nortopédica com laudo de arritmia sinusal. A conduta\nindicada neste caso é:","options":{"A":"indicar Tilt teste.","B":"realizar ecocardiograma.","C":"liberar para prática de natação.","D":"solicitar novo eletrocardiograma."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-229491","number":"229491","sourceNumber":"229491","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Para os pacientes estáveis, com FA (Fibrilação Atrial) persistente, que vão se submeter\nà cardioversão elétrica ou química, recomenda-se a\nACO (Anticoagulante Oral) por pelo menos 3\nsemanas antes e 4 semanas após cardioversão na faixa terapêutica (RNI entre 2 a 3). Somente\nestá ERRADO o item:","options":{"A":"Após 2 semanas, a manutenção da ACO deve ser de acordo com score de risco de CHA2 DS2\nVASC.","B":"O uso de ACO está indicado para os pacientes com flutter atrial nas mesmas considerações que\nna FA.","C":"A dose preferencial de rivaroxabana deve ser de 20 mg/dia, desde que tenham baixo risco de\nsangramento.","D":"A dose preferencial de dabigatrana deve ser de 150 mg 2x/dia, desde que tenham baixo risco de\nsangramento."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-229495","number":"229495","sourceNumber":"229495","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Para paciente submetidos à cardioversão elétrica guiada por ECOTE e sem trombos,\nrecomenda-se a HNF EV (bolus seguido de infusão contínua) antes da cardioversão e deve-se\nmantê-la até que a ACO plena seja atingida. Somente devemos indicar como ERRADO:","options":{"A":"Para pacientes com FA que necessitam de cardioversão elétrica de emergência, recomenda-se\na HNF EV (bolus seguido de infusão\nintermitente).","B":"Para paciente submetidos à cardioversão elétrica guiada por ECOTE e sem trombos,\nrecomenda-se a HBPM antes da cardioversão e\ndeve-se mantê-la até que a anticoagulação oral\nplena seja atingida.","C":"Para pacientes com FA que necessitam de cardioversão elétrica de emergência, recomenda-se\ndose plena de HBPM.","D":"Se for identificado trombo, anticoagulação dever ser mantida por 3 semanas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249464","number":"249464","sourceNumber":"249464","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Para que ocorra uma melhoria nas estruturas e nos sistemas de saúde, que é um dos\npontos essenciais no sucesso do atendimento da parada cardiorrespiratória (PCR), sendo\ninadequado apenas:","options":{"A":"Criação de um sistema integrado com treinamento de pessoas.","B":"Auxílio de materiais de emergência.","C":"Transportes para um atendimento unificado.","D":"Disponibilidade de DEA em locais públicos com baixa movimentação de pessoas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249467","number":"249467","sourceNumber":"249467","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Atualização da Diretriz de Ressuscitação Cardiopulmonar e Cuidados Cardiovasculares\nde Emergência da Sociedade Brasileira de\nCardiologia ? 2019. Listamos abaixo itens referentes à\ncadeia de elos de sobrevivência diferenciadas no contexto de uma parada cardiorrespiratória (PCR)\nintra-hospitalar, determine o item que não pode ser considerado como parte da mesma:","options":{"A":"RCP imediata de alta qualidade.","B":"Rápida desfibrilação.","C":"Suporte básico de Vida.","D":"Cuidados pós-PCR."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249468","number":"249468","sourceNumber":"249468","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A Ressuscitação Cardiopulmonar e Cuidados Cardiovasculares inseridos nos Cuidados\npós-PCR, apresenta como importante ponto o item:","options":{"A":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom maior tolerância na variação de\ntemperatura e prevenção de febre.","B":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom menor variação de temperatura e prevenção\nde febre.","C":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom menor variação de temperatura e sem\nprevenção de febre.","D":"Ênfase na avaliação neurológica, sem o cumprimento das metas hemodinâmicas e controle\ntérmico, com menor variação de temperatura e prevenção de febre."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249471","number":"249471","sourceNumber":"249471","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A adequada abordagem de Ressuscitação Cardiopulmonar e Cuidados\nCardiovasculares com ênfase nos cuidados após o\nretorno à circulação espontânea trouxe\nmelhorias nos resultados, contribuído ao prognóstico dos pacientes. Podemos assim determinar\ncomo adequado que:","options":{"A":"O reconhecimento precoce das causas desencadeantes, orientando a intervenção para cada\ncenário clínico.","B":"O reconhecimento tardio das causas desencadeantes, orientando a intervenção para cada\ncenário clínico.","C":"O reconhecimento precoce das causas desencadeantes, desorientando a intervenção para cada\ncenário clínico.","D":"O reconhecimento precoce das causas desencadeantes, não orientando a intervenção para\ncada cenário clínico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-248912","number":"248912","sourceNumber":"248912","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"As arritmias cardíacas são decorrentes, basicamente, de alterações na geração do\nimpulso (automatismo anormal e atividade deflagrada) e/ou na condução do impulso (reentrada).\nSobre os principais mecanismos de taquiarritmia mais prevalentes na população pediátrica, sua\nclassificação e tratamento, não podemos afirmar que:","options":{"A":"as células miocárdicas atriais e ventriculares normalmente não apresentam atividade de\nmarca-passo","B":"a reentrada é o mecanismo gerador de taquiarritmias supraventriculares e ventriculares mais\nfrequente e relevante, podendo ser anatômica ou funcional","C":"as arritmias cardíacas podem ser classificadas, quanto à repercussão clínica, em estável ou\ninstável","D":"cicatrizes (fibroses) miocárdicas secundárias à cardiopatia estrutural não favorecem o\ndesenvolvimento de reentrada"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249477","number":"249477","sourceNumber":"249477","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O algoritmo do protocolo no atendimento de uma PCR é formado pela cadeia de elos\nde sobrevivência diferenciadas, está de acordo com o item:","options":{"A":"O protocolo no atendimento de uma PCR segue uma sequência lógica e fundamentada de\ncondutas que melhoram as taxas de\nreversibilidade do processo inicial que desencadeou o evento.","B":"O protocolo no atendimento de uma PCR segue uma sequência lógica, mas não fundamentada\nde condutas que melhoram as taxas de\nreversibilidade do processo inicial que desencadeou o\nevento.","C":"O protocolo no atendimento de uma PCR segue uma sequência lógica e fundamentada de\ncondutas que melhoram as taxas de\nreversibilidade do processo final que desencadeou o evento.","D":"O protocolo no atendimento de uma PCR segue uma sequência lógica e fundamentada de\ncondutas que melhoram as taxas de reversibilidade do processo inicial que não desencadeou o\nevento."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-247411","number":"247411","sourceNumber":"247411","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 57 anos, sexo masculino, é admitido no pronto-socorro com dor torácica\nem queimação, retroesternal, de início há três\nhoras, de forte intensidade, associada à sudorese e\npalpitações. Ao ser monitorizado, seus sinais vitais revelam PA = 164/98 mmHg, Frequência\nCardíaca (FC) de 172bpm, Frequência Respiratória (FR) de 24 irpm e Saturação de Oxigênio\n(SaO?) em 94%. O ritmo ao monitor é o seguinte: A conduta imediata é:","options":{"A":"cardioversão elétrica sincronizada.","B":"adenosina 6 mg IV.","C":"amiodarona 150mg IV.","D":"metoprolol 5mg IV."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-249870","number":"249870","sourceNumber":"249870","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Pediatra recebe no pronto-socorro, trazida pelos bombeiros, uma criança, vítima de\nafogamento, em apneia, porém, com pulso central. Qual é a classificação do afogamento desta\ncriança?","options":{"A":"Grau 2.","B":"Grau 4.","C":"Grau 5.","D":"Grau 6."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-229547","number":"229547","sourceNumber":"229547","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente feminina, 35 anos, sem comorbidades, admitida em leito de terapia intensiva\napós laparotomia exploradora por cisto de ovário\nroto. Após 12 horas de observação clínica,\napresenta dor torácica de forte intensidade, palpitações, associada a dispneia súbita. Nega\nvômitos. Permanece estável hemodinamicamente, sem alterações neurológicas. Realizado\neletrocardiograma abaixo. A conduta MAIS adequada neste caso é:","options":{"A":"amiodarona 300mg em bolus.","B":"amiodarona 150mg em bolus.","C":"metoprolol 25mg via oral.","D":"cardioversão elétrica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-229888","number":"229888","sourceNumber":"229888","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante uma reanimação cardiopulmonar, qual recomendação de massagem cardíaca\ne ventilação, após a obtenção de via aérea\navançada:","options":{"A":"1 ventilação a cada 30 compressões torácicas.","B":"2 ventilações a cada 30 compressões torácicas.","C":"1 ventilação a cada 6 segundos e compressões torácicas contínuas.","D":"1 ventilação a cada 10 segundos e compressões torácicas contínuas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-229889","number":"229889","sourceNumber":"229889","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Você está tratando um indivíduo que apresentou uma fibrilação ventricular. Após\nreanimação cardiopulmonar e uma tentativa de desfibrilação, seu novo ritmo é um bloqueio\natrioventricular de 3º grau. O próximo passo no manejo é","options":{"A":"repetir desfibrilação.","B":"vasopressina.","C":"marca-passo transcutâneo.","D":"epinefrina alta dose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-246606","number":"246606","sourceNumber":"246606","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A atividade física compreende qualquer movimento corporal produzido por músculos\nesqueléticos e que resulta em dispêndio de energia. Assinale, a seguir, uma atividade considerada\nde alta intensidade.","options":{"A":"Movimentar móveis.","B":"Limpar a casa.","C":"Realizar exercícios de alongamento.","D":"Executar trabalho de carpintaria.","E":"Caminhar lentamente."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-210541","number":"210541","sourceNumber":"210541","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Considere: paciente em consulta ambulatorial de Cardiologia, sexo masculino, 63 anos,\nportador de fibrilação atrial crônica, sem antecedentes de hipertensão arterial, diabetes ou doença\ncoronariana, apresenta história de ataque isquêmico transitório no ano anterior. Sobre o manejo\nclínico, assinale a afirmativa correta.","options":{"A":"A seleção da terapia antitrombótica independe da forma de apresentação da FA.","B":"O paciente apresenta 2 fatores de risco maiores pelo escore CHA2DS2VASc.","C":"Se portador de prótese mitral mecânica, é recomendada varfarina e manter RNI>2.","D":"Pode ser indicada neste caso a dabigatrana, na dose preferencial de 110mg 2x/dia.","E":"A combinação AAS + clopidogrel pode ser feita, com eficácia similar à da varfarina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-218214","number":"218214","sourceNumber":"218214","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação ao tratamento da fibrilação atrial aguda, assinale a alternativa correta:","options":{"A":"A cardioversão elétrica não sincronizada está indicada na presença de QT longo.","B":"A administração de amiodarona intravenosa alcança taxas de reversão em torno de 99% em 24\nhoras.","C":"Quanto maior o átrio esquerdo, menor a chance de sucesso na cardioversão elétrica.","D":"O Sotalol por via oral é a droga de escolha para reversão em pacientes com insuficiência\ncardíaca."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-217036","number":"217036","sourceNumber":"217036","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 57 anos, sexo feminino, com queixa de mal-estar súbito há 1 hora, estável\nhemodinamicamente, admitida com o seguinte ECG: no caso apresentado, é recomendado o uso\nde qual fármaco?","options":{"A":"Procainamida.","B":"Adenosina.","C":"Verapamil.","D":"Cardizem.","E":"Digoxina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-202630","number":"202630","sourceNumber":"202630","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A adrenalina quando administrada como terapia na reanimação de parada cardíaca tem\ncomo objetivo promover:","options":{"A":"Vasoconstrição venosa.","B":"Aumento da resistência vascular arterial.","C":"Efeito beta-adrenérgico periférico.","D":"Aumento dos efeitos broncodilatadores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-201700","number":"201700","sourceNumber":"201700","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em pacientes idosos com fibrilação atrial paroxística, a melhor e mais segura maneira\nde reduzir a recorrência de AVC é:","options":{"A":"Aspirina, 325 mg ao dia.","B":"Aspirina, 325 mg ao dia, e clopidogrel, 75 mg ao dia.","C":"Apixabana.","D":"Warfarin."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-202643","number":"202643","sourceNumber":"202643","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O escore CHADS? é utilizado na avaliação da necessidade de anticoagulação nos\npacientes com fibrilação atrial de etiologia não valvular. Um paciente do sexo masculino, de 76\nanos, com fibrilação atrial, hipertenso crônico adequadamente tratado, obeso, antecedente de\ninfarto agudo sem disfunção sistólica de VE e sem outras comorbidades, apresenta qual valor no\nescore CHADS??","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-205562","number":"205562","sourceNumber":"205562","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um menino de um ano é levado ao pronto-socorro para ser avaliado por inapetência,\nagitação e sudorese. Na impressão inicial, ele\nse mostra letárgico, mas consegue despertar, tem\ndificuldade para respirar e apresenta-se cianótico. A primeira avaliação releva frequência\nrespiratória de 68 irpm, frequência cardíaca de 300 bpm que não varia com atividade ou sono,\npressão arterial de 70 x 45 mmHg, pulso braquial fraco e pulso radial ausente, enchimento capilar\nde 6 segundos, SatO2 de 85% em ar ambiente e ruídos respiratórios bilaterais bons. Você\nadministra oxigênio de alto fluxo e coloca a criança no monitor cardíaco. Não há histórico de\ndoença cardíaca congênita. Você observa o seguinte ritmo com pouca variabilidade da frequência\ncardíaca entre batimentos: o acesso EV foi estabelecido. Qual das seguintes terapias é a mais\nadequada para esta criança?","options":{"A":"Marcar uma consulta com o cardiologista pediátrico para o fim da semana.","B":"Infusão rápida de adenosina 0,1 mg/Kg EV; se a adenosina não estiver disponível\nimediatamente, realizar cardioversão sincronizada.","C":"Realizar desfibrilação imediata sem esperar por acesso IV.","D":"Estabelecer acesso IV e administrar um bolus de 20 ml/Kg de fluido cristalóide isotônico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-215454","number":"215454","sourceNumber":"215454","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"São fatores que podem precipitar o evento sincopal em crianças, EXCETO","options":{"A":"hiperextensão do pescoço.","B":"uso abusivo de celular.","C":"emoções.","D":"desidratação."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-217056","number":"217056","sourceNumber":"217056","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Nas Diretrizes de 2010 da American Heart Association (AHA) para Ressuscitação\nCardiopulmonar (RCP) em pediatria, alguns\nalgoritmos foram estabelecidos. Assinale a alternativa\nque não expressa o que foi exposto por tais diretrizes.","options":{"A":"Em se tratando de profissional de saúde no socorro à vítima de PCR, pulso e respiração devem\nser checados concomitantemente.","B":"Se o socorro à vítima de PCR está sendo prestado por um leigo, sozinho, é preferível que o\nmesmo acione o serviço de emergência antes de iniciar a RCP.","C":"Se a vítima encontra-se inconsciente, com respiração irregular e pulso acima de 60\nbatimentos/minuto, o profissional de saúde pode\nrealizar ventilações, sem compressões torácicas,\ndurante 2 minutos, ao fim dos quais deve reavaliar o paciente.","D":"Mesmo na presença de pulso detectável na vítima pediátrica, caso a frequência seja inferior a 60\nbatimentos/minuto, o profissional de saúde deve realizar compressões torácicas.","E":"A proporção de compressões: ventilações na população pediátrica é de 30:2, quando o\nsocorrista está sozinho, e de 15:2, quando há mais de 1 socorrista proficiente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-174400","number":"174400","sourceNumber":"174400","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A desfibrilação e cardioversão elétrica consistem na aplicação de corrente elétrica de\nalta energia para reversão de arritmias cardíacas geradas pelo mecanismo de reentrada. Somente\napresenta dados considerados inadequados a alternativa:","options":{"A":"Na desfibrilação, esta corrente elétrica é aplicada em qualquer momento do ciclo cardíaco,\nenquanto na cardioversão elétrica, esta\ncorrente é sempre sincronizada com os complexos QRS do\neletrocardiograma para que não seja administrada durante o período vulnerável da repolarização\nventricular (onda T), quando pode potencialmente desencadear uma fibrilação ventricular.","B":"Os desfibriladores/cardioversores podem ser classificados de acordo com o modo de operação\nem: a) manuais, no qual o reconhecimento do\nritmo cardíaco e a administração do choque\ndependem do operador; b) semiautomáticos, também,\n\nconhecidos como DEA, nos quais o reconhecimento do ritmo é realizado pelo dispositivo que\ninforma se o choque elétrico é\n\nrecomendado ou não no tratamento do paciente, sendo que a decisão de aplicar o choque continua\nsendo do operador.","C":"Desfibriladores também podem ser classificados em externos e internos. Nos externos, a\ncorrente elétrica é aplicada através da\nsuperfície externa do tórax do paciente por meio de pás\nmanuais ou adesivas, enquanto, nos internos, a corrente elétrica é aplicada por cabos eletrodos\ngeralmente implantados através do sistema venoso.","D":"Na cardioversão a corrente elétrica é aplicada em qualquer momento do ciclo cardíaco, esta\ncorrente é sempre sincronizada para que não seja administrada durante o período refratário da\nrepolarização ventricular (onda T), quando pode potencialmente desencadear uma arritmia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-175387","number":"175387","sourceNumber":"175387","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem de 54 anos, portador de doença arterial coronariana crônica, apresenta,\napós intensa emoção, dor torácica precordial e\nperda da consciência. Os pulsos periféricos não são\nperceptíveis, e a pressão arterial não foi percebida. O mecanismo provável da parada é:","options":{"A":"assistolia","B":"atividade elétrica sem pulso","C":"taquicardia supraventricular","D":"fibrilação ventricular","E":"fibrilação atrial"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183254","number":"183254","sourceNumber":"183254","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O ECG é um exame simples, barato e não invasivo. Permite uma ideia da condição\ncardíaca do indivíduo e pode eventualmente\nidentificar situações de risco de morte súbita. Dentro\nda Definição do ritmo sinusal, sendo que podem ocorrer modificações de sua morfologia\ndependentes da FC, apenas não podemos considerar como sendo cabível o que se afirma na\nalternativa:","options":{"A":"O Ritmo Sinusal (RS) é um ritmo fisiológico do coração.","B":"Origina-se no átrio direito baixo.","C":"Observado no ECG de superfície pela presença de ondas P positivas nas derivações D1, D2 e\naVF.","D":"O eixo de P pode variar entre -30° e +90°."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-175405","number":"175405","sourceNumber":"175405","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Qual das afirmações a seguir sobre os efeitos da epinefrina durante a tentativa de\nressuscitação é verdadeira?","options":{"A":"a epinefrina reduz a resistência vascular periférica e diminui a pós-carga miocárdica, de modo\nque as contrações ventriculares são mais\neficazes","B":"a epinefrina melhora a pressão de perfusão da artéria coronária e estimula as contrações\nespontâneas quando há assistolia","C":"a epinefrina é contraindicada na fibrilação ventricular, pois aumenta a irritabilidade\nmiocárdica","D":"a epinefrina reduz o consume de oxigênio miocárdico","E":"nenhuma das respostas acima"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183321","number":"183321","sourceNumber":"183321","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Para os paciente que apresentam parada cardíaca antes de receber qualquer\nabordagem, a medida mais importante e de\nmaior impacto seria a difusão global do conhecimento\nsobre atendimento básico da parada cardíaca. Sobre esse assunto, podemos considerar como\nINCORRETO apenas o item:","options":{"A":"O reconhecimento e o tratamento da Fibrilação Ventricular (FV) por profissional da saúde\n(Médico ou Enfermeiro com treinamento em\nACLS, sigla do inglês Advanced Cardiac Life Support)\nsão seguramente excelentes instrumentos para melhorar os resultados pré-hospitalares no IAM,\nmas apenas na possibilidade de ter uma aplicabilidade difusa, por meio de programas de\natendimento de urgência em unidades móveis que estejam equipadas e disponíveis para cobertura\nglobal da população.","B":"A importância da FV como mecanismo de óbito precoce e a habilidade na ressuscitação e na\ndesfibrilação foram os fatores que propiciaram o desenvolvimento de programas de tratamento\npré-hospitalar do IAM.","C":"Estima-se que a desfibrilação salve cerca de duas vezes mais vidas que o tratamento\ntrombolítico, mas depende de sua rápida aplicação ao paciente.","D":"Identificar o perfil dos casos de IAM que não chegam aos hospitais, qualificando o estado atual\nde atendimento e quantificando o impacto de uma nova estratégia de grande difusão na\npopulação.."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-178802","number":"178802","sourceNumber":"178802","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O ECG acima demonstra:","options":{"A":"taquicardia vetricular polimórfica.","B":"taquicardia vetricular monomórfica.","C":"fibrilação ventricular.","D":"taquicardia paroxística supraventricular.","E":"extrassístoles ventriculares."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-174502","number":"174502","sourceNumber":"174502","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quando da opção para tratamento farmacológico, os principais medicamentos utilizados\nem pacientes portadores de fibrilação atrial,\napresentam efeitos adversos. Sobre isso, assinale a\nalternativa que demonstra INCORRETA correlação:","options":{"A":"Propafenona: depressão grave da contratilidade miocárdica, gosto metálico, visão borrada,\nnáusea, diarreia aquosa, tontura, agranulocitose.","B":"Betabloqueadores: bradicardia, broncoespasmo, erupção cutânea, fadiga, depressão mental,\npesadelos.","C":"Amiodarona: pneumonite (1-23%), neuropatia periférica, tremor, insônia e ataxia,\nfotossensibilização (90%), depósitos na córnea,\n\ncom repercussões visuais (3-13%), insuficiência cardíaca, bradicardia, intolerância digestiva,\nhepatite medicamentosa, coloração azulada da pele,\nexacerbação de asma brônquica, alterações\nno metabolismo dos glicídios e triglicerídeos, epididimite, disfunção renal.","D":"Sotalol: torsades de pointes (2,4%), bradicardia, fadiga, astenia, dispneia, tontura (2-4%)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-178810","number":"178810","sourceNumber":"178810","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação à arritmia encontrada no eletrocardiograma, são condutas possíveis as\nlistadas a seguir, exceto uma. Qual?","options":{"A":"Sulfato de magnésio.","B":"Lidocaína.","C":"Isoproterenol.","D":"Marca-passo provisório com aumento da frequência cardíaca (Overdrive Pacing).","E":"Amiodarona."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-174405","number":"174405","sourceNumber":"174405","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Podemos obter o controle do ritmo na Fibrilação Atrial por diversas condutas, clínicas\nou intervencionistas. Indique a alternativa que\napresenta conduta INADEQUADA:","options":{"A":"Evidências sólidas indicam que a ablação da Fibrilação Atrial é mais eficaz do que as drogas\nantiarrítmicas para controle do ritmo.","B":"A ablação está indicada como opção para a falência de uma droga antiarrítmica e também como\nprimeira escolha em pacientes selecionados com FA paroxística, sem doença estrutural.","C":"Pacientes com cardiopatia estrutural e FA paroxística igualmente podem ser considerados para\nablação como terapia inicial, desde que se suspeite de taquicardiomiopatia e que o paciente deseje\nrealizar ablação.","D":"A eficácia da ablação da FA não varia conforme as características clínicas da arritmia e a\nextensão da cardiopatia de base."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-173565","number":"173565","sourceNumber":"173565","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 55 anos deu entrada no pronto-socorro e foi diagnosticada uma Parada\nCardiorrespiratória (PCR) por Fibrilação Ventricular (FV). Qual é o melhor momento para iniciar\nepinefrina 1 mg?","options":{"A":"Imediatamente, antes da primeira desfibrilação.","B":"Imediatamente, depois da primeira desfibrilação.","C":"Após reiniciada a Ressuscitação Cardiopulmonar (RCP), depois da segunda desfibrilação.","D":"Durante a RCP e imediatamente antes da segunda desfibrilação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-174468","number":"174468","sourceNumber":"174468","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente apresentando quadro de Fibrilação Atrial solicita sua orientação quanto às\nopções de tratamento disponíveis atualmente,\nseus riscos e benefícios. Dentre as alternativas\nabaixo, existe uma INCORRETA, assinale-a:","options":{"A":"As evidências mais robustas de benefício e os melhores resultados são obtidos nos pacientes\njovens com FA paroxística/persistente sintomática sem cardiopatia estrutural relevante.","B":"Existem evidências de que a intervenção seja superior à dos fármacos AA, no tocante à redução\nde desfechos duros, como mortalidade, IC e\nacidentes vasculares cerebrais.","C":"Nesse perfil de pacientes, a intervenção proporciona melhora significativa da sintomatologia e da\nqualidade de vida.","D":"Porém, faltam dados que comprovem o benefício do procedimento nos pacientes muito idosos,\ncom FA persistente de longa duração, ou IC avançada."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-174506","number":"174506","sourceNumber":"174506","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dentre os conceitos sobre o tratamento híbrido da Fibrilação Atrial, somente pode ser\nconsiderado INADEQUADO o seguinte conceito ou afirmativa:","options":{"A":"Os chamados ?procedimentos híbridos? combinam cirurgia epicárdica minimamente invasiva\ncom mapeamento eletrofisiológico e ablação por cateter endocárdico.","B":"O objetivo dessa técnica mista é tratar, em especial, pacientes com FA persistente, nos quais\nessas técnicas utilizadas isoladamente teriam resultados insatisfatórios.","C":"O objetivo dessa técnica mista é tratar, em especial, pacientes com FA persistente, nos quais\nessas técnicas utilizadas isoladamente teriam resultados satisfatórios.","D":"No geral, os resultados com os procedimentos híbridos são expressivos, principalmente\nconsiderando a maior complexidade da população tratada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-182497","number":"182497","sourceNumber":"182497","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com relação à fibrilação atrial, assinale a alternativa incorreta:","options":{"A":"devido à ação inotrópica negativa dos betabloqueadores, devem ser evitados nos pacientes com\nfibrilação atrial","B":"hipertireoidismo e intoxicação alcoólica aguda são causas bem definidas de fibrilação atrial","C":"idade >75 anos é um fator de risco para acidente vascular cerebral no paciente portador de\nfibrilação atrial","D":"os bloqueadores dos canais de cálcio verapamil e diltiazem podem ser utilizados para o controle\nda frequência cardíaca nos pacientes com\nfibrilação atrial"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-183271","number":"183271","sourceNumber":"183271","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao paciente vítima de acidente por\nsubmersão:","options":{"A":"Afogamentos em piscinas têm alto potencial de desenvolver infecção pulmonar precoce.","B":"O diagnóstico de pneumonia muitas vezes é feito de forma equivocada, por exames de\nradiografia solicitados no início do quadro, em decorrência da presença de opacificações que\ncorrespondem à água nos pulmões.","C":"Antes de tomar a decisão de iniciar a antibióticoterapia, recomenda-se observar o paciente\nclinicamente por meio da presença de\n\nfebre, leucocitose, novos infiltrados pulmonares na radiografia e exames de culturas.","D":"Na prática, a origem da água em que ocorreu o acidente, salgada ou doce, não diferencia a\nclínica de edema pulmonar ou os distúrbios eletrolíticos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-185159","number":"185159","sourceNumber":"185159","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Você atende um paciente que está arresponsivo e sem pulsos. Uma vez iniciadas as\nmanobras de ressuscitação cardiopulmonar (RCP), ao chegar o monitor-desfibrilador bifásico, você\nidentifica o ritmo a seguir. A próxima conduta deve ser:","options":{"A":"desfibrilação a 200 Joules, reiniciar a RCP imediatamente.","B":"RCP por 2 minutos e, então, desfibrilação a 200 Joules.","C":"desfibrilação a 200 Joules, e reavaliar o ritmo em seguida.","D":"manter a RCP e infundir adrenalina 1mg IV."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-185123","number":"185123","sourceNumber":"185123","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher de 32 anos é atendida no pronto-socorro com queixa de palpitações\ntaquicárdicas. Tem apresentado episódios\nfrequentes de taquiarritmia que revertem\nespontaneamente e duram aproximadamente 10 minutos. O episódio de hoje iniciou há 30 minutos,\no que a fez procurar atendimento. Ela está lúcida e orientada, sem outras queixas, a PA =\n132/76mmHg, FC 176bpm, saturação de oxigênio 97%. O ECG realizado revela o seguinte ritmo:\nDentre as opções abaixo, a conduta indicada para o caso deve ser?","options":{"A":"administrar atropina IV.","B":"administrar adenosina IV.","C":"realizar cardioversão elétrica sincronizada.","D":"administrar amiodarona IV."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-174527","number":"174527","sourceNumber":"174527","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 76 anos, pós-operatório imediato de gastrectomia subtotal por\nAdenocarcinoma Gástrico. Apresenta-se com\nPA=80x40mmHg Pulso=161bpm Sat=91%\nFR=27irpm, associado a sudorese, palidez cutânea. Apresentando o seguinte Eletrocardiograma:\nEm relação ao quadro clínico, assinale a alternativa que apresenta a melhor conduta:","options":{"A":"Cardioversão Elétrica.","B":"Amiodarona.","C":"Adenosina.","D":"Lidocaína."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-178858","number":"178858","sourceNumber":"178858","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, 67 anos, chega à Unidade de Emergência referindo que apresentou um\nepisódio de sincope em sua residência, mal-estar geral e sudorese intensa. Na avaliação,\n\nobserva-se que o paciente está com PA =84 x 62 mmHg, dispneia (saturação de oxigênio = 89%) e\nedema em membros inferiores, Com a suspeita de alguma patologia cardiológica, é solicitado um\neletrocardiograma (ECG), do qual se obteve o seguinte traçado. Após análise do traçado e\nmediante os sinais e os sintomas do paciente, assinale a alternativa correta quanto ao ritmo obtido\nno ECG e quanto à conduta mais adequada.","options":{"A":"Ritmo: bloqueio atrioventricular de segundo grau (Mobitz II / Wenckebach). Conduta: iniciar\nmanobra vagal; caso não haja resposta, prosseguir com adenosina 6 mg.","B":"Ritmo: bloqueio atrioventricular de segundo grau (Mobitz I / Wenckebach). Conduta: iniciar\natropina 0,5 mg e titular até no máximo 3 mg\nde 3 a 5 minutos, caso não haja resposta, prosseguir\ncom marcapasso transcutâneo ou dopamina ou epinefrina.","C":"Ritmo: bradicardia sinusal, Conduta: observar e, se necessário, chamar o especialista ou\nencaminhar para uma unidade especializada.","D":"Ritmo: bloqueio atrioventricular de primeiro grau. Conduta: iniciar atropina 0,5 mg e titular\naté no\nmáximo 3 mg de 3 a 5 minutos; caso não haja resposta, prosseguir com adenosina 6 mg e titular\naté no máximo 12 mg.","E":"Ritmo: bloqueio atrioventricular de terceiro grau. Conduta: cardioversão sincronizada iniciando\ncom carga de 50 J e aumentando progressivamente\naté 150 J; caso não haja resposta, prosseguir\ninfusão de dopamina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-174426","number":"174426","sourceNumber":"174426","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Estudos epidemiológicos demonstram clara associação entre Fibrilação Atrial e risco de\nmorbimortalidade por diversos fatores. Sobre isso, assinale a alternativa CORRETA:","options":{"A":"Estudos epidemiológicos demonstram clara associação entre Fibrilação Atrial e risco de Acidente\nVascular Cerebral (AVC), isquêmico somente, sem alterar mortalidade.","B":"Alterações cognitivas, Insuficiência Cardíaca (IC) e implicações socioeconômicas também são\nconsequências importantes da FA.","C":"Em estudos clínicos envolvendo pacientes com IC, a FA não foi considerada fator de risco\nindependente para mortalidade.","D":"IC e FA coexistem em uma alta porcentagem de pacientes (22 a 42%). Além disso, o\naparecimento de FA em pacientes portadores de\nIC não está associado à elevação de do risco de\nmorte em comparação com os indivíduos sem o distúrbio do ritmo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-174517","number":"174517","sourceNumber":"174517","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Muitos fatores de risco clínicos estão associados ao aumento no risco de FA e,\npossivelmente, participam da elevação na prevalência observada nas últimas décadas, somente\nnão podemos considerar completamente correta a alternativa:","options":{"A":"Fatores clínicos predisponentes a FA ocorrem quando anormalidades eletrofisiológicas alteram o\ntecido atrial e promovem formação/propagação anormal do impulso elétrico.","B":"Muitos fatores de risco clínicos clássicos estão associados, tais como hipertensão, diabetes,\ndoença valvar, infarto do miocárdio e Insuficiência Cardíaca (IC).","C":"Podemos observar novos fatores de risco como presença de Apneia Obstrutiva do Sono (AOS),\nobesidade, uso de bebidas alcoólicas, exercício físico, história familiar e fatores genéticos.","D":"Na prática clínica, a influência da obesidade e da AOS parece impactar muito pouco na\nabordagem terapêutica dos pacientes portadores de FA."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157328","number":"157328","sourceNumber":"157328","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre as principais mudanças no ACLS 2015, qual recomendação é INCORRETA?","options":{"A":"Em via aérea avançada, preconizam-se 10 ventilações por minuto (1 ventilação a cada 6\nsegundos).","B":"A vasopressina não é mais utilizada no protocolo ACLS.","C":"Em via aérea avançada, ETCO2 menor que 10 mmHg na capnografia após 10 minutos de\nressuscitação pode ser utilizado para determinar fim dos esforços.","D":"Utilização precoce da adrenalina em pacientes com ritmo não chocável.","E":"Está recomendado o uso de circulação extracorpórea para ressuscitação em pacientes que não\nrespondem à ressuscitação convencional e que possam apresentar algum benefício."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157433","number":"157433","sourceNumber":"157433","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A desfibrilação é uma aplicação de corrente elétrica de alta energia para reversão de\narritmias cardíacas geradas pelo mecanismo de reentrada. Na desfibrilação, esta corrente elétrica é\naplicada em qualquer momento do ciclo cardíaco, enquanto na cardioversão elétrica esta corrente é\nsempre sincronizada com os complexos QRS do eletrocardiograma para que não seja administrada\ndurante o período vulnerável da repolarização ventricular (onda T), quando pode potencialmente\ndesencadear uma fibrilação ventricular. A desfibrilação está indicada no tratamento da fibrilação\nventricular e na taquicardia ventricular sem pulso, ambas em situações compatíveis com parada\ncardiorrespiratória. Este procedimento também está indicado para reversão de taquicardia\nventricular polimórfica sustentada devido à dificuldade de sincronização com os diferentes\ncomplexos QRS observados nesta arritmia. Em relação à necessidade de adequada classificação\nda arritmia para sua correta indicação, aponte a alternativa que se mostra INADEQUADA na\nclassificação ou uso da desfibrilação.","options":{"A":"Nos desfibriladores externos, a corrente elétrica é aplicada através da superfície externa do\ntórax\ndo paciente por meio de pás manuais ou\nadesivas.","B":"Nos desfibriladores internos, a corrente elétrica é aplicada por cabos eletrodos geralmente\nimplantados através do sistema venoso.","C":"Quanto ao formato da onda, podem ser classificados em monofásicos ou bifásicos. Nos\nmonofásicos, toda a energia elétrica selecionada é aplicada em duplo único sentido vetorial.","D":"Nos desfibriladores bifásicos, parte da corrente é administrada em um sentido e a outra parte, no\nsentido inverso (inversão de polaridade)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157439","number":"157439","sourceNumber":"157439","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Desfibrilação precoce é o tratamento de escolha para vítimas em Fibrilação Ventricular\nde curta duração, como vítimas que apresentaram\ncolapso súbito, sendo este o principal ritmo de\nparada cardíaca. Podemos alegar, como uma conduta INADEQUADA, uma das opções a seguir.\nAssinale-a.","options":{"A":"Nos desfibriladores externos, o choque elétrico é aplicado por intermédio das pás manuais, as\nquais o operador posiciona sobre o tórax, exercendo pressão de aproximadamente 13 kg.","B":"Deve-se ter o cuidado de colocar gel na interface entre as pás e o tórax, visando diminuir a\nresistência à passagem da corrente elétrica; já as pás adesivas são coladas sobre o tórax do\npaciente, dessa maneira dispensando a utilização do gel e da compressão.","C":"Em relação ao posicionamento das pás manuais e adesivas, o local mais adequado é a posição\nanterolateral, onde uma das pás é colocada na região infraclavicular direita e a outra pá na região\nprecordial.","D":"Posições alternativas, como anteroposterior e laterolateral, podem ser utilizadas em situações\nespeciais, como presença de marca-passo ou\ncardioversor-desfibrilador implantável, no qual as pás\ndevem ser obrigatoriamente posicionadas por, pelo menos, 3 cm de distância do gerador."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157448","number":"157448","sourceNumber":"157448","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Ocorre grande importância a tomada de decisão a respeito de terapêutica elétrica,\nsendo que a cardioversão elétrica está indicada para a reversão das taquiarritmias com\ninstabilidade hemodinâmica. Considera-se como critérios de instabilidade a presença de pelo\nmenos um dos critérios seguintes, EXCETO por:","options":{"A":"Hipotensão mesmo sem sinais de choque circulatório.","B":"Dor torácica anginosa.","C":"Dispneia associada à congestão pulmonar.","D":"Rebaixamento do nível de consciência."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157455","number":"157455","sourceNumber":"157455","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A estimulação cardíaca temporária, através do Marca-Passo Transcutâneo (MPTC), é\num procedimento de emergência que tem a vantagem de ser uma técnica não invasiva e de\ninstalação praticamente imediata. O MPTC é um dispositivo que pode estimular o ritmo cardíaco\npelo fornecimento de corrente elétrica por eletrodos colados na pele. Há despolarização elétrica,\nque levará à contração cardíaca. Dentre as suas indicações e características, DESCONSIDERE,\napenas, o contido em uma das alternativas. Assinale-a.","options":{"A":"A principal indicação de seu uso é em pacientes com bradicardia sintomática.","B":"A vantagem do MPTC é a necessidade de baixa energia em razão da necessidade de fazer a\nenergia aplicada chegar ao miocárdio.","C":"Pode também ser utilizado na superestimação para supressão de taquicardias refratárias com o\nintuito de eliminar taquicardia supraventricular (TSV) e taquicardias ventriculares (TV) malignas.","D":"O aumento das placas de eletrodos para oito ou dez centímetros de diâmetro minimizam a\ndensidade de corrente elétrica, além da melhor condução."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157460","number":"157460","sourceNumber":"157460","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O Marca-Passo Transcutâneo (MPTC), é um procedimento de emergência que tem a\nvantagem de ser uma técnica não invasiva e de instalação praticamente imediata. Mas, como por\ndefinição, é utilizado através da parede torácica, apresentando diversas interferências em seu uso\ne indicação, NÃO sendo uma delas o contido em uma das opções. Aponte-a.","options":{"A":"A impedância transtorácica consiste na resistência da parede torácica ao fluxo da corrente\nelétrica e pode também ser influenciada pelo tamanho dos eletrodos.","B":"O aumento das placas de eletrodos para oito ou dez centímetros de diâmetro minimizam a\ndensidade de corrente elétrica, além da melhor condução.","C":"Pode também ser utilizado na superestimulação para supressão de taquicardias refratárias.","D":"O MPTC é um dispositivo que, em geral, não causa desconforto e dor ao paciente, visto que\ncorrentes elétricas de 50 a 100 miliampéres (mA) são necessárias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-160550","number":"160550","sourceNumber":"160550","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 52 anos é admitido com história de náuseas, vômitos e desconforto torácico.\nA triagem encaminha o paciente rapidamente para\na sala de emergência para monitorização, pois\ndetectou FC = 160 bpm e PA = 80/50 mmHg. O ECG realizado é mostrado a seguir (conforme\nimagem do caderno de questões). A conduta imediata mais apropriada é:","options":{"A":"Realizar cardioversão elétrica sincronizada com 100 joules.","B":"Realizar desfibrilação com 200 joules.","C":"Prescrever amiodarona endovenosa.","D":"Prescrever diltiazem endovenoso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157464","number":"157464","sourceNumber":"157464","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante o seu último plantão, ocorreu um caso de parada cardíaca que não se\nconseguia acesso a drogas, e um membro da equipe pediu para deixar de realizar a RCP por\nalguns instantes para se obter uma via central. Entretanto, podemos considerar que durante a\nparada cardíaca, a prioridade sempre será administrar RCP de boa qualidade e desfibrilação\nimediata; a administração de drogas será secundária. Depois da tentativa de desfibrilação, os\nsocorristas devem estabelecer um acesso para a medicação. A respeito disso, assinale a\nalternativa INCORRETA:","options":{"A":"Deve-se escolher, de preferência, o acesso venoso periférico nos membros superiores (veia\nantecubital). O acesso periférico é de fácil obtenção, fácil aprendizado, apresenta menor risco de\ncomplicações e não necessita de interrupção das manobras de RCP.","B":"Se não for possível estabelecer acesso IV, a via intraóssea (IO), para administração de drogas,\npode proporcionar concentrações plasmáticas\nadequadas, similares às alcançadas pelo acesso\nintravenoso.","C":"A administração de medicamentos por um acesso central pode ser considerada se não houver\nnenhuma contraindicação. Essa via de administração\nde medicamentos oferece a vantagem de\nviabilizar maior concentração plasmática apesar de um maior tempo para circulação, além de\npermitir a determinação da saturação venosa central e estimar a pressão de perfusão coronariana\ndurante a RCP.","D":"Estudos relatam que drogas como lidocaína, adrenalina, atropina e naloxone podem ser\nabsorvidas por via endotraqueal. A\nadministração dessas drogas pela via endotraqueal, durante a\nRCP, resulta em menores concentrações plasmáticas quando comparadas com as mesmas doses\nadministradas por via IV."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157454","number":"157454","sourceNumber":"157454","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Das condutas frente à parada cardíaca, as intervenções medicamentosas têm sido\nindicadas no manuseio da PCR desde longa\ndata, porém ocorrem muitas controvérsias, e\ndificuldades de indicações mudam constantemente, sendo o uso de Bicarbonato de Sódio uma das\ncondutas mais controversas, mas podemos admitir:","options":{"A":"Que o melhor tratamento da acidose na PCR é a compressão torácica adequada, além disso,\nnão ocorre benefício ganho com a ventilação.","B":"Que o uso de bicarbonato pode ter alguns efeitos benéficos, tais como aumento na geração de\nCO2.","C":"Bicarbonato de sódio exacerbando a acidose intracelular; efeito inotrópico negativo no miocárdio\nisquêmico.","D":"Bicarbonato de sódio, aumento da osmolaridade sérica e desvio da curva de dissociação da\nhemoglobina para a direita."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-149168","number":"149168","sourceNumber":"149168","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Idosa, 67 anos de idade, foi trazida por familiares ao hospital, desacordada. Logo na\nsua chegada, o caso foi reconhecido como de\nparada cardíaca, provavelmente decorrente de\nataque cardíaco em que ela se queixou de fortes dores no tórax logo quando iniciou o mal-estar,\nantes que perdesse a consciência. Foi iniciado manobras, com uso do CAB, dando grande ênfase\nnas compressões torácicas que foram vigorosas, com profundidade, a uma frequência, em média,\nde 145 por minuto. Sobre essa situação clínica, pode-se afirmar que:","options":{"A":"Essa frequência foi abaixo do necessário.","B":"A conduta foi inadequada, por comprometer a profundidade das compressões.","C":"Melhora fortemente as chances de se obter sucesso na RCP conforme o protocolo atual de\nfrequência.","D":"Somente foi possível graças ao grande treinamento técnico da equipe, que se atualizou sobre o\ntratamento adequado a PCR."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157458","number":"157458","sourceNumber":"157458","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Das medicações utilizadas em emergência, a atropina foi uma das que mais perdeu\nindicações e apresenta controvérsias. A respeito dela, marque a opção considerada INCORRETA:","options":{"A":"A atropina é agonista da ação da acetilcolina, um neurotransmissor parassimpático nos\nreceptores muscarínicos.","B":"Atropina bloqueia o efeito do nervo vago, tanto no nó sinoatrial (NSA) como no nó\natrioventricular (NAV).","C":"Atropina aumenta a frequência de disparos do nó SA.","D":"Atropina facilitando a condução atrioventricular."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-149173","number":"149173","sourceNumber":"149173","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Podemos considerar como boas práticas, durante as manobras de reanimação\ncardiorrespiratória, diversos itens como, por\nexemplo, frequência respiratória e massagem cardíaca,\ncom EXCEÇÃO do contido em uma das opções a seguir. Assinale-o.","options":{"A":"Permitir o retorno do tórax à sua posição sempre.","B":"Comprimir o tórax minimamente 6 cm.","C":"Realizar a compressão entre 100 e 120 por minuto.","D":"Minimizar as interrupções torácicas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157379","number":"157379","sourceNumber":"157379","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, sabidamente cardiopata, foi ao hospital trazido por familiares, que o\nconsideraram prostado nesta manhã. Foi deixado\nna sala de emergência e monitorizado, seu\neletrocardiograma demonstrava uma baixa frequência cardíaca. Foi, então, solicitado avaliação da\ncardiologia e o colega o solicitou para discutir e decidir sobre as condutas, inadequadamente\nfundamentada na seguinte alternativa. Indique-a.","options":{"A":"Os sinais e sintomas, mesmo leves, e os pacientes assintomáticos necessitam de tratamento.\n\nOs pacientes devem ser monitorados à procura dos sinais de deterioração das condições. Deve-se\nfornecer terapia imediata antes que os\npacientes\n\ntenham hipotensão, convulsões e outros sinais de choque relacionados à bradicardia.","B":"A bradicardia é definida como uma frequência cardíaca inferior a 60 bpm; quando a bradicardia é\na causa de sintomas, a frequência geralmente\né menor que 50 bpm. Este limite é individual e\nfrequências menores do que essas podem ser\n\nconsideradas fisiológicas para alguns pacientes e inadequadas para outros.","C":"As causas podem ser: não cardíacas, como uso de drogas; causas metabólicas ou endócrinas,\nespecialmente na tireoide; distúrbio eletrolítico, fatores neurológicos e reflexos autonômicos;\nfatores\nsituacionais, como o repouso prolongado no leito; e autoimunidade. As causas de origem cardíaca\nincluem a doença cardíaca isquêmica aguda ou crônica, doença cardíaca vascular, doença\ncardíaca valvular, ou doença degenerativa primária elétrica.","D":"Os pacientes assintomáticos não devem receber nenhum tratamento. O tratamento é indicado\nsomente nos casos em que a bradicardia, independente do seu tipo ou causa, provoca uma\nredução significativa da pressão arterial sistêmica com sinais clínicos de baixo débito cardíaco."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-149179","number":"149179","sourceNumber":"149179","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante as manobras de reanimação cardiotorácicas, devemos nos atentar a diversos\nfatores, como a frequência das compressões e\na qualidade delas. Além de uma frequência de 100\naté 120 bpm e uma profundidade de 5 a 6 cm, podemos, também, considerar que:","options":{"A":"Se apoiar sobre o tórax, entre as compressões, melhora e promove otimização da pressão\ntorácica.","B":"Aumenta em muito o achado de lesões fatais e promove o apoio do socorrista no tórax entre as\ncompressões.","C":"A pressão intratorácica negativa relativa melhora o fluxo cardiopulmonar.","D":"O retorno intratorácico parcial não causa mudança de fluxo circulatório."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157392","number":"157392","sourceNumber":"157392","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"As arritmias cardíacas apresentam importante conhecimento médico, sendo que\napenas uma das alternativas abaixo se apresenta\ncomo ADEQUADA para o correto entendimento\ndo Bloqueio Atrioventricular de primeiro grau. Assinale-a.","options":{"A":"Caracteriza-se pela aceleração na chegada do estímulo aos ventrículos. A relação\natrioventricular permanece 1:1, uma onda P para um\ncomplexo QRS. O intervalo PR é fixo, mas\nnão varia, medindo mais de 0,20 segundos, ou 200 milissegundos.","B":"A maioria localiza-se no nó sinusal e casionalmente nos átrios, raramente sendo infranodal.","C":"As síndromes coronárias agudas envolvendo a artéria coronária direita podem afetar a\ncirculação para o nó AV, levando à isquemia do nó AV e retardando a condução.","D":"Agentes que atuam no NAV, como betabloqueadores, digitálicos, bloqueadores dos canais de\ncálcio e outros, podem acelerar o intervalo PR."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157416","number":"157416","sourceNumber":"157416","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Do ponto de vista eletrocardiográfico, os Bloqueios Atrioventriculares (BAV) podem ser\ndivididos de acordo com a gravidade. Referente aos chamados BAV do segundo grau, aponte a\nalternativa INCORRETA:","options":{"A":"No BAV de segundo grau, ocorre a interrupção na condução do estímulo para os ventrículos,\nalterando a relação P: QRS usual, que é de\n1:1.","B":"Bloqueio atrioventricular de segundo grau tipo I ? Mobitz I ou Wenckebach\nEletrocardiograficamente, caracteriza-se pelo\naumento progressivo do intervalo PR, acarretando em\numa onda P ?bloqueada?, ou isolada, gerando uma pausa no traçado. Sua totalidade se origina na\nregião infranodal.","C":"No ECG, surgem ondas P isoladas, ditas \"bloqueadas?, porque aparecem isoladas, sem o\ncomplexo QRS correspondente.","D":"O digital, por sua ação vago mimética e sua ação indireta no nó AV, também pode causar esse\ntipo de alteração. É necessária a atenção para a associação desses fármacos, principalmente nos\npacientes idosos, em função da ação sinérgica sobre o nó atrioventricular."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-149204","number":"149204","sourceNumber":"149204","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Diversos são os fatores listados como adequados ou mesmo prejudiciais às condutas\nde reanimação cardiorrespiratória. Assim, podemos\nadequar as nossas condutas ao melhor\npossível em termos de sobrevivência da vítima. Dentre as afirmações a seguir, indique aquela que\nNÃO se enquadra nesse conceito.","options":{"A":"Apresenta grande importância o achado de lesões fatais, ocorridas quando da profundidade de\nmassagem cardíaca acima de 6 cm.","B":"Manter uma frequência de compressões torácicas adequadas aumenta o percentual de\nmassagem efetivamente eficiente.","C":"Permitir fluxo sanguíneo torácico com a massagem cardíaca adequada melhora as chances de\nsucesso.","D":"Hiperventilação se mostra prejudicial durante as manobras de reanimação."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157426","number":"157426","sourceNumber":"157426","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre os estudos eletrocardiográficos do dito bloqueio atrioventricular de segundo grau\ntipo I ? Mobitz I ou Wenckebach, marque a alternativa CORRETA:","options":{"A":"Eletrocardiograficamente, caracteriza-se pelo aumento fixo do intervalo PR, acarretando em uma\nonda P ?bloqueada?, ou isolada, gerando\numa pausa no traçado. Em torno de 85 a 90% desses\nbloqueios localizam-se no nó AV, sendo o restante infranodal.","B":"Ocorrem nas situações em que há redução importante do tônus vagal, como no atleta\n\nbem-condicionado, nas crianças e durante o repouso. Nestes casos, observa-se desaparecimento\ndo bloqueio durante o exercício, quando o tônus\nsimpático é aumentado e o vagal é diminuído.","C":"Os fármacos que atuam no NAV como os betabloqueadores, os bloqueadores dos canais de\ncálcio, os agentes da classe III, como a amiodarona, e os da classe IC, como a propafenona,\nreduzem a velocidade de condução do NAV, causando BAV do segundo grau tipo I.","D":"A pausa caracteriza-se por ser menor que dois ciclos básicos menores, e o PR pós-pausa é\nsempre igual ou menor que o intervalo PR do início de cada sequência. Sequências variadas\npodem ocorrer como 3:2, 4:3, 5:4, significando que há sempre um complexo QRS a menos, uma\nvez que sempre existe uma onda P bloqueada, sem o QRS correspondente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-149210","number":"149210","sourceNumber":"149210","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quando avaliamos o tratamento de taquiarritmias, diversos fatores inerentes às\nalternativas medicamentosas, bem como ao caso clínico,\ndevem ser consideradas quanto à tomada\nda decisão. Dessa maneira, podemos considerar como fatores importantes nesse contexto,\nespecificamente da Fibrilação Atrial, os listados abaixo, com EXCEÇÃO:","options":{"A":"Da apneia obstrutiva do sono.","B":"Da obesidade.","C":"Do uso de bebidas alcoólicas.","D":"Do uso de anti-inflamatórios."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157442","number":"157442","sourceNumber":"157442","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante o último plantão de interno no hospital, você foi chamado em caráter de\nemergência na sala de recuperação anestésica, por complicação cardíaca no pós-operatório\nimediato de cardiopata que fez laparotomia exploradora de emergência. Tanto o monitor cardíaco\nquanto o ECG demonstrava um padrão de bloqueio do segundo grau avançado. Sobre o caso,\naponte a alternativa que é considerada INADEQUADA:","options":{"A":"O BAV avançado do segundo grau é classificado como do tipo 2:1 e 3:1 etc., ou seja, para cada\ncomplexo QRS, existem duas ou três ondas P, respectivamente. Isso significa que não há\nintervalos PR consecutivos para serem comparados, ou seja, não é possível avaliar se o intervalo\nPR mantém-se constante ou prolonga-se antes de surgir a onda P bloqueada.","B":"Cerca de dois terços dos BAV avançados são localizados abaixo do NAV, no sistema\n\nHis-Purkinje, de onde talvez se origine a concepção equivocada de classificá-los como BAV tipo II.","C":"Nos casos em que está associado a complexos QRS finos, que são a maioria, está localizado no\nsistema His-Purkinje.","D":"O BAV avançado pode ser assintomático ou sintomático, apresentando-se sob a forma de\ntontura, pré-síncope ou mesmo episódios sincopais\nintermitentes. Em geral, é secundário à lesão\nanatômica bem-definida do sistema de condução, como na cardiopatia isquêmica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-149221","number":"149221","sourceNumber":"149221","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Além de aspectos cardiológicos com importantes complicações, a Fibrilação Atrial\ncausa enormes outras complicações à distância,\nentre elas os fenômenos emboligênicos. Sobre\nisso, concluímos que:","options":{"A":"O escore de risco para hemorragia não contraindica o uso de anticoagulante oral, mas orienta\nquanto à necessidade de cuidados especiais para tornar o tratamento mais seguro.","B":"Não ocorre risco de interação de anticoagulação e consumo de álcool.","C":"Não há necessidade de avaliar, concomitantemente, risco emboligênico e de sangramento.","D":"O conceito ?benefício líquido? não leva em consideração os aspectos positivos da redução de\nrisco de tromboembolismo bem como de hemorragia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157446","number":"157446","sourceNumber":"157446","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre as bradiarritimias, assinale a alternativa CORRETA:","options":{"A":"Todo BAVT significa dissociação atrioventricular, mas nem toda dissociação AV significa BAVT.","B":"Nos casos de BAVT, a frequência atrial é sempre menor que a ventricular.","C":"A frequência atrial pode ser somente o de ritmo sinusal, no achado de bloqueio atrioventricular\ntotal.","D":"Na ECG, observam-se ondas P bloqueadas, dissociadas do complexo QRS, que pode ser\nsomente alargado com padrão de bloqueio de ramo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-149232","number":"149232","sourceNumber":"149232","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quando avaliamos o tratamento da Fibrilação Atrial, devemos considerar, quanto ao\ntratamento proposto, o seguinte, com EXCEÇÃO de uma das alternativas a seguir. Indique-a.","options":{"A":"O uso de carvedilol associado à digoxina não auxiliou no controle da frequência, bem como na\nmelhora da função ventricular de pacientes portadores de IC.","B":"Os bloqueadores de canais de cálcio não diidropiridínicos, como o verapamil e o diltiazem,\nbloqueiam os canais de cálcio do tipo L do\nsistema de condução cardíaco, principalmente no nó\nAV.","C":"O verapamil e o diltiazem podem ser utilizados em associação com outro fármaco (digital, por\nexemplo), podendo permitir doses menores com consequente melhor tolerância.","D":"O uso intravenoso de esmolol, propranolol e metoprolol foi efetivo em casos de FA aguda."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157452","number":"157452","sourceNumber":"157452","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em termos de conduta de emergência, no caso do encontro das taquiarritmias, assinale\na alternativa INCORRETA:","options":{"A":"Pode-se, de um ponto de vista prático, classificar inicialmente as taquicardias em dois grupos,\nindependente do diagnóstico eletrocardiográfico: instáveis e estáveis.","B":"As taquiarritmias instáveis são aquelas que apresentam frequência cardíaca geralmente superior\na 150 bpm (caso não haja disfunção\nventricular acentuada).","C":"Independente do diagnóstico eletrocardiográfico, a cardioversão elétrica sincronizada deve ser\nprontamente instituída de modo a restaurar um ritmo cardíaco organizado e com frequência menor\ncapaz de produzir débito cardíaco mais efetivo.","D":"Do ponto de vista de atendimento emergencial, podemos dividi-las em dois tipos, de acordo com\na duração do complexo QRS: QRS estreito (< 140\nms) e QRS largo (=140 ms)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157466","number":"157466","sourceNumber":"157466","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O Bloqueio Atrioventricular Total adquirido no nosso meio é mais comumente causado\npor cardiopatia chagásica, além de doença\nisquêmica, cardiopatia dilatada, pós-cirurgia cardíaca,\ncausa degenerativa, entre outros. O nível do bloqueio é baixo, frequentemente infranodal, e o foco\nde escape, às vezes, fornece frequência muito baixa, como 15 a 20 bpm, configurando quadro de\nemergência, NÃO relacionado a uma das opções apresentadas a seguir. Indique-a.","options":{"A":"A sintomatologia vai depender da frequência ventricular. Com a interrupção do fluxo sanguíneo\npara o cérebro, o indivíduo pode apresentar\ntontura, vertigem, pré-síncope e síncope.","B":"A síncope do BAVT é conhecida como ataque de Stokes-Adams, em homenagem aos dois\ncientistas que a descreveram. A síncope\ncardiológica provoca a perda total dos sentidos por curto\nperíodo de tempo, sem aviso prévio, acarretando, frequentemente, lesão corporal, e o paciente\nrecupera-se imediatamente, sem ter noção do que aconteceu.","C":"Podem ser assintomáticos. Com frequência, o BAVT congênito só causa repercussão clínica na\nadolescência ou no adulto jovem.","D":"Os estímulos gerados na região supraventricular não são todos bloqueados, causando uma\ndissociação atrioventricular parcial de modo que os átrios tenham sua frequência própria, sendo\nsinusal ou não."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157471","number":"157471","sourceNumber":"157471","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Você foi chamado a explicar a um amigo de outra especialidade o porquê de o paciente\ndele ser considerado como de alto risco para\na cirurgia e, assim, indicado pós-operatório de UTI.\nIsso ocorreu devido a um lado de ECG que indicou internação imediata não para a cirurgia, e sim\npara a cardiologia. No laudo, estava escrito Bloqueio Atrioventricular Total (BAVT). A respeito\ndessa\nsituação, aponte a alternativa considerada INADEQUADA:","options":{"A":"O BAVT ou BAV de terceiro grau é a interrupção completa do estímulo de condução para os\nventrículos. Os estímulos gerados na região supraventricular são todos bloqueados, causando uma\ndissociação atrioventricular completa de modo que os átrios tenham sua frequência própria, sendo\nsinusal ou não, e completamente independente da frequência ventricular.","B":"Quando os ventrículos ficam privados de sua fonte estimuladora, tornam-se dependentes de\noutro grupo de células, que assume a função\nde marca-passo, sendo chamado de foco de escape.\nA frequência ventricular é completamente dissociada da atrial e depende exclusivamente da\ncapacidade cronotrópica do foco de escape.","C":"À medida que se aproximam do nó sinusal em direção aos ventrículos, as células especializadas\napresentam frequências de despolarização cada vez menores.","D":"As células do sistema His-Purkinje, como o próprio feixe, têm frequência em torno de 35 bpm, e\nos ramos do feixe de His, de 25 a 30 bpm.\nLogo, quanto mais baixo for o bloqueio, menos confiável\ne mais instável será o foco de escape, além de apresentar frequências baixas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157474","number":"157474","sourceNumber":"157474","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Recentemente um tio de seu colega de clube apresentou uma palpitação e teve muito\nmal-estar. Como você era o único médico que ele conhecia, pediu para convencer o tio de que\ndevia ir a um cardiologista. Sobre esse caso, você o orientou ADEQUADAMENTE, conforme uma\ndas alternativas apresentadas. Assinale-a.","options":{"A":"A menos que disfunção ventricular importante esteja presente, é consenso entre os especialistas\nque somente ritmos acima de 120 batimentos por\nminuto causam sintomas de comprometimento\nhemodinâmico.","B":"Nos pacientes sintomáticos, há que se estabelecerem dois aspectos fundamentais. O primeiro\ndiz respeito à intensidade dos sintomas. Assim,\npacientes sintomáticos podem apresentar sintomas\ndesconfortáveis, como palpitações, tontura e/ou dispneia leve, mas não apresentar qualquer sinal\nclínico de comprometimento hemodinâmico.","C":"Um aspecto fundamental é o estabelecimento de uma relação causal entre a presença das\ntaquiarritmias e os sintomas. Em que pese o fato de existir comprometimento hemodinâmico que\nnecessite de tratamento imediato, sempre é possível estabelecer uma relação direta para o\ntratamento.","D":"Em indivíduos assintomáticos, uma ampla gama de taquiarritmias pode ser identificada e sempre\nvão necessitar de tratamento específico\nimediato, já que não determinam alterações clínicas, mas\npodem degenerar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-149261","number":"149261","sourceNumber":"149261","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O exame de eletrocardiograma pode ser capaz de determinar suspeitas e diagnósticos\nde diversas doenças, tanto cardíacas como à\ndistância, NÃO sendo listado, entre estas capazes de\nalterar o ECG:","options":{"A":"Hipotermia.","B":"Hipertensão intracraniana.","C":"Glaucoma.","D":"Obesidade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157467","number":"157467","sourceNumber":"157467","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"As taquicardias de QRS estreito podem, para melhor raciocínio terapêutico, também ser\npossível dividi-las de acordo com a dependência do nó AV para seu início e manutenção. Assim,\ntemos as taquicardias em que o circuito da arritmia utiliza o nó, muitas das vezes sendo indicada\nterapêutica farmacológica. Dessa forma, aponte a alternativa INCORRETA:","options":{"A":"Adenosina é uma droga que diminui a condução pelo NAV e que promove vasoconstricção\ncoronária.","B":"Possui meia-vida de menos de 5 a 10 segundos, tendo assim efeito fugaz, porém efetivo no\ntérmino da maioria das taquicardias de QRS estreito.","C":"Efeitos colaterais podem ocorrer em até 60% dos casos.","D":"É importante orientar previamente o paciente que poderá apresentar pressão torácica importante\ncom sensação de ?morte? iminente, porém tais\nefeitos são transitórios."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-157470","number":"157470","sourceNumber":"157470","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A respeito do tratamento de emergência de taquiarritmias, marque a alternativa\nINCORRETA:","options":{"A":"Drogas antiarrítmicas têm potencial pró-arrítmico e causam hipotensão arterial e bradicardias\napós reversão de uma arritmia, quando vários\nantiarrítmicos são utilizados em sequência.","B":"Com exceção da adenosina, não se recomenda a administração sucessiva de várias drogas\nantiarrítmicas sequenciais.","C":"Após a adequada utilização de uma droga até sua dose máxima, se não houver reversão da\narritmia ou comprometimento hemodinâmico, o paciente deve ser considerado como ?instável? e a\ndesfibrilação elétrica deve ser realizada.","D":"Para pacientes com disfunção ventricular sistólica, a amiodarona e a digoxina são as drogas\nmais utilizadas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-149216","number":"149216","sourceNumber":"149216","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Dentre as seguintes complicações do afogamento, assinale a mais CORRETA.","options":{"A":"A pneumonia ocorre em 100% dos casos e necessita de tratamento imediato à chegada do\npaciente na emergência.","B":"O vômito é a complicação mais frequente no período pré-hospitalar.","C":"Nas primeiras 48 horas, a febre e a leucocitose representam infecção.","D":"A lesão pulmonar do afogamento pode ser reduzida com o uso de corticoide iniciado nas\nprimeiras 48 horas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-127102","number":"127102","sourceNumber":"127102","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um menino branco, de 9 anos, começou a apresentar dor e aumento de volume do\njoelho direito há 2 meses. Recebeu\nanti-inflamatório não hormonal por 7 dias, sem melhora. A\nclaudicação e as dores são piores pela manhã. Nega antecedentes de infecção ou outros sintomas\nassociados. Na história familiar, refere que o pai tem espondilite anquilosante. Ao exame físico,\napresenta claudicação intensa. O joelho direito revela aumento de volume e é mantido em\nsemiflexão, e o joelho esquerdo, dor no bordo patelar (posição de 2 a 10 horas) e dor à\ndigitopressão da tuberosidade anterior da tíbia. Constata-se ainda, leve aumento de volume e dor\nà digitopressão da inserção do tendão do calcâneo à esquerda. E mais: hemoglobina = 12g/dL,\n12.800 leucócitos/mm³ (60 neutrófilos e 29 linfócitos), 500.000 plaquetas/mm³, VHS = 70mm/1ª\nhora , proteína C reativa = 5,4mg/dL (referência = 0.5mg/dL) e fator reumatoide negativo. A\nultrassonografia mostra moderada quantidade de liquido distendendo a bursa suprapatelar do\njoelho direito, associada a espessamento da sinóvia. Com PPD negativo e HLA-B27 positivo, a\nbiopsia sinovial revela infiltrado inflamatório mononuclear, compatível com\n\nsinovite crônica inespecífica. O tipo de manifestação ocular que pode ocorrer em pacientes como\nesse é:","options":{"A":"Catarata subcapsular.","B":"Síndrome de Sjögren.","C":"Doença de Eales.","D":"Doença ocular isquêmica.","E":"Uveíte anterior aguda."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-127105","number":"127105","sourceNumber":"127105","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma pré-escolar de 2 anos vem ao ambulatório com história de 9 semanas de aumento\nde volume em joelhos, punho direito e\ntornozelo esquerdo. Ao exame físico, apresenta artrite nas\narticulações referidas. O hemograma, bioquímica e urina l foram normais, com exceção da VHS\n(50), ASLO (400U Todd) e FAN (1/160 com padrão homogêneo). Qual é o diagnóstico?","options":{"A":"Lúpus eritematoso sistêmico.","B":"Artrite reumatoide juvenil forma poliarticular.","C":"Febre reumática.","D":"Artrite reumatoide juvenil forma pauciarticular.","E":"Artrite reacional."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-127973","number":"127973","sourceNumber":"127973","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com relação ao tratamento da Artrite Reumatóide (AR), conforme as recomendações\ndo Consenso 2012 da Sociedade Brasileira de\nReumatologia, Assinale a alternativa correta:","options":{"A":"O metotrexato é a medicação padrão no tratamento da AR porque reduz sinais, sintomas e\nprogressão das lesões radiográficas.","B":"Os antimaláricos têm, como principal efeito colateral, o risco de glaucoma e tem ação na\nprogressão radiológica da doença.","C":"Corticoesteróides são indicados na AR para controle da inflamação e da dor, em doses\nsuperiores a 15 mg ao dia de prednisona.","D":"Nas gestantes, todas as drogas modificadoras do curso da doença devem ser suspensas, pois\nnenhuma delas pode ser usadas nessas ocasiões."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-127975","number":"127975","sourceNumber":"127975","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A manifestação extra-articular mais comum de espondilite anquilosante é a:","options":{"A":"Fibrose pulmonar.","B":"Uveíte anterior.","C":"Amiloidose.","D":"Conjuntivite."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-127979","number":"127979","sourceNumber":"127979","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A síndrome de Reiter tem como característica mais comum, exceto:","options":{"A":"Presença de úlceras orais e uretrite.","B":"Marcante melhora depois de 24 a 48 horas da administração de antibióticos.","C":"Em geral, se segue-se a disenteria por Shiguella ou outras bactérias.","D":"A artrite com frequência envolve as grandes articulações de carga (joelho e tornozelo,\nprincipalmente)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-127360","number":"127360","sourceNumber":"127360","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Quando das manobras de reanimação, seguindo o protocolo do CAB, a hiperventilação\ncom AMBU pode ocorrer, caso esta ultrapasse a\nfrequência de 10 por minutos. Qual é a POSSÍVEL\nconsequência dessa manobra?","options":{"A":"Melhora com hiperoxia.","B":"Aumento da pressão sistólica.","C":"Dificuldade de retorno venoso.","D":"Piora da hipercapnia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-127698","number":"127698","sourceNumber":"127698","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Homem de 48 anos, com profissão de caminhoneiro, vem ao pronto-socorro com\nqueixas de dor intensa, edema, rubor e calor\nna primeira metatarsofalangeana direita, que teve\ninício há doze horas. É diabético, hipertenso, etilista, obeso, sedentário e faz uso irregular das\nmedicações prescritas. Ao exame físico, observa-se artrite da primeira metatarsofalangeana direita.\nO médico plantonista prescreveu anti-inflamatório não hormonal e colchicina. Nesse caso,","options":{"A":"O diagnóstico pode ser feito com o achado de cristais de oxalato de cálcio no líquido sinovial.","B":"O uso da colchicina deve ser reservado para as crises de artrite e evitado durante o período\nintercrítico.","C":"A doença articular está dissociada dos hábitos de vida relatados pelo paciente.","D":"A efetividade do tratamento depende da redução da concentração de urato sérico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-138253","number":"138253","sourceNumber":"138253","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Considerando o Consenso Brasileiro para tratamento da artrite reumatoide,","options":{"A":"o uso de anti-TNFs está limitado à presença de falha de drogas modificadoras do curso de\ndoença (DMARDs) imunobiológicas.","B":"o uso de ICAD (indicadores clínicos de atividade de doença) está restrito ao ambiente de\npesquisa clínica.","C":"os pacientes com artrite reumatoide têm risco aumentado para TB (tuberculose) ativa e,\nportanto, devem receber quimioprofilaxia para esta doença.","D":"o rastreamento de tuberculose é recomendado para o uso de agentes imunobiológicos e,\nquando indicado, tratamento de TBIL (tuberculose infecção latente)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-138258","number":"138258","sourceNumber":"138258","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"J.B.S., de 45 anos, do sexo feminino, foi atendida em ambulatório de clínica médica\ncom relato de que, há oito anos, apresenta\ndor na região plantar dos calcanhares e que, após ter\nsido submetida à avaliação médica, recebeu o diagnóstico de reumatismo e que lhe haviam sido\nprescritos medicamentos cujos nomes não se recorda. Nesse intervalo de tempo, passou a\napresentar dor e alterações nos punhos, que a impossibilitam de fechar as mãos e também dor e\nvermelhidão nos joelhos e tornozelos. Apresentou, também, rigidez matinal, com duração de três\nhoras, por vários meses. Negou possuir outras doenças e informou que sua mãe apresentava\nproblema de reumatismo. Ao exame físico, observaram-se diminiução da flexão dos punhos\n(bilateralmente), dor nas articulações metacarpofalangianas (bilateralmente), presença de discreto\nderrame articular nos joelhos e dor à palpação das articulações metacarpofalangianas e dos\ncalcanhares. O restante do exame não apresentou alterações. Exames complementares realizados\nmostraram fator reumatoide (teste do látex) positivo, níveis elevados de proteína C reativa e\naceleração da velocidade de hemossedimentação. Radiografias das mãos e dos pés mostraram\nestreitamento dos espaços articulares e lesões ósseas erosivas. Com base nestas informações\nclínico-laboratoriais, o principal diagnóstico para a paciente é:","options":{"A":"lúpus eritematoso sistêmico.","B":"artrite reumatoide.","C":"espondilite anquilosante.","D":"doença de Behçet."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-127262","number":"127262","sourceNumber":"127262","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Indique os antiarrítmicos contidos em uma das alternativas, que estão correlacionados\ncom modulação dos canais de sódio para seu efeito:","options":{"A":"Lidocaína e propafenona.","B":"Amiodarona e metoprolol.","C":"Diltiazem e verapamil.","D":"Deslanosídeo e esmolol."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-109200","number":"109200","sourceNumber":"109200","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Menino de três anos apresenta há dois meses história de febre alta vespertina e\nexantema macular em tronco, artrite de joelhos\ne punho direito. Ao exame, além de artrite,\nencontra-se com linfonodomegalia generalizada e hepatoesplenomegalia. Os exames\ncomplementares mostram hemoglobina: 9,0 g/dl; hematócrito: 27% e 20.000 leuc/mm³; VHS = 95\nmm na primeira hora. A radiografia de tórax revela aumento da área cardíaca. O diagnóstico mais\nprovável é:","options":{"A":"Febre reumática.","B":"Doença de Kawasaki.","C":"Artrite idiopática juvenil.","D":"Leucemia linfoblástica aguda."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-110252","number":"110252","sourceNumber":"110252","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"João Antônio, 6 anos de idade, foi conduzido à UBS por estar apresentando, há 4\nmeses, alteração de comportamento, com\nirritabilidade e choro fácil. Segundo a mãe do menor, há\num mês vem observando também movimentos desordenados dos braços e pernas, principalmente\nquando ocorre algum estímulo, levando a quedas frequentes. Nega presença dos movimentos\ndurante o sono. No início, achou que a criança estava \"fazendo manha\", pois os sintomas iniciaram\nlogo após a viagem da avó do menor. Mas, como tem persistido, ficou preocupada e resolveu\nprocurar o serviço médico. Nega presença de qualquer outro sintoma. Quando perguntada sobre os\nantecedentes pessoais fisiológicos e patológicos da criança, a mãe referiu que o menor nasceu de\nparto normal, hospitalar, sem intercorrências, com desenvolvimento neuropsicomotor adequado\npara a idade, sendo internado duas vezes com diarreia e vômito (com 2 e 4 anos de idade). Há 7\nmeses a criança teve um episódio de gripe e há 6 meses, amigdalite. No exame físico geral, o\nmédico anotou os seguintes achados: BEG, ativo, eupneico, normocárdico, anictérico, acianótico,\nhidratado, consciente e orientado. Presença de movimentos involuntários rápidos, arrítmicos e\nincoordenados de membros superiores e inferiores. De acordo com o diagnóstico e com os dados\nclínicos de João Antônio, qual dos esquemas de tratamento a seguir é mais adequado a este\npaciente?","options":{"A":"Ácido valproico e prednisona.","B":"Haloperidol e diurético.","C":"Ácido acetilsalicílico e metilprednisolona.","D":"Indometacina e digitálico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-109195","number":"109195","sourceNumber":"109195","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma criança de 3 anos de idade apresentou febre de 39°C que surgiu a dois dias e\ndesde ontem passou a apresentar dor e\nimpossibilidade de movimentar o membro inferior direito. O\nexame físico mostrou edema e dor no joelho direito. O exame MAIS IMPORTANTE para confirmar\na hipótese de artrite séptica é:","options":{"A":"Radiografia do joelho.","B":"Hemocultura.","C":"Tomografia computadorizada de joelho.","D":"Exame do líquido articular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-101221","number":"101221","sourceNumber":"101221","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"É um tendão que, por apresentar uma zona hipovascularizada na sua inserção no\ntubérculo maior do úmero, possui maior predisposição para desenvolver a síndrome do impacto.\nTrata-se do tendão:","options":{"A":"supraespinhal.","B":"redondo menor.","C":"infraespinhal.","D":"subescapular."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-109308","number":"109308","sourceNumber":"109308","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A osteoartrite é um problema de saúde pública, frequente em indivíduos após os 60\nanos de idade, que pode acometer as\narticulações centrais (coluna vertebral) e as periféricas. A\nsíndrome de Milwaukee é uma doença degenerativa que acomete a seguinte articulação periférica:","options":{"A":"Temporomandibular.","B":"Coxofemoral.","C":"Cotovelo.","D":"Ombro."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-101238","number":"101238","sourceNumber":"101238","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher de 49 anos procura assistência médica com queixas de dor e edema nas mãos\ne nos punhos, de início há seis meses, que\npiora com o repouso e está associada à rigidez matinal\nde duas horas. Nega outras queixas. Ao exame físico, apresenta artrite nos punhos e em todas as\ninterfalangianas proximais de ambas as mãos. Os exames complementares revelam: VHS = 54\nmm; PCR = 56 mg/dl; hemograma = normal; FAN = negativo; fator reumatoide = negativo;\nsorologias para hepatites virais e HIV = negativas; radiografia das mãos = normal. Nesse caso, a\nconduta é:","options":{"A":"Iniciar, imediatamente, sulfassalazina 2 g/dia.","B":"Solicitar anti-CCP ou ressonância nuclear magnética das mãos.","C":"Iniciar, imediatamente, colchicina 1 mg/dia.","D":"Solicitar HLA-B27 e radiografia das sacroilíacas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-109318","number":"109318","sourceNumber":"109318","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher de 72 anos, assintomática, traz radiografias que mostram calcificações de\npadrão linear na topografia dos meniscos e do\nligamento triangular do punho direito. A principal\nhipótese diagnóstica para essa mulher é:","options":{"A":"Artrite reumatoide.","B":"Condrocalcinose.","C":"Gota.","D":"Artrite psoriásica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-111427","number":"111427","sourceNumber":"111427","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Alice, 09 anos, veio trazida ao pronto-socorro pediátrico após 3 dias com dores\narticulares que melhoravam com analgesia\ncomum. A que assustou a mãe hoje foi o aparecimento\nde \"caroços\" pelo corpo. Não houve febre e o estado geral permanece bom. Dentre os exames\nlaboratoriais, o que se destacou foi o ASLO acima de 1.000U. Você deve:","options":{"A":"Solicitar cultura por esfregaço (SWAB) de secreção das amigdalas.","B":"Iniciar Penicilina cristalina urgentemente.","C":"Solicitar ecocardiograma urgentemente.","D":"Solicitar ultrassom dos nódulos cutâneos urgentemente.","E":"Solicitar à mãe que isole e traga para avaliação médica os irmãos da Alice."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-109160","number":"109160","sourceNumber":"109160","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher, de 24 anos, vem apresentando constantemente parestesias no segundo e\nterceiro quirodáctilos esquerdos que se exarcebam\ncom a flexão do punho. O quadro é compatível\ncom:","options":{"A":"Distrofia muscular e radbomiólise.","B":"Mielodisplasias e cirrose biliar primária.","C":"Fibromialgia e climatério.","D":"Mixedema e gravidez."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-109307","number":"109307","sourceNumber":"109307","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A incidência de febre reumática aguda em alguns países em desenvolvimento é\nsuperior a 50 casos por 100.000 crianças/ano. Nesta doença,","options":{"A":"a válvula aórtica é a mais acometida, seguida pela válvula mitral.","B":"os critérios maiores são: febre, cardite, poliartrite, eritema marginatum e coreia.","C":"a artrite ocorre em cerca de 75% dos casos e envolve predominantemente grandes articulações.","D":"a coreia é o critério maior menos frequente, pois ocorre em 10 a 15% dos casos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-101192","number":"101192","sourceNumber":"101192","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"No diagnóstico da Artrite Idiopática Juvenil (AIJ) sistêmica:","options":{"A":"O comprometimento articular ocorre concomitante às manifestações sistêmicas, podendo ser do\ntipo oligo ou poliarticular.","B":"A febre com duração de, no mínimo, seis semanas é uma condição necessária para o seu\ndiagnóstico.","C":"O exantema evanescente, a hepatomegalia ou esplenomegalia e a serosite são manifestações\nsistêmicas.","D":"Os achados laboratoriais, como alterações nas provas de atividade inflamatória, são a base da\nconfirmação da doença."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-103730","number":"103730","sourceNumber":"103730","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"É causa frequente de dores nos membros em Pediatria:","options":{"A":"a síndrome da hipermobilidade articular.","B":"as dores de crescimento.","C":"a distrofia simpática reflexa.","D":"todas as citadas acima são causas frequentes de dores nos membros."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-85354","number":"85354","sourceNumber":"85354","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação ao diagnóstico da febre reumática, considera-se o seguinte:","options":{"A":"cardite, artralgia e eritema marginato são critérios maiores na classificação de Jones.","B":"coreia isolada e cardite indolente autorizam o diagnóstico de FR, mesmo na ausência de outros\ncritérios de Jones.","C":"PCR e VHS aumentado e presença de poliartrite são critérios menores na classificação de\nJones.","D":"nódulos cutâneos, prolongamento do espaço PR e cardite são critérios maiores na classificação\nde Jones."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-79574","number":"79574","sourceNumber":"79574","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Ao lado da preocupada avó, um rapaz de 17 anos chegou à emergência com história\nde artralgia migratória que durou 3 dias e\nacabou restrita ao joelho direito. Na ectoscopia, além de\nmoderado inchaço articular, notavam-se pequenas pústulas necróticas em solas e palmas que,\nentretanto, não doíam. Em face de evidências indicativas de artrite gonocócica, o residente tentou\ntranquilizá-los, pois sabia que:","options":{"A":"A doença articular torna o indivíduo imune às reinfecções pelo micro-organismo","B":"O período de imobilização gessada da junta é de, no máximo, 2 semanas","C":"A infiltração do joelho com hidrocortisona previne sequelas motoras","D":"A ceftriaxona parenteral tem bons resultados nessa artropatia"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-79576","number":"79576","sourceNumber":"79576","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma menina de 5 anos sofre de edema no joelho direito há 3 meses. Exame físico:\naumento de volume, discreta dor à\nmovimentação do mesmo joelho e atrofia da musculatura\nadjacente da coxa direita. O restante do exame é normal. Diante disso, é CORRETO afirmar que:","options":{"A":"A hipótese diagnóstica mais provável é febre reumática.","B":"A imobilização do joelho direito está indicada.","C":"A criança deve ser encaminhada ao oftalmologista.","D":"A criança tem risco aumentado para desenvolver lesões de válvulas cardíacas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-83847","number":"83847","sourceNumber":"83847","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Febre Reumática tem seu diagnóstico baseado nos:","options":{"A":"Critérios de Apache II.","B":"Critérios de Jones.","C":"Critérios de Gleason.","D":"Critérios de Balthazar.","E":"Critérios de Ranson."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-78146","number":"78146","sourceNumber":"78146","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A hiperuricemia é o principal fator de risco para o desenvolvimento da gota e ocorre\nquando a produção de ácido úrico não é\nequilibrada pela excreção renal. Assim, nessa doença,\nobserva-se que:","options":{"A":"A principal causa de hiperuricemia é uma subexcreção renal, em cerca de 90% dos pacientes.","B":"70% do ácido úrico filtrado no glomérulo é reabsorvido do túbulo contorcido distal renal.","C":"A excreção de urato é aumentada com o uso de drogas, como aspirina em baixas doses,\ntiazídicos e betabloqueadores.","D":"A benzobromarona age sobre o transportador de URAT 1 e aumenta a reabsorção tubular renal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-85337","number":"85337","sourceNumber":"85337","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Idosa, 70 anos, com queixa de dor contínua no quadril esquerdo, principalmente na\nface interna da coxa, que irradia até o\njoelho. Apresenta restrição importante da amplitude dos\nmovimentos do quadril em questão. Feito diagnóstico de coxartrose em estágio avançado Bombelli\nsuperoexterna, que alterações são esperadas no exame de radiografia coxofemoral?","options":{"A":"Esclerose subcondral e aumento do espaço articular.","B":"Cistos subcondrais, luxação do quadril e diminuição do espaço articular.","C":"Aumento do espaço de Müller e osteófitos marginais.","D":"Geodos e diminuição do espaço articular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-90019","number":"90019","sourceNumber":"90019","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre Febre Reumática, podemos afirmar:","options":{"A":"É uma sequela de fase aguda de infecção nas vias aéreas superiores.","B":"São critérios maiores de Jones: artrite e febre.","C":"O AAS é efetivo no impedimento da evolução da cardite reumática.","D":"Os antibióticos não modificam a evolução de uma crise reumática.","E":"Todas as alternativas anteriores estão corretas sobre febre reumática."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-63209","number":"63209","sourceNumber":"63209","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Elisa vem à consulta médica e diz ser portadora de doença de Poncet. Então, você\nsabe que ela tem:","options":{"A":"Poliartrite reativa em portador de tuberculose visceral ou disseminada.","B":"Poliartrite por microbactéria.","C":"Artrite tuberculosa.","D":"Artrite traumática.","E":"Osteomielite tuberculosa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-64575","number":"64575","sourceNumber":"64575","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A dose equivalente, para 5 mg de prednisona é de: HC: hidrocortisona; TC:\ntriancinolona; DX: dexametasona; BM: betametasona; MP: metilprednisolona.","options":{"A":"20 mg de HC; 4 mg de TC; 0,75 mg de DX;","B":"20 mg de HC; 10 mg de MP; 0,9 mg de DX;","C":"100 mg de MP; 1 mg de DX; 20 mg de BM;","D":"10 mg de HC; 4 mg de DX; 5 mg de BM;","E":"50 mg de HC; 4 mg de TC; 5 mg de BM."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-63229","number":"63229","sourceNumber":"63229","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Victória, 3 anos, trazida com história de febre, queda do estado geral e dor em membro\ninferior esquerdo com incapacidade de deambulação há 4 dias. Ao exame: temperatura axilar de\n38,5 °C, dor intensa e impotência funcional em quadril, com atitude em flexão e palpação dolorosa\nde pontos articulares do quadril. O hemograma é infeccioso e a radiografia do quadril é normal.\n\nConsiderando o diagnóstico mais provável, qual das condutas abaixo é a mais apropriada?","options":{"A":"Preescrever antitérmico e antibiótico VO e repetir radiografia após 2 dias.","B":"Solicitar hemocultura e iniciar antibioticoterapia EV por 10 dias.","C":"Realizar punção articular, encaminhar material para cultura e, se esta for positiva, realizar\ndrenagem cirúrgica e antibioticoterapia EV.","D":"Realizar punção articular e, se houver saída de líquido turvo, indicar imediata drenagem\ncirúrgica\ne antibioticoterapia EV.","E":"Antibioticoterapia EV por 72 horas e, caso não haja melhora do quadro clínico ou alteração\nradiográfica, realizar drenagem cirúrgica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-63427","number":"63427","sourceNumber":"63427","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre a artrite reumatoide, podemos afirmar que são critérios de diagnóstico do Colégio\nAmericano de Reumatologia, exceto:","options":{"A":"Rigidez matinal: rigidez articular durando pelo menos uma hora.","B":"Artrite de três ou mais áreas: pelo menos três áreas articulares com edema de partes moles ou\nderrame articular, observado pelo médico.","C":"Artrite assimétrica de articulações das mãos (punho, interfalangianas proximais e\nmetacarpofalangianas).","D":"Nódulo reumatoide.","E":"Alterações radiográficas: erosões ou descalcificações localizadas em radiografias de mãos e\npunhos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-63653","number":"63653","sourceNumber":"63653","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com relação à febre reumática, são considerados critérios menores, segundo os\ncritérios de Jones (modificados em 1992):","options":{"A":"Coreia de Sydenham e poliartrite.","B":"Febre e artralgia.","C":"Poliartrite e nódulos subcutâneos.","D":"Cardite e eritema marginado."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-64561","number":"64561","sourceNumber":"64561","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em quais estruturas ósseas articulares são encontrados os chamados nódulos de\nHeberden?","options":{"A":"Tarsometatársicas.","B":"Intertarsianas.","C":"Metatarsofalangianas.","D":"Interfalangianas distais.","E":"Interfalangianas proximais."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-61757","number":"61757","sourceNumber":"61757","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre a fibromialgia, é correto afirmar:","options":{"A":"É uma síndrome dolorosa crônica, com características inflamatórias e que apresenta aumento de\nprovas de atividade inflamatória como aumento importante do VHS.","B":"Os sintomas mais comuns são mialgia generalizada e poliartrite.","C":"Os níveis séricos de GH (hormônio do crescimento) estão elevados em 90% dos pacientes.","D":"Estudos mostram que existe aumento de substância P no Iiquor de pacientes com fibromialgia.","E":"Apresenta incidência igual entre homens e mulheres."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-47312","number":"47312","sourceNumber":"47312","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A rizartrose geralmente acompanha a:","options":{"A":"osteoartrose de coluna vertebral","B":"osteoartrite nodal das mãos","C":"coxartrose","D":"gonartrite"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-48309","number":"48309","sourceNumber":"48309","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Humberto, 35 anos, apresenta um episódio autolimitado de diarreia, surgindo algumas\nsemanas depois um quadro de poliartrite assimétrica de membros inferiores, dactilite nos\npododáctilos, tendinite do aquileu, lesões superficiais, eritematosas e indolores no pênis.\n\nConstata-se que apresenta também uma sacroileíte assintomática e conjuntivite bilateral. Um\nexame de sangue mostra HLA-B27. O diagnóstico\nprovável deste caso é:","options":{"A":"Doença de Behçet","B":"Síndrome de Reiter","C":"Doença de Whipple","D":"Espondilite anquilosante","E":"Reumatismo palindrômico"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-47318","number":"47318","sourceNumber":"47318","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma menina com 9 anos e história de artrite no punho direito por 3 dias, seguidas de\nartrite no tornozelo esquerdo com duração de 2 dias e artrite no joelho que também durou 2 dias,\napresentou melhora com aspirina e, na avaliação laboratorial, aumento das provas de atividade\ninflamatória. Uma semana depois, apresentou cansaço aos médios esforços. Quais os achados\nmais prováveis à ausculta cardíaca?","options":{"A":"bradicardia e sopro diastólico em foco aórtico","B":"bradicardia e sopro sistólico em foco aórtico","C":"taquicardia e sopro diastólico em foco aórtico","D":"taquicardia e sopro sistólico em foco mitral","E":"bradicardia e sopro diastólico em foco mitral"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-53539","number":"53539","sourceNumber":"53539","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Qual o fármaco de escolha para o tratamento dos sintomas dolorosos da osteoartrite?","options":{"A":"Prednisona.","B":"Colchicina.","C":"Paracetamol.","D":"Naproxeno.","E":"Nenhuma das alternativas acima."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-48842","number":"48842","sourceNumber":"48842","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma criança de 18 meses é trazida à emergência devido à febre, irritabilidade e recusa\nem mover a sua perna esquerda. O exame\nclínico mostra que o joelho esquerdo apresenta-se\nedemaciado, com intensos sinais flogísticos. Há resistência à movimentação passiva da articulação.\nA principal hipótese diagnóstica é de artrite séptica. Dos exames abaixo, o mais importante para\nconfirmar o diagnóstico é:","options":{"A":"Cintilografia óssea.","B":"Radiografia simples do joelho.","C":"Exame do líquido articular.","D":"Hemograma completo e VHS.","E":"Hemocultura."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-51033","number":"51033","sourceNumber":"51033","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Valquíria, 12 anos, com história de tonsilite palatina estreptocócica ocorrida há algumas\nsemanas, vem à UBS com queixa de erupção cutânea macular eritematosa em distribuição de\n\"maiô de banho\". Das características distintivas abaixo, qual é necessária para se estabelecer o\ndiagnóstico de febre reumática?","options":{"A":"velocidade de hemossedimentação elevada.","B":"leucocitose.","C":"poliartrite migratória.","D":"intervalo PR prolongado no eletrocardiograma.","E":"temperatura corporal maior que 38,2°C."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-49009","number":"49009","sourceNumber":"49009","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A artrite reumatoide é uma doença inflamatória crônica e acomete cerca de 0,5 a 1% da\npopulação mundial. A associação entre esta doença, esplenomegalia e neutropenia é denominada\nde:","options":{"A":"Síndrome de Sjögren.","B":"Doença de Still.","C":"Síndrome de Felty.","D":"Doença de Behçet.","E":"Síndrome de Kaplan."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-53614","number":"53614","sourceNumber":"53614","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Breno, 3 anos, apresenta episódios febris vespertinos há 30 dias. Mãe nota que,\ndurante os picos febris, a criança tem dores\nnos tornozelos e punhos, manchas avermelhadas no\ntronco e apatia. Ao exame, está afebril, hipocorado e com hepatoesplenomegalia; sinais flogísticos\nsão notados em tornozelos e punhos. Hemoglobina: 7 g/dl; leve leucocitose com predomínio de\nneutrófilos; trombocitose; VSG e proteína C-reativa fortemente elevados. Radiogramas das\narticulações afetadas evidenciam aumento de partes moles sem erosões. Ecocardiografia normal.\nQual é a hipótese diagnóstica mais provável?","options":{"A":"Febre reumática aguda.","B":"Artrite estafilocócica.","C":"Artrite idiopática da infância, forma sistêmica.","D":"Artrite reativa a estreptococo.","E":"Leucemia linfocítica aguda."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-35621","number":"35621","sourceNumber":"35621","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher de 29 anos apresenta quadro de poliartralgia migratória e febre que evoluiu para\ntenosinovite de cotovelo direito caracterizada por dor, edema e eritema periarticular. Houve\ntambém, aparecimento de pápulas eritematosas e algumas vesículas em região palmar. O\ntratamento empírico mais indicado é a introdução de:","options":{"A":"Aciclovir.","B":"Prednisona.","C":"Indometacina.","D":"Ceftriaxone.","E":"Vancomicina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-34043","number":"34043","sourceNumber":"34043","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A gota é uma doença caracterizada pela deposição intra-articular de cristais. Nessa\ndoença:","options":{"A":"A colchicina é utilizada no tratamento para inibir a\nxantina-oxidase, bloqueando assim a síntese de ácido úrico.","B":"A fase crônica cursa com lesões líticas ósseas periarticulares, visualizadas por métodos de\nimagem como mordedura de rato.","C":"Os cristais de ácido úrico, quando visualizados por microscópio de luz polarizada, apresentam\nbirrefringência fortemente positiva.","D":"Os agentes hipouricemiantes, tais como o alopurinol e o febuxostat, inibem a reabsorção de\nácido úrico nos túbulos renais proximais."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-35865","number":"35865","sourceNumber":"35865","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Adolescente de 15 anos com diagnóstico de febre reumática, apresenta como sequela\nda cardite, insuficiência mitral leve. Em\nrelação à profilaxia secundária, é correto afirmar que:","options":{"A":"Realizar penicilina benzatina de 21 em 21 dias até 21 anos ou 5 anos após o último surto,\nvalendo o que cobrir maior período.","B":"Realizar penicilina benzatina de 21 em 21 dias até 25 anos ou 10 anos após o último surto,\nvalendo o que cobrir maior período.","C":"Realizar penicilina benzatina de 21 em 21 dias até os 40 anos.","D":"Realizar penicilina benzatina de 21 em 21 dias até 21 anos ou 10 anos após o último surto,\nvalendo o que cobrir maior período.","E":"Nenhuma correta."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-35604","number":"35604","sourceNumber":"35604","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Menino de 10 anos de idade dá entrada em Unidade de Terapia Intensiva com história\nde febre alta e mialgia generalizada há 4\ndias, queda do estado geral progressiva e quadro de\nconfusão mental nas últimas 12 horas. Ao exame físico: temperatura 39,5°C, toxemiado, hipotenso,\ntaquicárdico. Apresentando rigidez de nuca e estertoração crepitante em terço médio de pulmão\ndireito e base do hemitórax esquerdo. Há lesão purulenta, com sinais inflamatórios, em tornozelo\ndireito. Os pais referem que há 8 dias o paciente caiu da bicicleta e machucou o tornozelo. A\nconduta inicial neste caso deve ser:","options":{"A":"Debridamento do foco infecioso, metronidazol por via oral e soro antitetânico ou imunoglobulina\nhumana antitetânica por via intramuscular.","B":"Colheita de sangue para cultura, realização de ecocardiograma e introdução de penicilina\ncristalina e gentamicina, por via endovenosa.","C":"Colheita de sangue, líquor e material da lesão para cultura e introdução de oxacilina por via\nendovenosa.","D":"Debridamento do foco infeccioso com colheita de material para cultura, introdução de penicilina\ncristalina por via endovenosa e aguardar\nresultado da cultura para introdução de antitoxina tetânica.","E":"Isolamento do paciente, colheita de sangue e líquor para cultura, introdução de cefalosporina de\n3ª geração por via endovenosa e receita de\nantibióticos para os comunicantes domiciliares."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-34065","number":"34065","sourceNumber":"34065","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Na febre reumática:","options":{"A":"os nódulos subcutâneos são comuns e costumam acompanhar os casos de cardite.","B":"a artrite característica é a poliartrite migratória que envolve grandes e, mais raramente,\npequenas articulações.","C":"a coreia é uma manifestação precoce e desaparece após o início do tratamento.","D":"a válvula mais frequentemente lesada é a tricúspide."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-23032","number":"23032","sourceNumber":"23032","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente do sexo masculino, 25 anos, comparece ao ambulatório com queixa de\ndor lombar, bilateral, com irradiação para raiz das coxas, de início há quatro meses. Refere que\nacorda durante a noite pela dor e, quando caminha, a dor melhora. Qual a principal hipótese\ndiagnóstica para esse caso?","options":{"A":"Osteoma osteoide.","B":"Hérnia discal.","C":"Doença degenerativa discal.","D":"Espondilite anquilosante."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-27141","number":"27141","sourceNumber":"27141","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"São características radiográficas da osteoartrose, exceto:","options":{"A":"Estreitamento simétrica do espaço articular","B":"Esclerose subcondral","C":"Formação de osteófitos","D":"Cistos subcondrais","E":"Ausência de osteopenia peri-articular"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-10662","number":"10662","sourceNumber":"10662","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um homem de 35 anos apresenta episódio autolimitado de diarreia, surgindo, algumas\nsemanas depois, um quadro de poliartrite assimétrica de membros inferiores, dáctil e nos\npododáctilos, tendinite do aquileu, lesões superficiais, eritematosas e indolores no pênis.\n\nConstata-se que apresenta também uma sacroileíte assintomática e conjuntivite bilateral. Um\nexame de sangue mostra HLA-B27. O diagnóstico\nprovável deste caso é:","options":{"A":"Doença de Behçet.","B":"Reumatismo palindrômico.","C":"Doença de Whipple.","D":"Espondilite anquilosante.","E":"Síndrome de Reiter."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-11075","number":"11075","sourceNumber":"11075","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"São sinais radiológicos precoces da artrite reumatoide, exceto:","options":{"A":"Edema de tecidos moles Periarticulares","B":"Osteopenia periarticular","C":"Erosões marginais","D":"Fusão de ossos do carpo","E":"Erosões do processo estiloide ulnar"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-11106","number":"11106","sourceNumber":"11106","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"São achados radiológicos clássicos da gota, exceto:","options":{"A":"Erosões ósseas bem definidas ou em saca-bocado","B":"Espaço articular preservado","C":"Ausência de osteopenia","D":"Bursite olecraniana bilateral","E":"Distribuição simétrica em mãos e pés"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-9354","number":"9354","sourceNumber":"9354","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Na artrite reumatoide:","options":{"A":"as articulações mais acometidas nos membros superiores são as dos punhos, as\nmetacarpofalangeanas e as interfalangeanas distais.","B":"a artrite de cotovelo é um achado frequente, sendo comum quadro doloroso bastante\nexpressivo.","C":"a compressão medular e a morte súbita podem ocorrer como consequência da subluxação\natlantoaxial.","D":"a manifestação ocular mais comum é a escleromalácia perfurante."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-10692","number":"10692","sourceNumber":"10692","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente do sexo feminino, 7 anos de idade, com história de artrite em joelho e punho\nesquerdo, tornozelo direito há sete dias. Com duração de três dias em cada articulação. Há dois\ndias apresenta dor precordial e cansaço aos grandes esforços. Nega antecedente infeccioso. Ao\nexame apresenta de positivo: taquicardia (130 bpm) sopro holosistólico em foco mitral com\nirradiação para a axila e artrite em tornozelo direito. Qual o diagnóstico mais provável?","options":{"A":"Endocardite infecciosa.","B":"Artrite reumatoide juvenil.","C":"Doença de Kawasaki.","D":"Febre reumática.","E":"Mixoma atrial."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-11052","number":"11052","sourceNumber":"11052","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Menino, 8 anos, negro, há 5 dias com aumento do volume, calor, vermelhidão e dor\nintensa no joelho direito que dificultam a\ndeambulação, acompanhados de febre há dois dias. Joga\nfutebol diariamente, mas nega traumatismo. Antecedente de pneumonia aos sete anos de idade.\n\nExame físico: estado geral satisfatório, toxemiado, T 38,7°C, tecido celular subcutâneo escasso,\nlinfoadenomegalia inguinal bilateral, escoriações e hematomas em pernas e muita dor à\nmovimentação. A hipótese diagnóstica e a conduta são:","options":{"A":"Artrite tuberculosa, radiografia de tórax","B":"Artrite séptica, punção articular","C":"Artrite isquêmica, prova de faleização","D":"Artrite reumatoide, pesquisa de fator reumatoide","E":"Artrite traumática; radiografia simples do joelho"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-9314","number":"9314","sourceNumber":"9314","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A artrite da febre reumática:","options":{"A":"compromete as pequenas articulações em 20% a 40% dos casos.","B":"tem resposta pouco satisfatória ao uso dos anti-inflamatórios não hormonais.","C":"dura de cinco a dez dias em cada articulação.","D":"tem início uma a três semanas após infecção de orofaringe pelo estreptococo beta-hemolítico do\ngrupo A."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-274007","number":"274007","sourceNumber":"274007","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"O uso da adrenalina na parada cardiorrespiratória tem como objetivo principal:","options":{"A":"Aumentar a pressão diastólica e automaticidade miocárdica melhorando a perfusão renal.","B":"Restabelecer a circulação espontânea e melhorar a sobrevida pós-parada cardíaca.","C":"Aumentar o consumo de oxigênio pelo miocárdio e, assim, restabelecer o débito cardíaco.","D":"Restabelecer a circulação espontânea através do aumento da pressão de perfusão coronária e\nmanter a perfusão cerebral."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-250228","number":"250228","sourceNumber":"250228","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente 65 anos, avaliado em consulta ambulatorial, apresenta antecedente de\nacidente vascular encefálico isquêmico e fibrilação atrial. Previamente hipertenso e com doença\nvascular periférica. Exames laboratoriais: creatinina: 1,1 mg/dl, hemoglobina: 12 g/dl, plaquetas:\n260.000/mm³, ecocardiograma: estenose mitral moderada a grave. Com base nas informações,\nassinale a alternativa CORRETA:","options":{"A":"Está indicada a anticoagulação com antagonistas da vitamina K.","B":"A rivaroxabana 20 mg é o anticoagulante de escolha.","C":"Está indicado o uso de dupla antiagregação: aspirina 100 mg e clopidogrel 75 mg.","D":"Não está indicado o uso de terapia antiagregante ou anticoagulante nesse caso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-216386","number":"216386","sourceNumber":"216386","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 35 anos, sexo feminino, apresentando queixa de palpitações há alguns\ndias. História pregressa de febre reumática. À\nausculta, ritmo cardíaco irregular. Realizado ECG\nque mostrou: QRS estreito, intervalos R-R variáveis e ausência de onda P identificável. A arritmia\nMAIS PROVÁVEL para essa paciente é:","options":{"A":"Flutter atrial.","B":"Fibrilação atrial.","C":"Taquicardia por reentrada nodal atrioventricular.","D":"Taquicardia ortodrômica por via acessória."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-176131","number":"176131","sourceNumber":"176131","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"As arritmias cardíacas são decorrentes, basicamente, de alterações na geração do\nimpulso (automatismo anormal e atividade deflagrada) e/ou na condução do impulso (reentrada).\nSobre os principais mecanismos de taquiarritmia mais prevalentes na população pediátrica, sua\nclassificação e tratamento, podemos afirmar, EXCETO:","options":{"A":"As células miocárdicas atriais e ventriculares normalmente não apresentam atividade de\nmarca-passo.","B":"A reentrada é o mecanismo gerador de taquiarritmias supraventriculares e ventriculares mais\nfrequente e relevante, podendo ser anatômica ou funcional.","C":"As arritmias cardíacas podem ser classificadas quanto à repercussão clínica em estável ou\ninstável.","D":"A distinção entre taquicardia supraventricular e taquicardia ventricular é de fundamental\nimportância, não somente para a reversão aguda, mas para adoção de estratégias para a\nprevenção de recorrências em longo prazo.","E":"Cicatrizes (fibrose) miocárdicas secundárias à cardiopatia estrutural não favorecem o\ndesenvolvimento de reentrada."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-155255","number":"155255","sourceNumber":"155255","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre a Fibrilação Atrial é correto afirmar, EXCETO:","options":{"A":"Essa arritmia se apresenta obrigatoriamente com taquicardia.","B":"Os pacientes com fibrilação atrial, mesmo quando paroxística, podem ter indicação para\nanticoagulação, mantida indefinidamente naqueles\nsem contraindicação e com pelo menos um fator\nde risco CHADS2","C":"É a arritmia crônica mais comum, com incidência e prevalência que aumentam com a idade.","D":"Um paciente masculino, 60 anos, diabético, portador de fibrilação atrial, sem outras\ncomorbidades, poderá trocar a anticoagulação oral pelo AAS.","E":"A rivaroxabana foi aprovada para anticoagulação em pacientes com fibrilação atrial não valvar."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-155261","number":"155261","sourceNumber":"155261","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mãe traz à emergência criança de 6 meses com queixa de irritabilidade há dois dias,\nvômitos, recusa alimentar e cansaço que piorou nas últimas 12 horas associada à palidez. Ao\nexame físico, é observado desconforto respiratório, pulsos finos, gemência, tiragem inter e\nsubcostal. Paciente é colocado com máscara de oxigênio não reinalante a 10 litros/min e\nmonitorizado. Observado no monitor ritmo cardíaco sem onda p, duração do QRS de 70ms,\nfrequência cardíaca de 260 bpm, sem variações durante todo o atendimento. Qual a medida MAIS\nADEQUADA para restabelecer a estabilidade hemodinâmica desse paciente?","options":{"A":"Adenosina - 0,1 mg/kg máximo 6mg.","B":"Cardioversão elétrica - Choque inicial de 0,5 a 1 J/kg.","C":"Amiodarona - 5mg/kg EV.","D":"Cardioversão elétrica - Choque inicial de 2J/kg.","E":"Procainamida - 15mg/kg."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-105686","number":"105686","sourceNumber":"105686","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, portadora de artrite reumatoide, em tratamento crônico com metotrexato,\npoderá reduzir a toxicidade do tratamento,\nfazendo uso coadjuvante da seguinte vitamina:","options":{"A":"Piridoxina.","B":"Vitamina B12.","C":"Ácido fólico.","D":"Tiamina.","E":"Vitamina E."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-80896","number":"80896","sourceNumber":"80896","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A febre reumática continua sendo a principal causa de cardiopatia adquirida em\nadolescentes e adultos jovens. Em relação a essa cardiopatia, é CORRETO afirmar:","options":{"A":"A cardite reumática ocorre somente na fase aguda da febre reumática.","B":"A pericardite reumática aguda comumente evolui com derrame pericárdico volumoso e risco de\ntamponamento cardíaco.","C":"A lesão valvar é o principal marco da cardite reumática, sendo a valva mitral a mais acometida.","D":"A profilaxia secundária para febre reumática com cardite sem sequela valvar deve durar até os\n40 anos.","E":"O comprometimento isolado da valva aórtica é a manifestação mais comum."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-62662","number":"62662","sourceNumber":"62662","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Em relação à Artrite Reumatoide, é correto afirmar, EXCETO:","options":{"A":"Pacientes com atividade moderada de doença apresentam entre 6 e 20 articulações\ncomprometidas e provas de atividade inflamatórias aumentadas.","B":"Metotrexato é comumente selecionado como terapia para pacientes com atividade moderada de\ndoença.","C":"Os agentes anti-TNF são contraindicados em pacientes com risco de reativação de tuberculose,\na menos que sejam previamente tratados.","D":"Altos títulos de fator reumatoide, nódulos reumatoides e comprometimento extra-articular não\nestão relacionados a mau prognóstico.","E":"Corticoide intra-articular pode ser usado para controle de sinovite."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-35745","number":"35745","sourceNumber":"35745","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um jovem de 18 anos, masculino, desenvolveu calafrios, febre e edema articular\ndoloroso unilateral. Qual teste seria mais apropriado, a fim de ajudar a fazer o diagnóstico?","options":{"A":"Cultura de líquido sinovial do joelho afetado.","B":"Teste da doença de Lyme.","C":"Ressonância magnética.","D":"Eletroforese de proteínas séricas.","E":"Estudo de cristais na membrana sinovial."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-35728","number":"35728","sourceNumber":"35728","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A avaliação laboratorial dos processos inflamatórios, por meio das proteínas de fase\naguda é corriqueira na prática diária dos reumatologistas. Sobre as proteínas de fase aguda é\nCORRETO afirmar:","options":{"A":"As proteínas de fase aguda são produzidas pelos miócitos;","B":"Após um estímulo inflamatório agudo a concentração da proteína C reativa pode elevar-se\nrapidamente, em picos sem qualquer relação com a gravidade da lesão tecidual;","C":"A medida da velocidade de hemossedimentação avalia, de uma maneira indireta, a\nconcentração plasmática de fibrinogênio;","D":"A velocidade de hemossedimentação e a proteína C reativa distinguem a artrite reumatoide da\nfebre reumática;","E":"A alfa 1 glicoproteína ácida é um dos componentes da proteína C reativa, e tem sido usada no\nacompanhamento da atividade inflamatória dos pacientes com febre reumática aguda."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-35741","number":"35741","sourceNumber":"35741","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Qual afirmação é VERDADEIRA?","options":{"A":"A dosagem de ácido úrico sérico normal durante um episódio de monoartrite aguda afasta o\ndiagnóstico de gota;","B":"Os cristais de monourato de sódio, à microscopia de luz polarizada, têm birrefringência positiva\nforte, assemelhando-se a uma agulha;","C":"Osteoporose periarticular, erosões ósseas e redução do espaço articular são alterações\nradiológicas que podem ser encontradas na gota de evolução mais prolongada;","D":"Na vigência da crise aguda de gota deve se iniciar o uso de colchicina e de alopurinol;","E":"Os uricosúricos estão indicados nos pacientes com excreção urinária de urato maior que 1.000\nmg em 24 horas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-35732","number":"35732","sourceNumber":"35732","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A Febre Reumática Aguda (FR) é uma reação tardia a uma infecção faríngea não\nsupurativa por estreptococos do grupo A de Lancifield. No Brasil constitui um problema sério de\nsaúde pública. Das opções abaixo, qual corresponde à CORRETA:","options":{"A":"A Coreia Sydenham é uma manifestação do envolvimento dos gânglios da base do SNC e\nocorre em 15% dos pacientes com FR.","B":"A cardite aguda é a manifestação mais comum da FR e possui alta taxa de morbidade e\nmortalidade.","C":"Nódulos subcutâneos são comuns, apresentam-se indolores, endurecidos, móveis, localizados\nnas superfícies extensoras das articulações.","D":"A profilaxia secundária com Penicilina Benzatina a cada quatro semanas previne recorrências da\ndoença e reduz a gravidade da cardiopatia\nresidual.","E":"As Sulfonamidas devem ser recomendadas para o tratamento da faringoamigdalite\nestreptocócia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-28293","number":"28293","sourceNumber":"28293","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Analise os itens abaixo sobre as doenças por deposição de cristais: I - A gota decorre\nde um estado de aumento nos níveis de ácido\núrico que acarreta a formação de cristais de\nmonourato de sódio em diversos tecidos, destacando-se, pela frequência, as articulações, as\nestruturas periarticulares, os rins e o subcutâneo. II - Na gota, na análise do líquido sinovial,\nencontramos: presença de cristais de monourato de sódio, extra e intracelular. Esses cristais são\nfinos e têm pontas afiladas com birrefringência negativa à luz polarizada. Também detectamos\npresença de polimorfonucleares em grande quantidade na fase aguda. III - A gota caracteriza-se\npor elevação persistente do nível sérico do ácido úrico. Portanto, no tratamento da crise articular\n(crise de gota) o tratamento da hiperuricemia deve ser imediatamente iniciado para reduzir os níveis\nde ácido úrico e melhorar o processo inflamatório. Está CORRETO o que se afirma em:","options":{"A":"I, II, III.","B":"I e II, apenas.","C":"I e III, apenas.","D":"II e III, apenas.","E":"III apenas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-28263","number":"28263","sourceNumber":"28263","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Escolar de 8 anos, do sexo feminino, apresenta quadro agudo de febre alta, dor e sinais\ninflamatórios em joelho direito e exantema serpiginoso evanescente e não pruriginoso em tronco,\nque piora com o calor. Exames complementares: leucocitose e VHS elevado. Neste caso, a\nhipótese diagnóstica mais provável é:","options":{"A":"Doença de Kawasaki.","B":"Artrite reativa.","C":"Febre reumática.","D":"Lúpus eritematoso.","E":"Artrite reumatoide."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-11499","number":"11499","sourceNumber":"11499","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"É uma Síndrome hipotônica e hipercinética caracterizada por movimentos involuntários,\nrápidos, arrítmicos e incoordenados que desaparecem\ndurante o sono associados à doença\nStreptocócica:","options":{"A":"Cardite Reumática.","B":"Artrite Reumatoide.","C":"Coreia de Sydenham.","D":"Eritema nodoso.","E":"Síndrome de Werning-Hoffman."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-311492","number":"311492","sourceNumber":"311492","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A ocorrência da grave arritmia \"Torsade de Pointes\" está mais frequentemente\nassociada a qual das alterações\neletrocardiográficas abaixo?","options":{"A":"Aumento do intervalo QT.","B":"Fibrilação atrial em paciente com pré-excitação ventricular.","C":"Aparecimento da onda U.","D":"Ausência da onda P de forma variável.","E":"Bloqueio AV 2º grau Mobitz 2."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-218035","number":"218035","sourceNumber":"218035","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente, 67 anos, chega ao pronto-socorro relatando astenia intensa, dispneia e\nsudorese fria aos mínimo esforços e\nsonolência. À admissão apresentava-se hipocorado (+|4+),\nsonolento mas lúcido e orientado em tempo e espaço, freqüência respiratória = 30, oximetria de\npulso = 95%, freqüência cardíaca = 40 batimentos por minuto, pressão arterial = 82 x 61 mmHg,\nedema de membros inferiores. Realizado acesso venoso periférico e ECG abaixo assinalado.Qual o\nprimeira conduta que deverá ser realizada:","options":{"A":"Expansão volêmica.","B":"Uso de noradrenalina.","C":"Marcapasso transvenoso.","D":"Cineangiocoronariográfica com passagem de marcapasso transvenoso.","E":"Uso de atropina 0,5 mg endovenoso."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-177550","number":"177550","sourceNumber":"177550","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente de 42 anos, portador de cardiomiopatia dilatada idiopática, interna na UTI com\nsepse de foco pulmonar, apresentando\ntaquidispneia, edema de membros inferiores e\nhiperlactatemia. É dada sequência ao pacote de 6h para sepse, já previamente iniciada na\nemergência, mas, 2h depois, o paciente evolui com perda de consciência e sem pulso detectável\nao longo de 10''. O monitor mostra o ritmo abaixo: São iniciadas as manobras de ressuscitação\ncardiopulmonar, incluindo compressões torácicas na frequência de 100-120min e ventilação\n\nbolsa-válvula-máscara. Em menos de um minuto, o desfibrilador chega ao local da intercorrência. A\nmelhor sequência de condutas a partir daí é:","options":{"A":"Manter a RCP até que se conclua o ciclo de 2 minutos, realizando, em seguida, desfibrilação.","B":"Interromper RCP e promover desfibrilação imediata, checando em seguida o ritmo e o pulso.\n\nCaso persista ritmo chocável, promover novamente desfibrilação.","C":"Interromper RCP e promover cardioversão sincronizada, checando em seguida o ritmo e o pulso.\n\nCaso persista o ritmo, cardioverter novamente com carga maior.","D":"Interromper RCP e promover desfibrilação imediata, reiniciando em seguida as manobras de\nressuscitação por 2 minutos.","E":"Discutir os 5H5T com a equipe e, havendo suspeita de hipóxia ou ventilação insuficiente via\nbolsa-válvula-máscara, promover intubação orotraqueal."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-160454","number":"160454","sourceNumber":"160454","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma mulher de 45 anos é portadora de estenose mitral de origem reumática e faz uso\nde atenolol. Apresenta-se em classe funcional\nII. O ecocardiograma transesofágico mostra área\nvalvar mitral de 0,9 cm², com boa morfologia e insuficiência mitral mínima, ausência de trombos no\nátrio esquerdo; diâmetro e função sistólica do VE preservados. O ritmo no ECG é de fibrilação\natrial. Sobre a profilaxia dos fenômenos tromboembólicos, a conduta mais apropriada é prescrever:","options":{"A":"Varfarina, com alvo de INR entre 2,5 e 3,5.","B":"Dabigatrana ou rivaroxabana, sem necessidade de ajuste do INR.","C":"Varfarina, com alvo de INR entre 2,0 e 3,0.","D":"Ácido acetilsalicílico associado à varfarina, com alvo de INR entre 2,0 e 3,0.","E":"Ácido acetilsalicílico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-160437","number":"160437","sourceNumber":"160437","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Uma senhora de 80 anos, no 2º dia de pós-operatório de artroplastia de quadril,\napresenta dispneia súbita. O médico plantonista\ndemora 30 minutos para chegar e, ao abordar a\npaciente, observa que ela está \"não responsiva\" e sem respiração. Com base nas recomendações\ndo suporte avançado de vida do adulto (ACLS), da American Heart Association, a próxima conduta\ndeve ser:","options":{"A":"Checar pulso carotídeo.","B":"Pedir ajuda e para trazerem desfibrilador.","C":"Realizar um soco precordial.","D":"Administrar 1 mg epinefrina.","E":"Abrir as vias aéreas e fornecer duas ventilações."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-132755","number":"132755","sourceNumber":"132755","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Mulher de 41 anos, comparece a Unidade Básica de Saúde (UBS) para consulta\nmédica com história de cinco meses de\nmal-estar e rigidez de mãos matinal que melhora ao longo\ndo dia. Refere ainda que as duas mãos estão comprometidas na altura dos pulsos. Os testes\nlaboratoriais iniciais mostram VHS elevado e anti-CCP altamente positivo. Qual dos seguintes\ntratamentos tem maior probabilidade de levar ao melhor resultado em longo prazo para essa\npaciente?","options":{"A":"Ceftriaxona intravenosa.","B":"Metotrexato.","C":"Naproxeno.","D":"Alopurinol.","E":"Ibuprofeno."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-132765","number":"132765","sourceNumber":"132765","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente feminino, 31 anos, refere que há cerca de quarenta dias iniciou quadro de dor\nde garganta e dificuldade para deglutir que\nfoi tratado com azitromicina, sem melhora. Uma semana\napós, iniciou quadro de febre diária no final da tarde, geralmente em torno de 40°C, acompanhada\nde sudorese e calafrios e que cedia, mesmo sem uso de analgésicos. Refere ainda mialgia e a\npresença de um rash evanescente, cor de salmão, não pruriginoso, em tórax e abdome, que\naparece apenas durante os episódios febris. Ao exame físico, apresenta adenomegalia difusa e\nhepatoesplenomegalia. Laboratório mostrou neutrofilia importante (em torno de 30.000/mm³), FR e\nFAN negativos, elevação discreta de enzimas hepáticas, elevação muito acentuada da ferritina. O\ndiagnóstico mais provável é de:","options":{"A":"Linfoma não Hodgkin.","B":"Leucemia mieloide.","C":"Doença de Still.","D":"Mononucleose Infecciosa.","E":"Citomegalovirose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-132808","number":"132808","sourceNumber":"132808","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre o tratamento da artrite gotosa, assinale a afirmativa INCORRETA:","options":{"A":"Durante o tratamento do ataque agudo, deve-se priorizar o uso de AINEs e corticoides, podendo\ntambém iniciar colchicina e alopurinol para aqueles que ainda não estiverem em uso dos mesmos.","B":"O uso de Probenecida é aceitável em substituição ou adição aos inibidores da xantina oxidase\nno tratamento crônico, tendo como principal\nefeito colateral a nefrolitíase.","C":"A colchicina está indicada, tanto na artrite gotosa aguda, quanto na crônica. Seus efeitos\ncolaterais mais comuns são diarreia e náuseas. Deve-se sempre avaliar necessidade de\nmodificação da dose em pacientes com disfunção renal.","D":"Reações de hipersensibilidade ocorrem em cerca de 2% dos pacientes em uso de Alopurinol.\n\nExiste maior risco de tais reações em pacientes renais crônicos e em uso de tiazídicos.","E":"Consumo excessivo de álcool deve ser evitado. O consumo de cerveja parece conferir um risco\nmaior de gota do que whisky ou vinho."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-132798","number":"132798","sourceNumber":"132798","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Na avaliação diagnóstica da febre reumática, os Critérios de Jones (1941) modificados\nem 1992, são considerados o \"padrão ouro\",\nporém há necessidade de uma cominação de critérios\npara que o diagnóstico seja considerado, e esta combinação está melhor descrita na alternativa:","options":{"A":"Febre, artralgia e epistaxe.","B":"Artralgia, epistaxe e coreia de Huntington.","C":"Eritema nodoso, artrite e dor abdominal.","D":"Poliartrite migratória, eritema marginado e febre.","E":"Dor abdominal, infecção de orofaringe e artrite."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-132837","number":"132837","sourceNumber":"132837","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Menina de 12 anos trazida pela mãe ao pronto-socorro com queixa de labilidade\nemocional há algumas semanas, mãe tem notado\nque criança passa do choro ao riso muito rápido,\na professora na escola queixou-se de que as últimas provas foram muito difíceis de serem\ncorrigidas porque a letra da criança não estava tão legível quanto antes e havia traços fora das\npautas do caderno, como se fossem riscos aleatórios. A mãe recorda-se de que há mais de 2\nsemanas, a menina apresentou um quadro de infecção amigdaliana, que foi tratada com\n\nanti-inflamatório (sic). Qual o diagnóstico mais provável?","options":{"A":"Esquizofrenia.","B":"Febre reumática.","C":"Coreia de Huntington.","D":"Amigdalite bacteriana.","E":"Nenhuma das alternativas anteriores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-103907","number":"103907","sourceNumber":"103907","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Qual das seguintes articulações é tipicamente poupada na osteoartrite?","options":{"A":"Coluna cervical.","B":"Tornozelo.","C":"Articulação interfalangeana distal.","D":"Quadril.","E":"Joelho."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-108040","number":"108040","sourceNumber":"108040","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Pelos novos critérios de classificação para artrite reumatoide (ACR/EULAR, 2010), é\nmenos importante para o diagnóstico:","options":{"A":"Artrite de pequenas articulações.","B":"Artrite de grandes articulações.","C":"Alterações radiográficas compatíveis.","D":"Anticorpo antiproteína citrulinada em baixo título.","E":"Anticorpo antiproteína citrulinada em alto título."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-89286","number":"89286","sourceNumber":"89286","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Com relação à artrite séptica, não é possível afirmar:","options":{"A":"A incidência é muito maior em pacientes com artrite reumatoide.","B":"Os principais fatores predisponentes são dano articular prévio e presença de prótese articular.","C":"Em adultos, o quadril é a articulação mais envolvida.","D":"Na análise do líquido sinovial, inicialmente a bacterioscopia é a avaliação de maior importância\npara identificar algum microrganismo.","E":"Cerca de 50% das artrites não gonocócicas têm hemoculturas positivas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-52185","number":"52185","sourceNumber":"52185","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"A Coreia de Sydenham é uma manifestação da febre reumática que aparece:","options":{"A":"Acompanhante de cardite","B":"Sozinha na maioria dos casos","C":"Acompanhada de artrite","D":"Em crianças maiores de 15 anos","E":"Manifesta-se associada à artrite reumatoide"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-52188","number":"52188","sourceNumber":"52188","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Qual o cristal responsável pelo processo inflamatório na pseudogota?","options":{"A":"Monourato de sódio","B":"Colesterol","C":"Oxalato de cálcio","D":"Pirofosfato de cálcio","E":"Apatita"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-52439","number":"52439","sourceNumber":"52439","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Menina de sete anos com história de febre associada à artrite em tornozelo esquerdo\ndurante quatro dias, seguida de artrite em\njoelho direito por cinco dias, seguida de artrite em punho\ndireito por três dias, evoluindo com tosse seca e dispneia aos médios esforços há 48 horas. Relata\nainda episódio de dor de garganta três semanas antes do início do quadro articular. Ao exame\nobserva-se taquipneia, taquicardia, hepatomegalia, sopro sistólico (4+/6+) em foco mitral com\nirradiação para axila e artrite em punho direito. É CORRETO afirmar:","options":{"A":"Coreia, nódulos subcutâneos e eritema multiforme são manifestações clínicas maiores que\npodem ser\n\nobservadas.","B":"Os marcadores de fase aguda (VSH e proteína C-reativa) apresentam fiel relação com a\natividade da\n\ndoença e não sofrem influência do uso de medicações.","C":"O período de latência (da instalação da faringite estreptocócica até o início do quadro clínico)\nda\ndoença pode variar de duas semanas até seis\nmeses.","D":"Pode ser observada alteração eletrocardiográfica como o aumento do intervalo PR.","E":"A evidência de infecção prévia por estreptococo do grupo A pode ser confirmada apenas por\ncultura de orofaringe positiva."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-52469","number":"52469","sourceNumber":"52469","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Sobre a doença reumática, assinale a alternativa incorreta:","options":{"A":"Fatores ambientais e socioeconômicos contribuem para o aparecimento da doença, assim como\nfatores genéticos de suscetibilidade à doença estão diretamente relacionados ao desenvolvimento\nda FR e de suas sequelas","B":"O diagnóstico da febre reumática é clínico, não existindo sinal patognomônico ou exame\nespecífico","C":"O acometimento do pericárdico não é comum, não ocorre isoladamente e não resulta em\nconstrição","D":"A artrite é, em geral, muito dolorosa e mostra sinais inflamatórios intensos ao exame físico. A\nresposta aos anti-inflamatórios não hormonais é lenta e a dor desaparece em dois a três dias","E":"A ausência de sopro não afasta a possibilidade de comprometimento cardíaco"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-330851","number":"330851","sourceNumber":"330851","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Paciente masculino, 60 anos, tem PA = 140x85 mmHg e pesa 98 kg. Relata que não\nestá se sentindo bem, seu ECG não tem onda\nP, com FC = 44 bpm e os complexos QRS ocorrem\nregularmente. Qual o diagnóstico para essa condição?","options":{"A":"Bloqueio atrioventricular de segundo grau.","B":"Bloqueio atrioventricular avançado.","C":"Bloqueio sinoatrial de segundo grau.","D":"Bloqueio sinoatrial de terceiro grau."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-316002","number":"316002","sourceNumber":"316002","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Um paciente de 58 anos, com antecedente de hipertensão arterial sistêmica e diabetes\nmellitus, em uso de enalapril, hidroclorotiazida e metformina, vem apresentando episódios de perda\nde consciência com períodos intercrise cada vez menores. Há relatos de ser visto vígil, e,\nsubitamente, apresentou perda total da consciência, sem pródromos, caindo da própria altura sem\ndefesa. Ao recobrar o nível neurológico, alguns segundos após o evento, costuma apresentar-se\ndiscretamente confuso e desorientado. Assinale a alternativa que contempla a hipótese diagnóstica\ncorreta:","options":{"A":"Sincope cardiogênica","B":"Lipotimia por hipertensão","C":"Sincope neuromediada","D":"Pré-sincope por hipoglicemia","E":"Sincope por crise convulsiva"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-316003","number":"316003","sourceNumber":"316003","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Durante culto em ambiente fechado, uma menina de 14 anos sente \"tonturas\" e \"perda\nde visão\", seguidas de perda de consciência. A\npaciente tentou se agarrar nos familiares e teve\numa queda lenta. O quadro foi acompanhado de tremor, sudorese, palidez, taquicardia e vômitos. A\nadolescente refere que se lembra vagamente dos fatos e que já apresentou 8 episódios, com\ncompleta recuperação após as crises. O tilt test foi positivo. Assinale a alternativa que apresenta\no\ndiagnóstico clínico mais provável e a conduta indicada para profilaxia de outras crises:","options":{"A":"Epilepsia generalizada; ácido valproico","B":"Crise de simulação; orientação psicológica","C":"Sincope vasovagal; dieta rica em sal, aumento da ingestão de líquidos e uso de betabloqueador","D":"Sincope vagal; dieta rica em sal, aumento da ingestão de líquidos e uso de atropina","E":"Somatização (histeria); avaliação psiquiátrica"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-24-313394","number":"313394","sourceNumber":"313394","collectionBlock":"med:med-clinica-medica-med-clm-24","collectionLabel":"MED · MED CLM 24","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 24","subtopic":"","stem":"Lactente, 8 meses, admitido na UPA devido pulso acelerado segundo a mãe. Ao exame\napresenta temperatura 36,4ºC, FR 46 irpm, FC 210 bpm, boa perfusão e normotenso. O traçado no\neletrocardiograma revela QRS estreito, RR regular eonda P ausente. A primeira conduta mais\napropriada deverá ser:","options":{"A":"Compressão do bulbo ocular;","B":"Colocação de gelo na face do lactente;","C":"Cardioversão elétrica sincronizada imediata;","D":"Adenosina iv em bomba de infusão contínua."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 24/MED CLM 24.txt","sourceLabel":"MED · MED CLM 24","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 24","MED"],"answerSource":"explicit","commentDeferred":true}]};
